  const [searchTerm, setSearchTerm] = useState('');
  const [filteredSales, setFilteredSales] = useState(sales);
  const [showFilters, setShowFilters] = useState(false);
  const [filterStartDate, setFilterStartDate] = useState<Date | null>(null);
  const [filterEndDate, setFilterEndDate] = useState<Date | null>(null);

  useEffect(() => {
    let newSales = sales;

    if (searchTerm) {
      newSales = newSales.filter(sale =>
        sale.customer.name.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    if (filterStartDate) {
      newSales = newSales.filter(sale => new Date(sale.date) >= filterStartDate);
    }
    if (filterEndDate) {
      newSales = newSales.filter(sale => new Date(sale.date) <= filterEndDate);
    }

    setFilteredSales(newSales);
  }, [sales, searchTerm, filterStartDate, filterEndDate]);

  const calculateNetSales = () => {
    return filteredSales.reduce((sum, sale) => sum + sale.total, 0);
  };

  const calculateTotalReturns = () => {
    return returns.reduce((sum, ret) => sum + ret.amount, 0);
  };

  const calculateNetProfit = () => {
    return calculateNetSales() - calculateTotalReturns();
  };

