export enum UserRole {
  SUPER_ADMIN = 'SUPER_ADMIN',
  ADMIN = 'ADMIN',
  CASHIER = 'CASHIER',
}

export type Permission = 
  | 'VIEW_DASHBOARD'
  | 'MANAGE_INVENTORY'
  | 'POS'
  | 'VIEW_SALES_HISTORY'
  | 'MANAGE_CUSTOMERS'
  | 'MANAGE_USERS'
  | 'MANAGE_SETTINGS'
  | 'MANAGE_PURCHASE_ORDERS';

export interface User {
  id: string;
  name: string;
  role: UserRole;
  email: string;
  avatar?: string;
  password?: string; // Made optional for types compatibility, but logic will enforce it
  permissions: Permission[];
}

export interface ToastMessage {
