                                                          {item.historyType === 'SALE' && <span className="bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 px-2 py-1 rounded text-xs font-bold">Sale</span>}
                                                          {item.historyType === 'RETURN' && <span className="bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400 px-2 py-1 rounded text-xs font-bold">Return</span>}
                                                          {item.historyType === 'CREDIT' && <span className="bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400 px-2 py-1 rounded text-xs font-bold">Wallet</span>}
                                                      </td>
                                                      <td className="p-4 font-mono text-xs text-slate-500 dark:text-slate-400">
                                                          #{item.id.split('-')[1]}
                                                      </td>
                                                      <td className="p-4 text-slate-600 dark:text-slate-300">
                                                          {item.historyType === 'SALE' && `${item.items.length} items`}
                                                          {item.historyType === 'RETURN' && `Original: #${item.originalSaleId.split('-')[1]}`}
                                                          {item.historyType === 'CREDIT' && item.reason}
                                                      </td>
                                                      <td className="p-4 text-right font-bold text-slate-800 dark:text-white">
                                                          {item.historyType === 'RETURN' ? '-' : ''}{symbol}{item.historyType === 'SALE' ? item.totalAmount.toFixed(2) : item.historyType === 'RETURN' ? item.totalRefund.toFixed(2) : item.amount.toFixed(2)}
                                                      </td>
                                                  </tr>
                                              ))
                                          )}
                                      </tbody>
                                  </table>
                              </div>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Customers;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, StockAdjustment, AdjustmentType, User, ReturnTransaction, Customer, Sale, PriceHistory } from '../types';
import { generateProductDescription, suggestRestock } from '../services/geminiService';
import { Plus, Edit2, Trash2, Search, Wand2, RefreshCw, AlertCircle, AlertTriangle, CheckCircle, ClipboardEdit, History, X, ArrowRight, RotateCcw, ClipboardList, Filter, ArrowUp, ArrowDown, ChevronsUpDown, XCircle, ChevronDown, Check, TrendingUp, DollarSign, BarChart3, Package, Eye, Tags, ArrowBigUp, ArrowBigDown, Printer, FileSpreadsheet, Upload, Image as ImageIcon, ArrowRightLeft, Boxes, Scale, CheckSquare, Layers } from 'lucide-react';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  stockAdjustments: StockAdjustment[];
  onAdjustStock: (adjustment: StockAdjustment) => void;
  onBulkAdjustStock: (adjustments: StockAdjustment[]) => void;
  currentUser: User;
  currency: string;
  showToast: (message: string, type: 'SUCCESS' | 'ERROR' | 'INFO') => void;
  returns: ReturnTransaction[];
  customers: Customer[];
  sales: Sale[];
  priceHistory: PriceHistory[];
  onLogPriceChange: (log: PriceHistory) => void;
}

type SortField = 'name' | 'sku' | 'category' | 'price' | 'stock' | 'stockExpiryDate' | 'cost' | 'margin';
type SortDirection = 'asc' | 'desc';

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, stockAdjustments, onAdjustStock, onBulkAdjustStock, currentUser, currency, showToast, returns, customers, sales, priceHistory, onLogPriceChange }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Search & Filter State
  const [searchTerm, setSearchTerm] = useState('');
  const [isFilterOpen, setIsFilterOpen] = useState(false);
  const [filterCategory, setFilterCategory] = useState('ALL');
  const [filterStockStatus, setFilterStockStatus] = useState<'ALL' | 'LOW' | 'OUT' | 'IN'>('ALL');
  const [filterExpiry, setFilterExpiry] = useState<'ALL' | 'EXPIRED' | 'SOON' | 'VALID'>('ALL');

  // Sorting State
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');

  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [isLoadingAi, setIsLoadingAi] = useState(false);

  // Adjustment State
  const [isAdjModalOpen, setIsAdjModalOpen] = useState(false);
  const [selectedProductForAdj, setSelectedProductForAdj] = useState<Product | null>(null);
  const [adjType, setAdjType] = useState<AdjustmentType>('ADD');
  const [adjQuantity, setAdjQuantity] = useState(0);
  const [adjReason, setAdjReason] = useState('Stock Count Correction');
  const [adjNotes, setAdjNotes] = useState('');

  // Bulk Adjustment State
  const [isBulkAdjModalOpen, setIsBulkAdjModalOpen] = useState(false);
  const [bulkAdjType, setBulkAdjType] = useState<AdjustmentType>('ADD');
  const [bulkAdjQuantity, setBulkAdjQuantity] = useState(0);
  const [bulkAdjReason, setBulkAdjReason] = useState('Stock Count Correction');
  const [bulkAdjNotes, setBulkAdjNotes] = useState('');

  // Conversion State
  const [isConversionModalOpen, setIsConversionModalOpen] = useState(false);
  const [convSourceId, setConvSourceId] = useState('');
  const [convTargetId, setConvTargetId] = useState('');
  const [convSourceQty, setConvSourceQty] = useState(1);
  const [convTargetQty, setConvTargetQty] = useState(1);

  // Detailed View State
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
  const [selectedProductDetails, setSelectedProductDetails] = useState<Product | null>(null);
  const [historyFilterType, setHistoryFilterType] = useState<AdjustmentType | 'ALL'>('ALL');
  const [historyStartDate, setHistoryStartDate] = useState('');
  const [historyEndDate, setHistoryEndDate] = useState('');
  const [historyView, setHistoryView] = useState<'ADJUSTMENTS' | 'RETURNS' | 'PRICE'>('ADJUSTMENTS');

  // Category & Unit Dropdown State
  const [isCategoryDropdownOpen, setIsCategoryDropdownOpen] = useState(false);
  const categoryDropdownRef = useRef<HTMLDivElement>(null);

  const [isUnitDropdownOpen, setIsUnitDropdownOpen] = useState(false);
  const unitDropdownRef = useRef<HTMLDivElement>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false
  });

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  };

  const symbol = getCurrencySymbol(currency);
  const formatCurrency = (val: number) => val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const formatNumber = (val: number) => val.toLocaleString('en-US', { maximumFractionDigits: 3 });

  const categories = useMemo(() => {
      const cats = new Set(products.map(p => p.category).filter(Boolean));
      return ['ALL', ...Array.from(cats).sort()];
  }, [products]);

  // Unique categories for the dropdown (excluding ALL)
  const uniqueCategories = useMemo(() => {
      const cats = new Set(products.map(p => p.category).filter(Boolean));
      return Array.from(cats).sort();
  }, [products]);

  // Unique units for the dropdown
  const uniqueUnits = useMemo(() => {
      const productUnits = new Set(products.map(p => p.unit).filter(Boolean) as string[]);
      const defaultUnits = ['pcs', 'kg', 'g', 'mg', 'l', 'ml', 'box', 'pack', 'sack', 'bottle', 'can', 'jar', 'm', 'cm', 'roll', 'set', 'pair', 'dozen', 'bundle', 'tray'];
      defaultUnits.forEach(u => productUnits.add(u));
      return Array.from(productUnits).sort();
  }, [products]);

  // Total Calculations for Top Cards
  const totalItems = products.reduce((acc, p) => acc + p.stock, 0);
  const totalValueRetail = products.reduce((acc, p) => acc + (p.price * p.stock), 0);
  const totalValueCost = products.reduce((acc, p) => acc + (p.cost * p.stock), 0);

  // Click outside to close dropdowns
  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (categoryDropdownRef.current && !categoryDropdownRef.current.contains(event.target as Node)) {
              setIsCategoryDropdownOpen(false);
          }
          if (unitDropdownRef.current && !unitDropdownRef.current.contains(event.target as Node)) {
              setIsUnitDropdownOpen(false);
          }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleOpenModal = (product?: Product) => {
    if (product) {
      setEditingProduct(product);
      setFormData(product);
    } else {
      setEditingProduct(null);
      setFormData({
         name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false
      });
    }
    setIsModalOpen(true);
    setIsCategoryDropdownOpen(false);
    setIsUnitDropdownOpen(false);
  };

  const handleOpenAdjModal = (product: Product) => {
      setSelectedProductForAdj(product);
      setAdjType('ADD');
      setAdjQuantity(0);
      setAdjReason('Stock Count Correction');
      setAdjNotes('');
      setIsAdjModalOpen(true);
  }

  const handleOpenConversionModal = () => {
      setConvSourceId('');
      setConvTargetId('');
      setConvSourceQty(1);
      setConvTargetQty(1);
      setIsConversionModalOpen(true);
  };

  const handleOpenDetails = (product: Product) => {
      setSelectedProductDetails(product);
      // Reset filters & view
      setHistoryFilterType('ALL');
      setHistoryStartDate('');
      setHistoryEndDate('');
      setHistoryView('ADJUSTMENTS');
      setIsDetailsModalOpen(true);
  }

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) { // 2MB Limit
         showToast("Image too large. Please use an image under 2MB.", 'ERROR');
         return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmitAdjustment = () => {
      if (!selectedProductForAdj) return;

      let newStock = selectedProductForAdj.stock;

      // Calculate new stock with float precision if needed
      if (adjType === 'ADD') newStock = parseFloat((selectedProductForAdj.stock + adjQuantity).toFixed(3));
      if (adjType === 'REMOVE') newStock = parseFloat((selectedProductForAdj.stock - adjQuantity).toFixed(3));
      if (adjType === 'SET') newStock = adjQuantity;

      // Prevent negative stock unless desired, for now block it
      if (newStock < 0) {
          showToast("Stock cannot be negative.", 'ERROR');
          return;
      }

      const adjustment: StockAdjustment = {
          id: `adj-${Date.now()}`,
          productId: selectedProductForAdj.id,
          productName: selectedProductForAdj.name,
          userId: currentUser.id,
          userName: currentUser.name,
          timestamp: Date.now(),
          type: adjType,
          quantity: adjQuantity,
          previousStock: selectedProductForAdj.stock,
          newStock: newStock,
          reason: adjReason,
          notes: adjNotes
      };

      onAdjustStock(adjustment);
      setIsAdjModalOpen(false);
  }

  const handleBulkSubmit = () => {
      if (bulkAdjQuantity <= 0 && bulkAdjType !== 'SET') {
          showToast("Quantity must be greater than zero.", 'ERROR');
          return;
      }
      if (bulkAdjType === 'SET' && bulkAdjQuantity < 0) {
          showToast("Stock cannot be negative.", 'ERROR');
          return;
      }

      const timestamp = Date.now();
      const adjustments: StockAdjustment[] = [];

      selectedIds.forEach(id => {
          const product = products.find(p => p.id === id);
          if (!product) return;

          let delta = bulkAdjQuantity;
          let newStock = product.stock;

          // If product doesn't allow decimal, floor the delta for operations to avoid fractional stocks
          // For SET, we just use the rounded quantity
          const qty = product.allowDecimal ? delta : Math.round(delta);

          if (bulkAdjType === 'ADD') {
              newStock = parseFloat((product.stock + qty).toFixed(3));
          } else if (bulkAdjType === 'REMOVE') {
              newStock = parseFloat((product.stock - qty).toFixed(3));
          } else if (bulkAdjType === 'SET') {
              newStock = qty;
          }

          if (newStock < 0) newStock = 0; // Prevent negative stock

          adjustments.push({
              id: `adj-bulk-${id}-${timestamp}`,
              productId: product.id,
              productName: product.name,
              userId: currentUser.id,
              userName: currentUser.name,
              timestamp: timestamp,
              type: bulkAdjType,
              quantity: qty,
              previousStock: product.stock,
              newStock: newStock,
              reason: bulkAdjReason,
              notes: bulkAdjNotes ? `[Bulk] ${bulkAdjNotes}` : '[Bulk Update]'
          });
      });

      onBulkAdjustStock(adjustments);
      setIsBulkAdjModalOpen(false);
      setSelectedIds(new Set()); // Clear selection
      setBulkAdjQuantity(0);
      setBulkAdjNotes('');
  };

  const handleConvertStock = () => {
      const sourceProd = products.find(p => p.id === convSourceId);
      const targetProd = products.find(p => p.id === convTargetId);

      if (!sourceProd || !targetProd) {
          showToast("Please select both source and target products.", 'ERROR');
          return;
      }
      if (sourceProd.id === targetProd.id) {
          showToast("Source and target cannot be the same.", 'ERROR');
          return;
      }
      if (convSourceQty <= 0) {
          showToast("Source quantity must be greater than zero.", 'ERROR');
          return;
      }
      if (convTargetQty <= 0) {
          showToast("Target quantity must be greater than zero.", 'ERROR');
          return;
      }
      if (sourceProd.stock < convSourceQty) {
          showToast(`Insufficient stock in ${sourceProd.name}.`, 'ERROR');
          return;
      }

      const timestamp = Date.now();

      // 1. Remove from Source
      const sourceAdj: StockAdjustment = {
          id: `adj-conv-src-${timestamp}`,
          productId: sourceProd.id,
          productName: sourceProd.name,
          userId: currentUser.id,
          userName: currentUser.name,
          timestamp: timestamp,
          type: 'REMOVE',
          quantity: convSourceQty,
          previousStock: sourceProd.stock,
          newStock: parseFloat((sourceProd.stock - convSourceQty).toFixed(3)),
          reason: `Conversion to ${targetProd.name}`,
          notes: `Repacked/Converted ${convSourceQty} units to ${convTargetQty} units of ${targetProd.name}`
      };

      // 2. Add to Target
      const targetAdj: StockAdjustment = {
          id: `adj-conv-tgt-${timestamp}`,
          productId: targetProd.id,
          productName: targetProd.name,
          userId: currentUser.id,
          userName: currentUser.name,
          timestamp: timestamp, // same timestamp ensures logical grouping
          type: 'ADD',
          quantity: convTargetQty,
          previousStock: targetProd.stock,
          newStock: parseFloat((targetProd.stock + convTargetQty).toFixed(3)),
          reason: `Conversion from ${sourceProd.name}`,
          notes: `Repacked/Converted from ${convSourceQty} units of ${sourceProd.name}`
      };

      onAdjustStock(sourceAdj);
      onAdjustStock(targetAdj);

      showToast(`Successfully converted ${convSourceQty} ${sourceProd.name} to ${convTargetQty} ${targetProd.name}`, 'SUCCESS');
      setIsConversionModalOpen(false);
  };

  const handleSave = () => {
    if (!formData.name || !formData.price || !formData.category) {
        showToast("Please fill in required fields (Name, Category, Price)", 'ERROR');
        return; 
    }

    if (editingProduct) {
      // Check for price/cost changes for history logging
      if (formData.price !== editingProduct.price) {
          onLogPriceChange({
              id: `ph-${Date.now()}-price`,
              productId: editingProduct.id,
              type: 'PRICE',
              oldValue: editingProduct.price,
              newValue: formData.price || 0,
              userId: currentUser.id,
              userName: currentUser.name,
              timestamp: Date.now()
          });
      }
      if (formData.cost !== editingProduct.cost) {
          onLogPriceChange({
              id: `ph-${Date.now()}-cost`,
              productId: editingProduct.id,
              type: 'COST',
              oldValue: editingProduct.cost,
              newValue: formData.cost || 0,
              userId: currentUser.id,
              userName: currentUser.name,
              timestamp: Date.now()
          });
      }

      setProducts(prev => prev.map(p => p.id === editingProduct.id ? { ...p, ...formData } as Product : p));
      showToast("Product updated successfully.", 'SUCCESS');
    } else {
      const newProduct: Product = {
        id: `p-${Date.now()}`,
        ...formData as Product
      };
      setProducts(prev => [...prev, newProduct]);
      showToast("New product created.", 'SUCCESS');
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Are you sure you want to delete this product?')) {
      setProducts(prev => prev.filter(p => p.id !== id));
      showToast("Product deleted.", 'INFO');
    }
  };

  const handleGenerateDescription = async () => {
    if (!formData.name || !formData.category) {
        showToast("Please enter a Name and Category first.", 'ERROR');
        return;
    }
    const desc = await generateProductDescription(formData.name, formData.category);
    setFormData(prev => ({ ...prev, description: desc }));
    showToast("Description generated with AI.", 'SUCCESS');
  };

  const handleRestockCheck = async () => {
      setIsLoadingAi(true);
      const suggestions = await suggestRestock(products);
      setAiSuggestions(suggestions);
      setIsLoadingAi(false);
      showToast("Inventory analyzed by AI.", 'SUCCESS');
  }

  const getDaysUntilExpiry = (dateString?: string) => {
      if (!dateString) return null;
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      // Parse YYYY-MM-DD explicitly to avoid timezone issues
      const [year, month, day] = dateString.split('-').map(Number);
      const expiry = new Date(year, month - 1, day);

      const diffTime = expiry.getTime() - today.getTime();
      return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const getExpiryStatus = (days: number | null) => {
      if (days === null) return 'NONE';
      if (days < 0) return 'EXPIRED';
      if (days <= 30) return 'WARNING';
      return 'OK';
  };

  // --- Filtering & Sorting Logic ---

  const handleSort = (field: SortField) => {
      if (sortField === field) {
          setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
      } else {
          setSortField(field);
          setSortDirection('asc');
      }
  };

  const processedProducts = useMemo(() => {
      let filtered = products.filter(p => 
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        p.sku.toLowerCase().includes(searchTerm.toLowerCase())
      );

      // Category Filter
      if (filterCategory !== 'ALL') {
          filtered = filtered.filter(p => p.category === filterCategory);
      }

      // Stock Status Filter
      if (filterStockStatus !== 'ALL') {
          if (filterStockStatus === 'OUT') filtered = filtered.filter(p => p.stock === 0);
          if (filterStockStatus === 'LOW') filtered = filtered.filter(p => p.stock > 0 && p.stock <= p.minStockLevel);
          if (filterStockStatus === 'IN') filtered = filtered.filter(p => p.stock > p.minStockLevel);
      }

      // Expiry Filter
      if (filterExpiry !== 'ALL') {
          filtered = filtered.filter(p => {
              const days = getDaysUntilExpiry(p.stockExpiryDate);
              if (filterExpiry === 'EXPIRED') return days !== null && days < 0;
              if (filterExpiry === 'SOON') return days !== null && days >= 0 && days <= 30;
              if (filterExpiry === 'VALID') return days === null || days > 30;
              return true;
          });
      }

      // Sorting Logic
      return filtered.sort((a, b) => {
          let valA: any;
          let valB: any;

          switch (sortField) {
              case 'margin':
                  valA = a.price > 0 ? ((a.price - a.cost) / a.price) : -999999;
                  valB = b.price > 0 ? ((b.price - b.cost) / b.price) : -999999;
                  break;
              case 'stockExpiryDate':
                  // Treat no expiry as valid/infinite future for sorting purposes (or bottom)
                  // Let's treat null as far future so expired stuff comes first in ASC
                  valA = a.stockExpiryDate ? new Date(a.stockExpiryDate).getTime() : 9999999999999;
                  valB = b.stockExpiryDate ? new Date(b.stockExpiryDate).getTime() : 9999999999999;
                  break;
              default:
                  valA = a[sortField];
                  valB = b[sortField];
          }

          // Handle nulls/undefineds for standard fields (push to end)
          if ((valA === null || valA === undefined || valA === '') && (valB !== null && valB !== undefined && valB !== '')) return 1;
          if ((valB === null || valB === undefined || valB === '') && (valA !== null && valA !== undefined && valA !== '')) return -1;
          if ((valA === null || valA === undefined || valA === '') && (valB === null || valB === undefined || valB === '')) return 0;

          // String comparison
          if (typeof valA === 'string' && typeof valB === 'string') {
              return sortDirection === 'asc' 
                  ? valA.localeCompare(valB) 
                  : valB.localeCompare(valA);
          }

          // Number comparison
          if (valA < valB) return sortDirection === 'asc' ? -1 : 1;
          if (valA > valB) return sortDirection === 'asc' ? 1 : -1;

          return 0;
      });

  }, [products, searchTerm, filterCategory, filterStockStatus, filterExpiry, sortField, sortDirection]);

  // Selection Logic
  const handleSelectAll = () => {
      if (selectedIds.size === processedProducts.length && processedProducts.length > 0) {
          setSelectedIds(new Set());
      } else {
          setSelectedIds(new Set(processedProducts.map(p => p.id)));
      }
  };

  const handleSelectRow = (id: string) => {
      const newSet = new Set(selectedIds);
      if (newSet.has(id)) newSet.delete(id);
      else newSet.add(id);
      setSelectedIds(newSet);
  };

  const handleOpenBulkModal = () => {
      setBulkAdjType('ADD');
      setBulkAdjQuantity(0);
      setBulkAdjReason('Stock Count Correction');
      setBulkAdjNotes('');
      setIsBulkAdjModalOpen(true);
  };

  // Derived stats for top banners
  const expiringProducts = products.filter(p => {
    const days = getDaysUntilExpiry(p.stockExpiryDate);
    return days !== null && days >= 0 && days <= 30;
  });

  const expiredProducts = products.filter(p => {
      const days = getDaysUntilExpiry(p.stockExpiryDate);
      return days !== null && days < 0;
  });

  const lowStockProducts = products.filter(p => p.stock <= p.minStockLevel);

  const reasons = [
      'Stock Count Correction',
      'Received Shipment',
      'Damaged Goods',
      'Expired Stock',
      'Theft / Loss',
      'Return to Vendor',
      'Customer Return',
      'Promotion / Demo',
      'Other'
  ];

  // --- UI Render Helpers ---
  const renderSortIcon = (field: SortField) => {
      if (sortField !== field) return <ChevronsUpDown size={14} className="text-slate-400 ml-1" />;
      return sortDirection === 'asc' ? <ArrowUp size={14} className="text-blue-500 ml-1" /> : <ArrowDown size={14} className="text-blue-500 ml-1" />;
  };

  const HeaderCell = ({ field, label, align = 'left' }: { field: SortField, label: string, align?: 'left' | 'center' | 'right' }) => (
      <th 
          className={`p-4 text-xs font-semibold text-slate-600 dark:text-slate-300 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700 transition select-none text-${align}`}
          onClick={() => handleSort(field)}
      >
          <div className={`flex items-center ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
              {label}
              {renderSortIcon(field)}
          </div>
      </th>
  );

  return (
    <div className="space-y-6">
      {/* Top Banner Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-full mr-4"><Package size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Total Items</p><p className="text-lg font-bold text-slate-800 dark:text-white">{formatNumber(totalItems)}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-full mr-4"><DollarSign size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Total Value (Retail)</p><p className="text-lg font-bold text-slate-800 dark:text-white">{symbol}{formatCurrency(totalValueRetail)}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400 rounded-full mr-4"><TrendingUp size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Total Value (Cost)</p><p className="text-lg font-bold text-slate-800 dark:text-white">{symbol}{formatCurrency(totalValueCost)}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 rounded-full mr-4"><AlertTriangle size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Needs Attention</p><p className="text-lg font-bold text-slate-800 dark:text-white">{lowStockProducts.length + expiredProducts.length} Items</p></div>
          </div>
      </div>

      {/* Main Controls */}
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
          <div className="flex flex-col md:flex-row gap-4 w-full xl:w-auto">
              {/* Search */}
              <div className="relative w-full md:w-64">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={18} />
                  <input type="text" placeholder="Search product or SKU..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 focus:ring-2 focus:ring-blue-500 focus:outline-none bg-slate-50 dark:bg-slate-700 dark:text-white dark:placeholder-slate-400"/>
              </div>

              {/* Filters */}
              <div className="flex gap-2">
                  <div className="relative">
                      <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="appearance-none pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500">
                          {categories.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                      <Filter size={14} className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-400 pointer-events-none"/>
                  </div>
                  <div className="relative">
                      <select value={filterStockStatus} onChange={(e) => setFilterStockStatus(e.target.value as any)} className="appearance-none pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500">
                          <option value="ALL">All Stock</option>
                          <option value="LOW">Low Stock</option>
                          <option value="OUT">Out of Stock</option>
                          <option value="IN">In Stock</option>
                      </select>
                      <ChevronDown size={14} className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-400 pointer-events-none"/>
                  </div>
                  <div className="relative">
                      <select value={filterExpiry} onChange={(e) => setFilterExpiry(e.target.value as any)} className="appearance-none pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500">
                          <option value="ALL">All Dates</option>
                          <option value="EXPIRED">Expired</option>
                          <option value="SOON">Expiring Soon</option>
                          <option value="VALID">Valid</option>
                      </select>
                      <ChevronDown size={14} className="absolute right-3 top-1/2 transform -translate-y-1/2 text-slate-400 pointer-events-none"/>
                  </div>
              </div>
          </div>

          <div className="flex flex-wrap gap-2 w-full xl:w-auto justify-end">
              {selectedIds.size > 0 && (
                  <button onClick={handleOpenBulkModal} className="px-4 py-2 bg-slate-800 dark:bg-slate-600 text-white rounded-lg text-sm font-medium hover:bg-slate-700 dark:hover:bg-slate-500 transition flex items-center shadow-sm">
                      <Layers size={16} className="mr-2"/> Bulk Edit ({selectedIds.size})
                  </button>
              )}
              <button onClick={handleRestockCheck} disabled={isLoadingAi} className="px-4 py-2 bg-purple-600 text-white rounded-lg text-sm font-medium hover:bg-purple-700 transition flex items-center shadow-sm disabled:opacity-70">
                  <Wand2 size={16} className={`mr-2 ${isLoadingAi ? 'animate-spin' : ''}`}/> AI Audit
              </button>
              <button onClick={handleOpenConversionModal} className="px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm font-medium hover:bg-indigo-700 transition flex items-center shadow-sm">
                  <ArrowRightLeft size={16} className="mr-2"/> Convert
              </button>
              <button onClick={() => handleOpenModal()} className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition flex items-center shadow-sm">
                  <Plus size={16} className="mr-2"/> Add Product
              </button>
          </div>
      </div>

      {/* AI Suggestions Panel */}
      {aiSuggestions.length > 0 && (
          <div className="bg-gradient-to-r from-purple-50 to-indigo-50 dark:from-purple-900/20 dark:to-indigo-900/20 border border-purple-100 dark:border-purple-800 rounded-xl p-4 flex flex-col md:flex-row items-start gap-4">
              <div className="p-2 bg-purple-100 dark:bg-purple-900/50 rounded-full text-purple-600 dark:text-purple-300 shrink-0"><Wand2 size={20}/></div>
              <div className="flex-1">
                  <h4 className="font-bold text-purple-900 dark:text-purple-300 mb-2">AI Inventory Suggestions</h4>
                  <div className="flex flex-wrap gap-2">
                      {aiSuggestions.map((s, i) => (
                          <div key={i} className="bg-white dark:bg-slate-800 px-3 py-1.5 rounded-lg shadow-sm border border-purple-100 dark:border-slate-700 text-xs flex items-center">
                              <span className="font-bold text-slate-700 dark:text-slate-200 mr-2">{s.productName}:</span>
                              <span className="text-purple-600 dark:text-purple-400">{s.suggestedAction}</span>
                          </div>
                      ))}
                  </div>
              </div>
              <button onClick={() => setAiSuggestions([])} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200"><X size={18}/></button>
          </div>
      )}

      {/* Data Table */}
      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
          <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                  <thead className="bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-700">
                      <tr>
                          <th className="p-4 w-10">
                              <input type="checkbox" checked={selectedIds.size > 0 && selectedIds.size === processedProducts.length} onChange={handleSelectAll} className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"/>
                          </th>
                          <HeaderCell field="name" label="Product" />
                          <HeaderCell field="sku" label="SKU" />
                          <HeaderCell field="category" label="Category" />
                          <HeaderCell field="stockExpiryDate" label="Expiry" />
                          <HeaderCell field="cost" label="Cost" align="right" />
                          <HeaderCell field="price" label="Price" align="right" />
                          <HeaderCell field="margin" label="Margin" align="right" />
                          <HeaderCell field="stock" label="Stock" align="center" />
                          <th className="p-4 text-xs font-semibold text-slate-600 dark:text-slate-300 text-right">Actions</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                      {processedProducts.length === 0 ? (
                          <tr><td colSpan={10} className="p-8 text-center text-slate-500 dark:text-slate-400">No products found matching filters.</td></tr>
                      ) : (
                          processedProducts.map(product => {
                              const daysUntilExpiry = getDaysUntilExpiry(product.stockExpiryDate);
                              const expiryStatus = getExpiryStatus(daysUntilExpiry);
                              const margin = product.price > 0 ? ((product.price - product.cost) / product.price) * 100 : 0;

                              return (
                                  <tr key={product.id} className={`hover:bg-slate-50 dark:hover:bg-slate-700/50 transition group ${selectedIds.has(product.id) ? 'bg-blue-50 dark:bg-blue-900/10' : ''}`}>
                                      <td className="p-4">
                                          <input type="checkbox" checked={selectedIds.has(product.id)} onChange={() => handleSelectRow(product.id)} className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 w-4 h-4 cursor-pointer"/>
                                      </td>
                                      <td className="p-4">
                                          <div className="flex items-center">
                                              <div className="w-10 h-10 rounded bg-slate-100 dark:bg-slate-700 mr-3 overflow-hidden flex items-center justify-center shrink-0">
                                                  <img src={product.imageUrl || "https://placehold.co/40?text=..."} alt="" className="w-full h-full object-cover"/>
                                              </div>
                                              <div>
                                                  <div className="font-medium text-slate-900 dark:text-white text-sm">{product.name}</div>
                                                  {product.stock <= product.minStockLevel && <span className="text-[10px] font-bold text-orange-500 flex items-center"><AlertCircle size={10} className="mr-1"/> Low Stock</span>}
                                              </div>
                                          </div>
                                      </td>
                                      <td className="p-4 text-sm font-mono text-slate-500 dark:text-slate-400">{product.sku}</td>
                                      <td className="p-4">
                                          <span className="px-2 py-1 rounded-full text-xs font-medium bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300">
                                              {product.category}
                                          </span>
                                      </td>
                                      <td className="p-4 text-sm">
                                          {product.stockExpiryDate ? (
                                              <div className={`flex items-center ${expiryStatus === 'EXPIRED' ? 'text-red-600 font-bold' : expiryStatus === 'WARNING' ? 'text-orange-500 font-medium' : 'text-slate-500 dark:text-slate-400'}`}>
                                                  {expiryStatus !== 'OK' && <AlertTriangle size={12} className="mr-1.5"/>}
                                                  {new Date(product.stockExpiryDate).toLocaleDateString()}
                                              </div>
                                          ) : <span className="text-slate-300 dark:text-slate-600">-</span>}
                                      </td>
                                      <td className="p-4 text-right text-sm text-slate-600 dark:text-slate-400">{symbol}{formatCurrency(product.cost)}</td>
                                      <td className="p-4 text-right text-sm font-medium text-slate-800 dark:text-white">{symbol}{formatCurrency(product.price)}</td>
                                      <td className="p-4 text-right">
                                          <span className={`text-xs font-bold ${margin < 15 ? 'text-red-500' : margin < 30 ? 'text-orange-500' : 'text-green-500'}`}>
                                              {margin.toFixed(1)}%
                                          </span>
                                      </td>
                                      <td className="p-4 text-center">
                                          <div className="flex items-center justify-center space-x-2">
                                              <span className={`font-bold text-sm ${product.stock === 0 ? 'text-red-500' : product.stock <= product.minStockLevel ? 'text-orange-500' : 'text-slate-800 dark:text-white'}`}>
                                                  {formatNumber(product.stock)}
                                              </span>
                                              <span className="text-xs text-slate-400">{product.unit || 'pcs'}</span>
                                          </div>
                                      </td>
                                      <td className="p-4 text-right">
                                          <div className="flex items-center justify-end space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                              <button onClick={() => handleOpenAdjModal(product)} className="p-1.5 text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded" title="Adjust Stock"><Scale size={16}/></button>
                                              <button onClick={() => handleOpenDetails(product)} className="p-1.5 text-slate-600 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-700 rounded" title="History"><History size={16}/></button>
                                              <button onClick={() => handleOpenModal(product)} className="p-1.5 text-slate-600 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-700 rounded" title="Edit"><Edit2 size={16}/></button>
                                              <button onClick={() => handleDelete(product.id)} className="p-1.5 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 rounded" title="Delete"><Trash2 size={16}/></button>
                                          </div>
                                      </td>
                                  </tr>
                              );
                          })
                      )}
                  </tbody>
              </table>
          </div>
      </div>

      {/* Add/Edit Modal */}
      {isModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col">
                  <div className="p-6 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-xl">
                      <h3 className="text-xl font-bold text-slate-800 dark:text-white">{editingProduct ? 'Edit Product' : 'Add New Product'}</h3>
                      <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X size={24}/></button>
                  </div>
                  <div className="flex-1 overflow-y-auto p-6 space-y-6">
                      <div className="flex gap-6">
                          {/* Image Upload */}
                          <div className="w-32 shrink-0">
                              <label className="block w-32 h-32 rounded-xl border-2 border-dashed border-slate-300 dark:border-slate-600 hover:border-blue-500 transition cursor-pointer flex flex-col items-center justify-center text-slate-400 overflow-hidden relative bg-slate-50 dark:bg-slate-700">
                                  {formData.imageUrl ? <img src={formData.imageUrl} alt="" className="w-full h-full object-cover"/> : <><ImageIcon size={24} className="mb-2"/><span className="text-xs">Upload</span></>}
                                  <input type="file" accept="image/*" className="hidden" onChange={handleImageUpload}/>
                              </label>
                          </div>

                          {/* Basic Info */}
                          <div className="flex-1 space-y-4">
                              <div><label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-1">Product Name</label><input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full p-2 border rounded-lg bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" placeholder="e.g. Wireless Mouse"/></div>
                              <div className="grid grid-cols-2 gap-4">
                                  <div><label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-1">SKU</label><input type="text" value={formData.sku} onChange={e => setFormData({...formData, sku: e.target.value})} className="w-full p-2 border rounded-lg bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" placeholder="PROD-001"/></div>
                                  <div className="relative" ref={categoryDropdownRef}>
                                      <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-1">Category</label>
                                      <div className="relative">
                                          <input type="text" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} onFocus={() => setIsCategoryDropdownOpen(true)} className="w-full p-2 border rounded-lg bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white"/>
                                          {isCategoryDropdownOpen && uniqueCategories.length > 0 && (
                                              <div className="absolute top-full left-0 right-0 mt-1 bg-white dark:bg-slate-800 border dark:border-slate-600 rounded-lg shadow-lg z-20 max-h-40 overflow-y-auto">
                                                  {uniqueCategories.map(c => <div key={c} onClick={() => { setFormData({...formData, category: c}); setIsCategoryDropdownOpen(false); }} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 cursor-pointer text-sm">{c}</div>)}
                                              </div>
                                          )}
                                      </div>
                                  </div>
                              </div>
                          </div>
                      </div>

                      <div className="grid grid-cols-3 gap-4">
                          <div><label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-1">Cost Price ({symbol})</label><input type="number" min="0" step="0.01" value={formData.cost} onChange={e => setFormData({...formData, cost: parseFloat(e.target.value)})} className="w-full p-2 border rounded-lg bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white"/></div>
                          <div><label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-1">Selling Price ({symbol})</label><input type="number" min="0" step="0.01" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} className="w-full p-2 border rounded-lg bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white"/></div>
                          <div><label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-1">Initial Stock</label><input type="number" min="0" disabled={!!editingProduct} value={formData.stock} onChange={e => setFormData({...formData, stock: parseFloat(e.target.value)})} className="w-full p-2 border rounded-lg bg-slate-100 dark:bg-slate-800 dark:border-slate-600 dark:text-white cursor-not-allowed" title="Use Adjust Stock to change quantity"/></div>
                      </div>

                      <div className="grid grid-cols-3 gap-4">
                          <div className="relative" ref={unitDropdownRef}>
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-1">Unit</label>
                              <input type="text" value={formData.unit} onChange={e => setFormData({...formData, unit: e.target.value})} onFocus={() => setIsUnitDropdownOpen(true)} className="w-full p-2 border rounded-lg bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" placeholder="pcs"/>
                              {isUnitDropdownOpen && (
                                  <div className="absolute top-full left-0 right-0 mt-1 bg-white dark:bg-slate-800 border dark:border-slate-600 rounded-lg shadow-lg z-20 max-h-40 overflow-y-auto">
                                      {uniqueUnits.map(u => <div key={u} onClick={() => { setFormData({...formData, unit: u}); setIsUnitDropdownOpen(false); }} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 cursor-pointer text-sm">{u}</div>)}
                                  </div>
                              )}
                          </div>
                          <div><label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-1">Min Stock Alert</label><input type="number" min="0" value={formData.minStockLevel} onChange={e => setFormData({...formData, minStockLevel: parseFloat(e.target.value)})} className="w-full p-2 border rounded-lg bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white"/></div>
                          <div><label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-1">Expiry Date</label><input type="date" value={formData.stockExpiryDate || ''} onChange={e => setFormData({...formData, stockExpiryDate: e.target.value})} className="w-full p-2 border rounded-lg bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white dark:[color-scheme:dark]"/></div>
                      </div>

                      <div className="flex items-center space-x-2 bg-slate-50 dark:bg-slate-700/50 p-3 rounded-lg border border-slate-200 dark:border-slate-600">
                          <input type="checkbox" id="allowDecimal" checked={formData.allowDecimal} onChange={e => setFormData({...formData, allowDecimal: e.target.checked})} className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500"/>
                          <label htmlFor="allowDecimal" className="text-sm text-slate-700 dark:text-slate-300 font-medium">Allow Decimal Quantities (e.g. 1.5 kg)</label>
                      </div>

                      <div>
                          <div className="flex justify-between items-center mb-1">
                              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase">Description</label>
                              <button onClick={handleGenerateDescription} type="button" className="text-xs text-purple-600 hover:text-purple-700 flex items-center"><Wand2 size={12} className="mr-1"/> AI Generate</button>
                          </div>
                          <textarea value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full p-2 border rounded-lg bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" rows={3}></textarea>
                      </div>
                  </div>
                  <div className="p-4 border-t border-slate-100 dark:border-slate-700 flex justify-end space-x-2">
                      <button onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-500 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-700 rounded-lg">Cancel</button>
                      <button onClick={handleSave} className="px-6 py-2 bg-blue-600 text-white font-bold rounded-lg hover:bg-blue-700">Save Product</button>
                  </div>
              </div>
          </div>
      )}

      {/* Adjust Stock Modal */}
      {isAdjModalOpen && selectedProductForAdj && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-sm p-6">
                  <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-1">Adjust Stock</h3>
                  <p className="text-sm text-slate-500 mb-4">for {selectedProductForAdj.name}</p>

                  <div className="space-y-4">
                      <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-lg">
                          {['ADD', 'REMOVE', 'SET'].map(type => (
                              <button key={type} onClick={() => setAdjType(type as AdjustmentType)} className={`flex-1 py-1.5 text-xs font-bold rounded ${adjType === type ? 'bg-white dark:bg-slate-600 shadow text-blue-600 dark:text-blue-400' : 'text-slate-500 dark:text-slate-400'}`}>{type}</button>
                          ))}
                      </div>
                      <div className="flex items-center">
                          <input type="number" min="0" step={selectedProductForAdj.allowDecimal ? "0.001" : "1"} value={adjQuantity} onChange={e => setAdjQuantity(parseFloat(e.target.value))} className="flex-1 p-3 text-center text-2xl font-bold border rounded-lg bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" autoFocus/>
                      </div>
                      <div className="text-center text-sm">
                          <span className="text-slate-500">New Balance: </span>
                          <span className="font-bold text-slate-800 dark:text-white">
                              {adjType === 'ADD' ? selectedProductForAdj.stock + adjQuantity : adjType === 'REMOVE' ? selectedProductForAdj.stock - adjQuantity : adjQuantity} {selectedProductForAdj.unit}
                          </span>
                      </div>
                      <div>
                          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase mb-1">Reason</label>
                          <select value={adjReason} onChange={e => setAdjReason(e.target.value)} className="w-full p-2 border rounded-lg text-sm bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white">
                              {reasons.map(r => <option key={r} value={r}>{r}</option>)}
                          </select>
                      </div>
                      <input type="text" placeholder="Notes (Optional)" value={adjNotes} onChange={e => setAdjNotes(e.target.value)} className="w-full p-2 border rounded-lg text-sm bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white"/>
                  </div>
