                      </div>

                      <div className="text-slate-400"><ArrowRight size={24} className="hidden md:block"/><ArrowDown size={24} className="md:hidden"/></div>

                      <div className="flex-1 w-full space-y-4 p-4 bg-green-50 dark:bg-green-900/10 rounded-xl border border-green-100 dark:border-green-900">
