                      </div>
                      <button onClick={() => setIsDetailsModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X size={24}/></button>
                  </div>

                  <div className="flex border-b border-slate-200 dark:border-slate-700 px-6">
                      <button onClick={() => setHistoryView('ADJUSTMENTS')} className={`py-3 px-4 text-sm font-medium border-b-2 transition ${historyView === 'ADJUSTMENTS' ? 'border-blue-600 text-blue-600 dark:text-blue-400' : 'border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400'}`}>Stock Adjustments</button>
                      <button onClick={() => setHistoryView('RETURNS')} className={`py-3 px-4 text-sm font-medium border-b-2 transition ${historyView === 'RETURNS' ? 'border-blue-600 text-blue-600 dark:text-blue-400' : 'border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400'}`}>Returns</button>
                      <button onClick={() => setHistoryView('PRICE')} className={`py-3 px-4 text-sm font-medium border-b-2 transition ${historyView === 'PRICE' ? 'border-blue-600 text-blue-600 dark:text-blue-400' : 'border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400'}`}>Price History</button>
                  </div>

                  <div className="flex-1 overflow-y-auto p-0">
                      {historyView === 'ADJUSTMENTS' && (
