                                        {h.note && <div className="text-xs italic text-slate-500 mt-1">"{h.note}"</div>}
                                        <div className={`text-xs font-bold mt-1 ${isExpired ? 'text-red-500' : 'text-orange-500'}`}>
                                            {isExpired ? 'Expired' : `Expires in ${Math.ceil(timeLeft / 60000)} mins`}
