                                        <button onClick={() => onVoidHold(h.id)} className="px-3 py-1.5 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 text-xs font-bold rounded border border-red-200 dark:border-red-800 flex items-center justify-center">
                                            <Trash size={14} className="mr-1"/> Void
                                        </button>
                                    </div>
                                </div>
