                  <div className={`flex items-center mb-4 ${(selectedCustomer.storeCredit || 0) < 0 ? 'text-red-600 dark:text-red-400' : 'text-emerald-600 dark:text-emerald-400'}`}>
                      <Banknote size={24} className="mr-2"/>
                      <h3 className="text-lg font-bold text-slate-800 dark:text-white">
                          {(selectedCustomer.storeCredit || 0) < 0 ? 'Settle Outstanding Debt' : 'Add Store Credit'}
