                  </div>

                  {/* Current Balance Display Logic */}
                  <div className={`p-4 rounded-lg mb-6 text-center border ${(selectedCustomer.storeCredit || 0) < 0 ? 'bg-red-50 dark:bg-red-900/20 border-red-100 dark:border-red-800 text-red-700 dark:text-red-300' : 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-100 dark:border-emerald-800 text-emerald-700 dark:text-emerald-300'}`}>
                      <p className="text-xs uppercase font-bold tracking-wider mb-1 opacity-80">{(selectedCustomer.storeCredit || 0) < 0 ? 'Total Amount Due' : 'Current Balance'}</p>
                      <p className="text-3xl font-bold">
                          {symbol}{Math.abs(selectedCustomer.storeCredit || 0).toFixed(2)}
