                              <div className="mt-2 p-2 bg-slate-50 dark:bg-slate-700/50 rounded flex justify-between items-center text-xs">
                                  <span className="text-slate-500 dark:text-slate-400">New Balance:</span>
                                  <span className={`font-bold ${previewBalance < 0 ? 'text-red-500' : 'text-green-500'}`}>
                                      {symbol}{Math.abs(previewBalance).toFixed(2)} {previewBalance < 0 ? '(DR)' : '(CR)'}
                                  </span>
                              </div>
                          )}
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-500 dark:text-slate-400 mb-1">Payment Method</label>
