      setCart([]);
      setHoldNote('');
      setHoldDuration(30);
      setAmountTendered('');
      setIsHoldModalOpen(false);
      setSelectedCustomer(createWalkInCustomer());
  }

  const resumeHold = (hold: HoldTransaction) => {
