  sales, 
  returns,
  onProcessReturn,
  heldTransactions,
  onHoldTransaction,
  onResumeHold,
  onVoidHold,
  currency,
  showToast,
  storeSettings,
  onCartUpdate,
  resumeHoldId,
  onClearResumeHold,
