      document.exitFullscreen();
    }
  };

  useImperativeHandle(ref, () => ({
      triggerHold: () => {
          if (cart.length > 0) handleHoldClick();
      }
  }));

  useEffect(() => {
      if (resumeHoldId && onClearResumeHold) {
          const hold = heldTransactions.find(h => h.id === resumeHoldId);
          if (hold) {
              if (cart.length > 0) {
                  triggerToast("Cannot auto-resume: Current cart is not empty.", 'ERROR');
              } else {
                  setCart(hold.items);
                  setSelectedCustomer(hold.customer);
                  onResumeHold(hold.id);
                  triggerToast(`Transaction for ${hold.customer.name} resumed!`, 'SUCCESS');
              }
          }
          onClearResumeHold();
      }
  }, [resumeHoldId, heldTransactions, cart.length]);

  useEffect(() => {
      onCartUpdate(cart.length > 0);
  }, [cart]);

  const categories: string[] = ['All', ...Array.from(new Set(products.map(p => p.category))) as string[]];

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  };
  const symbol = getCurrencySymbol(currency);
  const formatCurrency = (val: number) => val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  useEffect(() => {
    const timer = setInterval(() => setTick(t => t + 1), 1000); 
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchInputRef.current && !searchInputRef.current.contains(event.target as Node)) {
        setIsSearchFocused(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const addToCart = (product: Product) => {
    if (product.stock <= 0) return; 
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) {
            triggerToast("Cannot add more than available stock.", 'ERROR');
            return prev;
        }
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    setSearchTerm(''); 
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        let newQty = item.quantity + delta;
        if (item.allowDecimal) newQty = Math.round(newQty * 1000) / 1000;
        if (delta > 0 && newQty > item.stock) return item; 
        return { ...item, quantity: Math.max(item.allowDecimal ? 0.001 : 1, newQty) };
      }
      return item;
    }));
  };

  const setItemQuantity = (id: string, value: string) => {
    if (value === '') {
        setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: 0 } : item));
        return;
    }
    const qty = parseFloat(value);
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        let newQty = isNaN(qty) ? 0 : qty;
        newQty = Math.min(newQty, item.stock);
        if (!item.allowDecimal) newQty = Math.floor(newQty);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const handleInputBlur = (id: string, currentQty: number) => {
    const item = cart.find(i => i.id === id);
    if (!item) return;
    const minQty = item.allowDecimal ? 0.001 : 1;
    if (currentQty < minQty) {
        setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: minQty } : i));
    }
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const cartSubtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  let calculatedTax = 0;
  let finalTotal = cartSubtotal;

  if (storeSettings.taxRate > 0) {
      if (storeSettings.taxType === 'EXCLUSIVE') {
          calculatedTax = cartSubtotal * (storeSettings.taxRate / 100);
          finalTotal = cartSubtotal + calculatedTax;
      } else {
          calculatedTax = cartSubtotal - (cartSubtotal / (1 + storeSettings.taxRate / 100));
          finalTotal = cartSubtotal;
      }
  }

  let creditMarkupAmount = 0;
  let currentCreditTerm: CreditTerm | undefined;

  if (paymentMethod === 'STORE_CREDIT') {
      currentCreditTerm = storeSettings.creditTerms?.find(t => t.id === selectedCreditTermId);
      if (!currentCreditTerm && storeSettings.creditTerms?.length > 0) currentCreditTerm = storeSettings.creditTerms[0];
      const rate = currentCreditTerm ? currentCreditTerm.rate : (storeSettings.creditMarkupRate || 0);
      if (rate > 0) creditMarkupAmount = finalTotal * (rate / 100);
  }

  const finalPayableAmount = finalTotal + creditMarkupAmount;
  const tenderedNum = parseFloat(amountTendered) || 0;
  const changeDue = tenderedNum - finalPayableAmount;
  const potentialNewBalance = (selectedCustomer?.storeCredit || 0) - finalPayableAmount;

  const handleCheckout = () => {
    if (cart.length === 0) return;
    if (paymentMethod === 'CASH' && tenderedNum < finalPayableAmount) {
        triggerToast("Amount tendered is less than total.", 'ERROR');
        return;
    }
    if (paymentMethod === 'STORE_CREDIT') {
        if (!selectedCustomer) { triggerToast("Select customer for credit.", 'ERROR'); return; }
        if (selectedCustomer.type !== 'MEMBER') { triggerToast("Store Credit is for Members only.", 'ERROR'); return; }
        const limit = selectedCustomer.creditLimit || 0;
        if (potentialNewBalance < -limit) {
            const canBypass = currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPER_ADMIN;
            if (canBypass) {
                if (!window.confirm(`Credit limit exceeded by ${symbol}${Math.abs(potentialNewBalance + limit).toFixed(2)}. Bypass?`)) return;
            } else {
                triggerToast(`Transaction exceeds credit limit (${symbol}${limit}).`, 'ERROR');
                return;
            }
        }
    }
    if (selectedCustomer && !customers.find(c => c.id === selectedCustomer.id)) onAddCustomer(selectedCustomer);
    const costOfGoods = cart.reduce((sum, item) => sum + (item.cost * item.quantity), 0);
    const saleProfit = (cartSubtotal - costOfGoods) + creditMarkupAmount;
    let creditDueDate = undefined;
    if (paymentMethod === 'STORE_CREDIT' && currentCreditTerm) creditDueDate = Date.now() + (currentCreditTerm.days * 24 * 60 * 60 * 1000);
    const sale: Sale = {
      id: `sale-${Date.now()}`,
      timestamp: Date.now(),
      items: cart.map(item => ({ productId: item.id, productName: item.name, quantity: item.quantity, unit: item.unit, priceAtSale: item.price, costAtSale: item.cost })),
      subTotal: cartSubtotal, totalTax: calculatedTax, totalAmount: finalPayableAmount, totalProfit: saleProfit,
      taxName: storeSettings.taxName, taxRate: storeSettings.taxRate, taxType: storeSettings.taxType,
      creditMarkupRate: currentCreditTerm ? currentCreditTerm.rate : (storeSettings.creditMarkupRate || 0), creditMarkupAmount: creditMarkupAmount, creditTermName: currentCreditTerm ? currentCreditTerm.name : undefined, creditDueDate: creditDueDate,
      cashierId: currentUser.id, paymentMethod, customerId: selectedCustomer?.id, customerName: selectedCustomer?.name, amountTendered: paymentMethod === 'CASH' ? tenderedNum : undefined, change: paymentMethod === 'CASH' ? changeDue : undefined
    };
    onCompleteSale(sale);
    setCompletedSale(sale);
    setShowReceipt(true);
    setCart([]);
  };

  const handleOpenAccountPayment = () => {
      if (!selectedCustomer || selectedCustomer.type !== 'MEMBER') { triggerToast("Select a Member for payment.", 'ERROR'); return; }
      setIsPaymentModalOpen(true);
      setAccountPaymentAmount('');
      setAccountPaymentMethod('CASH');
  };

  const handleAccountPayment = () => {
      if (!onAddCreditAdjustment) return;
      const amount = parseFloat(accountPaymentAmount);
      if (isNaN(amount) || amount <= 0) { triggerToast("Enter valid amount.", 'ERROR'); return; }
      if (!selectedCustomer) return;
      const currentBalance = selectedCustomer.storeCredit || 0;
      const newBalance = currentBalance + amount;
      const adj: CreditAdjustment = { id: `pay-${Date.now()}`, customerId: selectedCustomer.id, customerName: selectedCustomer.name, amount: amount, type: 'ADD', paymentMethod: accountPaymentMethod, newBalance: newBalance, timestamp: Date.now(), userId: currentUser.id, userName: currentUser.name, reason: 'Account Payment (POS)' };
      onAddCreditAdjustment(adj);
      setSelectedCustomer({ ...selectedCustomer, storeCredit: newBalance });
      setCompletedPayment(adj);
      setShowReceipt(true);
      setIsPaymentModalOpen(false);
      setAccountPaymentAmount('');
  };

  const handleNewSale = () => {
      setShowReceipt(false); setCompletedSale(null); setCompletedPayment(null); setAmountTendered('');
      setSelectedCustomer(createWalkInCustomer()); setCustomerSearch('');
      if (paymentMethod === 'STORE_CREDIT') setPaymentMethod('CARD');
  };

  const handlePrintReceipt = () => window.print();

  const handleCreateCustomer = () => {
      if (!newCustomerName) return;
      const newCustomer: Customer = { id: `c-${Date.now()}`, name: newCustomerName, email: newCustomerEmail, phone: newCustomerPhone, totalSpent: 0, visitCount: 0, storeCredit: 0, type: 'MEMBER' };
      onAddCustomer(newCustomer);
      setSelectedCustomer(newCustomer);
      setIsCustomerModalOpen(false);
      setNewCustomerName(''); setNewCustomerEmail(''); setNewCustomerPhone('');
  }

  const handleHoldClick = () => {
      if (cart.length === 0) return;
      if (selectedCustomer && selectedCustomer.type === 'MEMBER') { triggerToast("Hold not available for Members.", 'ERROR'); return; }
      setIsHoldModalOpen(true);
  }

  const confirmHold = () => {
      if (!selectedCustomer) return;
      const hold: HoldTransaction = { id: `hold-${Date.now()}-${Math.floor(Math.random() * 1000)}`, items: [...cart], customer: selectedCustomer, timestamp: Date.now(), durationMinutes: holdDuration, expiryTime: Date.now() + (holdDuration * 60 * 1000), note: holdNote, cashierId: currentUser.id };
      onHoldTransaction(hold);
      setCart([]); setHoldNote(''); setHoldDuration(30); setAmountTendered('');
      setIsHoldModalOpen(false); setSelectedCustomer(createWalkInCustomer());
  }

  const resumeHold = (hold: HoldTransaction) => {
      setCart(hold.items);
      setSelectedCustomer(hold.customer);
      onResumeHold(hold.id);
      setIsHeldListOpen(false);
  }

  const getSuggestions = () => {
    if (!searchTerm) return [];
    const results: { type: 'PRODUCT' | 'CATEGORY', item: any, score: number }[] = [];
    categories.forEach((cat: string) => {
      if (cat === 'All') return;
      const score = getMatchScore(cat, searchTerm);
      if (score > 40) results.push({ type: 'CATEGORY', item: cat, score: score + 10 });
    });
    products.forEach(p => {
       const nameScore = getMatchScore(p.name, searchTerm);
       const skuScore = getMatchScore(p.sku, searchTerm);
       const score = Math.max(nameScore, skuScore);
       if (score > 0) results.push({ type: 'PRODUCT', item: p, score });
    });
    return results.sort((a, b) => b.score - a.score).slice(0, 6);
  };

  const suggestions = getSuggestions();
  const filteredProducts = products.filter(p => activeCategory === 'All' || p.category === activeCategory).map(p => ({ ...p, matchScore: searchTerm ? Math.max(getMatchScore(p.name, searchTerm), getMatchScore(p.sku, searchTerm)) : 1 })).filter(p => p.matchScore > 0).sort((a, b) => { if (searchTerm) return b.matchScore - a.matchScore; return a.name.localeCompare(b.name); });
  const filteredCustomers = customers.filter(c => !c.id.startsWith('walkin-') && (c.name.toLowerCase().includes(customerSearch.toLowerCase()) || c.phone?.includes(customerSearch) || c.email?.toLowerCase().includes(customerSearch.toLowerCase())));
  const filteredHeldTransactions = heldTransactions.filter(h => h.id.toLowerCase().includes(heldSearch.toLowerCase()) || h.customer.name.toLowerCase().includes(heldSearch.toLowerCase()) || h.note?.toLowerCase().includes(heldSearch.toLowerCase()));
  const canHold = selectedCustomer && selectedCustomer.type !== 'MEMBER';
  const isDebt = selectedCustomer && selectedCustomer.type === 'MEMBER' && (selectedCustomer.storeCredit || 0) < 0;
  const debtAmount = isDebt ? Math.abs(selectedCustomer!.storeCredit) : 0;
  const creditLimit = selectedCustomer?.creditLimit || 0;
  const currentCredit = selectedCustomer?.storeCredit || 0;
  const availableCredit = creditLimit + currentCredit;
  const usagePercentage = creditLimit > 0 ? Math.min(100, Math.max(0, (Math.abs(currentCredit < 0 ? currentCredit : 0) / creditLimit) * 100)) : 0;
  const previewBalance = (selectedCustomer?.storeCredit || 0) + (parseFloat(accountPaymentAmount) || 0);

  return (
    <div ref={posContainerRef} className={`flex flex-col lg:flex-row gap-6 p-4 md:p-6 bg-slate-100 dark:bg-slate-900 ${isFullscreen ? 'h-screen w-screen overflow-auto relative' : 'h-[calc(100vh-100px)]'}`}>

      {/* Fullscreen Notification Mirror Area */}
      {isFullscreen && (
          <div className="fixed top-4 right-4 z-[100] flex flex-col items-end gap-2 w-full max-w-sm pointer-events-none">
              {/* Mirror Urgent Holds from App if in fullscreen */}
              {urgentHolds.map(hold => {
                  const diff = Math.max(0, hold.expiryTime - Date.now());
                  const isCritical = diff < 60 * 1000;
                  return (
                      <div 
                        key={hold.id}
                        onClick={() => onUrgentHoldClick?.(hold.id)}
                        className={`pointer-events-auto px-4 py-3 rounded-xl shadow-lg flex items-center space-x-3 cursor-pointer transition-all transform hover:scale-105 backdrop-blur-md border border-white/20
                            ${isCritical ? 'bg-red-600/90 text-white animate-pulse' : 'bg-amber-600/90 text-white'}`}
                      >
                          <AlertCircle size={20} />
                          <div className="flex flex-col items-start leading-tight">
                              <span className="font-bold text-[10px] uppercase tracking-wider">{isCritical ? 'CRITICAL HOLD' : 'EXPIRING HOLD'}</span>
                              <span className="text-xs font-semibold">{hold.customer.name} • {Math.floor(diff/60000)}m left</span>
                          </div>
                          <PlayCircle size={16} className="ml-2"/>
                      </div>
                  );
              })}

              {/* Mirror Local Toasts */}
              {localToasts.map(toast => (
                  <div key={toast.id} className={`pointer-events-auto flex items-center p-3 pl-4 rounded-lg shadow-xl animate-in slide-in-from-right-10 fade-in duration-300 w-full 
                    ${toast.type === 'SUCCESS' ? 'bg-emerald-600' : toast.type === 'ERROR' ? 'bg-red-600' : 'bg-blue-600'} text-white`}>
                      {toast.type === 'SUCCESS' ? <CheckCircle size={18} className="mr-3" /> : toast.type === 'ERROR' ? <AlertCircle size={18} className="mr-3" /> : <Info size={18} className="mr-3" />}
                      <span className="font-medium text-sm flex-1 leading-tight">{toast.message}</span>
                  </div>
              ))}
          </div>
      )}

      <style>{`
        @media print {
            body * { visibility: hidden; }
            #receipt-content, #receipt-content * { visibility: visible; }
            #receipt-content { position: absolute; left: 0; top: 0; margin: 0; padding: 0; box-shadow: none; border: none; width: 100%; background: white; }
            .format-a4 { width: 100%; padding: 40px !important; font-size: 12pt !important; }
            .format-80mm { width: 100%; font-size: 12px; padding: 10px !important; }
            .format-58mm { width: 100%; font-size: 10px; padding: 5px !important; }
            .no-print { display: none !important; }
        }
      `}</style>

      {/* Product Grid */}
      <div className="flex-1 flex flex-col bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden relative">
          <div className="p-4 border-b border-slate-200 dark:border-slate-700 space-y-4 z-20 bg-white dark:bg-slate-800">
             <div className="flex justify-between items-center mb-2">
                 <div className="text-slate-800 dark:text-white font-bold hidden md:block">Terminal</div>
                 <div className="flex space-x-2">
                   <button onClick={toggleFullscreen} className="bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-600 text-slate-600 dark:text-slate-200 px-3 py-1.5 rounded-lg flex items-center text-sm font-medium shadow-sm transition">
                       {isFullscreen ? <Minimize size={16} className="mr-2"/> : <Maximize size={16} className="mr-2"/>} {isFullscreen ? 'Exit Fullscreen' : 'Fullscreen'}
                   </button>
                   <button onClick={() => setIsHeldListOpen(true)} className={`bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-600 text-slate-600 dark:text-slate-200 px-3 py-1.5 rounded-lg flex items-center text-sm font-medium shadow-sm transition ${heldTransactions.length > 0 ? 'border-orange-200 text-orange-600 bg-orange-50 dark:bg-orange-900/30 dark:text-orange-400 dark:border-orange-800' : ''}`}>
                       <PauseCircle size={16} className="mr-2"/> Holds ({heldTransactions.length})
                   </button>
                   <button onClick={() => setIsOrdersModalOpen(true)} className="bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-600 text-slate-600 dark:text-slate-200 px-3 py-1.5 rounded-lg flex items-center text-sm font-medium shadow-sm transition">
                       <Receipt size={16} className="mr-2"/> Recent Orders
                   </button>
                   <button onClick={() => setIsReturnsHistoryOpen(true)} className="bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-600 text-slate-600 dark:text-slate-200 px-3 py-1.5 rounded-lg flex items-center text-sm font-medium shadow-sm transition">
                       <RotateCcw size={16} className="mr-2"/> Returns History
                   </button>
                 </div>
             </div>

             <div className="relative" ref={searchInputRef}>
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={20} />
                <input 
                  type="text" placeholder="Search products by name, SKU, or category..." value={searchTerm}
                  onFocus={() => setIsSearchFocused(true)}
                  onChange={(e) => { setSearchTerm(e.target.value); setIsSearchFocused(true); }}
                  className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500 bg-slate-50 dark:bg-slate-700 dark:text-white dark:placeholder-slate-400"
                />
                {isSearchFocused && searchTerm && suggestions.length > 0 && (
                    <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-100 dark:border-slate-700 overflow-hidden z-30">
                        {suggestions.map((s, idx) => (
                            <div key={idx}
                                onClick={() => { if (s.type === 'CATEGORY') { setActiveCategory(s.item); setSearchTerm(''); setIsSearchFocused(false); } else { addToCart(s.item as Product); setIsSearchFocused(false); } }}
                                className="flex items-center p-3 hover:bg-blue-50 dark:hover:bg-slate-700 cursor-pointer border-b border-slate-50 dark:border-slate-700 last:border-0 transition-colors"
                            >
                                {s.type === 'CATEGORY' ? (
                                    <><Tag size={18} className="text-blue-500 mr-3" /><div><p className="text-sm font-medium text-slate-800 dark:text-white">Category: <span className="text-blue-600 dark:text-blue-400">{s.item}</span></p></div></>
                                ) : (
                                    <><div className="w-8 h-8 rounded bg-slate-100 dark:bg-slate-700 mr-3 overflow-hidden shrink-0"><img src={(s.item as Product).imageUrl || "https://placehold.co/40?text=No+Img"} alt="" className="w-full h-full object-cover"/></div><div className="flex-1"><p className="text-sm font-medium text-slate-800 dark:text-white">{(s.item as Product).name}</p><div className="flex items-center text-xs text-slate-500 dark:text-slate-400"><span className="text-green-600 dark:text-green-400 font-bold">{symbol}{formatCurrency((s.item as Product).price)}</span>{(s.item as Product).unit && <span className="ml-1 text-slate-400">/ {(s.item as Product).unit}</span>}</div></div></>
                                )}
                            </div>
                        ))}
                    </div>
                )}
             </div>
             <div className="flex space-x-2 overflow-x-auto pb-2 scrollbar-hide">
                {categories.map(cat => (
                  <button key={cat} onClick={() => setActiveCategory(cat)} className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition ${activeCategory === cat ? 'bg-blue-600 text-white shadow-md' : 'bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600'}`}>{cat}</button>
                ))}
             </div>
          </div>
          <div className="flex-1 overflow-y-auto p-4 grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 bg-slate-50/50 dark:bg-slate-900/50">
             {filteredProducts.length === 0 ? <div className="col-span-full flex flex-col items-center justify-center text-slate-400 mt-10"><Package size={48} className="mb-4 opacity-20"/><p>No products found</p></div> :
                filteredProducts.map(product => (
                    <div key={product.id} onClick={() => addToCart(product)} className={`bg-white dark:bg-slate-800 rounded-xl p-3 shadow-sm hover:shadow-md cursor-pointer border border-slate-100 dark:border-slate-700 transition-all active:scale-95 flex flex-col group ${product.stock === 0 ? 'opacity-50 grayscale cursor-not-allowed' : ''}`}>
                        <div className="aspect-square bg-slate-100 dark:bg-slate-700 rounded-lg mb-3 overflow-hidden relative">
                            <img src={product.imageUrl || "https://placehold.co/300?text=No+Image"} alt={product.name} className="w-full h-full object-cover transition-transform group-hover:scale-105" />
                            {product.stock <= product.minStockLevel && product.stock > 0 && (<div className="absolute top-2 right-2 bg-red-500 text-white text-[10px] font-bold px-1.5 py-0.5 rounded shadow-sm">LOW</div>)}
                            {product.stock === 0 && (<div className="absolute inset-0 bg-black/10 flex items-center justify-center"><span className="bg-slate-900 text-white text-xs font-bold px-2 py-1 rounded">OUT OF STOCK</span></div>)}
                        </div>
                        <h4 className="font-semibold text-slate-800 dark:text-white text-sm mb-1 truncate">{product.name}</h4>
                        <div className="flex justify-between items-center mt-auto">
                            <div className="flex flex-col"><span className="text-blue-600 dark:text-blue-400 font-bold">{symbol}{formatCurrency(product.price)}</span>{product.unit && <span className="text-[10px] text-slate-400 font-medium">/ {product.unit}</span>}</div>
                            <span className={`text-xs ${product.stock === 0 ? 'text-red-500 font-bold' : 'text-slate-500 dark:text-slate-400'}`}>{product.stock === 0 ? 'Out of Stock' : `${product.stock} left`}</span>
                        </div>
                    </div>
                ))
             }
          </div>
      </div>

      {/* Cart Sidebar */}
      <div className="w-full lg:w-96 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-200 dark:border-slate-700 flex flex-col h-full lg:h-auto z-10">
         <div className="p-4 bg-slate-50 dark:bg-slate-700/50 border-b border-slate-200 dark:border-slate-700">
             {(!selectedCustomer || selectedCustomer.id.startsWith('walkin-')) ? (
                 <div className="relative">
                     <div className="flex space-x-2">
                        <div className="relative flex-1"><UserIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={16} /><input type="text" placeholder="Search Member..." value={customerSearch} onChange={(e) => setCustomerSearch(e.target.value)} className="w-full pl-9 pr-2 py-2 text-sm rounded-lg border border-slate-200 dark:border-slate-600 focus:outline-none focus:ring-2 focus:ring-blue-500 shadow-sm bg-white dark:bg-slate-700 dark:text-white dark:placeholder-slate-400" /></div>
                        <button onClick={() => setIsCustomerModalOpen(true)} className="bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-600 text-blue-600 dark:text-blue-400 p-2 rounded-lg transition shadow-sm"><UserPlus size={18} /></button>
                     </div>
                     <div className="mt-3 flex items-center justify-between"><div className="flex items-center text-xs text-slate-500 dark:text-slate-400 bg-slate-200/50 dark:bg-slate-600/50 px-2 py-1 rounded-md border border-slate-200 dark:border-slate-600 w-full"><Footprints size={12} className="mr-1.5 text-slate-400"/> <span>Default: <span className="font-semibold text-slate-600 dark:text-slate-300">Walk-in Customer</span></span></div></div>
                     {customerSearch && (
                        <div className="absolute top-full left-0 right-0 mt-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 shadow-lg rounded-lg max-h-48 overflow-y-auto z-20">{filteredCustomers.map(c => (<div key={c.id} onClick={() => { setSelectedCustomer(c); setCustomerSearch(''); }} className="p-2 hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer border-b border-slate-50 dark:border-slate-700 last:border-0"><p className="font-medium text-sm text-slate-800 dark:text-white">{c.name}</p><p className="text-xs text-slate-500 dark:text-slate-400">{c.phone || c.email}</p></div>))}</div>
                     )}
                 </div>
             ) : (
                 <div className="bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-slate-700 dark:to-slate-800 p-4 rounded-xl border border-blue-100 dark:border-slate-600 shadow-sm relative overflow-hidden group">
                     <div className="flex justify-between items-start mb-3 relative z-10"><div className="flex items-center"><div className="w-10 h-10 rounded-full bg-white dark:bg-slate-600 text-blue-600 dark:text-blue-300 flex items-center justify-center font-bold text-lg shadow-sm border border-blue-100 dark:border-slate-500 mr-3">{selectedCustomer.name.charAt(0).toUpperCase()}</div><div><p className="font-bold text-slate-800 dark:text-white text-sm flex items-center">{selectedCustomer.name}</p><div className="flex items-center text-xs text-slate-500 dark:text-slate-400 mt-0.5">{selectedCustomer.type === 'WALK_IN' ? <span className="bg-slate-200 dark:bg-slate-600 text-slate-600 dark:text-slate-300 px-1.5 py-0.5 rounded text-[10px] font-medium flex items-center"><Footprints size={10} className="mr-1"/> Walk-in</span> : <span className="bg-blue-200 dark:bg-blue-900/50 text-blue-700 dark:text-blue-300 px-1.5 py-0.5 rounded text-[10px] font-medium">Member</span>}</div></div></div><button onClick={() => setSelectedCustomer(createWalkInCustomer())} className="text-slate-400 hover:text-red-500 p-1.5 hover:bg-white dark:hover:bg-slate-700 rounded-full transition-colors"><X size={16} /></button></div>
                     <div className="relative z-10 pt-2 border-t border-blue-200/50 dark:border-slate-600 space-y-2">
                        {isDebt && (<div className="flex justify-between items-center text-xs font-bold text-red-600 dark:text-red-400 px-1"><span>Outstanding Balance</span><span>{symbol}{debtAmount.toFixed(2)}</span></div>)}
                        {selectedCustomer.type === 'MEMBER' && (
                            <div className="px-1 pt-1"><div className="flex justify-between text-[10px] font-medium text-slate-500 dark:text-slate-400 mb-1"><span>Available Credit: <span className={`font-bold ${availableCredit < finalPayableAmount ? 'text-red-500' : 'text-slate-700 dark:text-slate-200'}`}>{symbol}{availableCredit.toFixed(2)}</span></span><span>Limit: {symbol}{creditLimit.toFixed(2)}</span></div><div className="h-2 bg-slate-200 dark:bg-slate-600 rounded-full overflow-hidden shadow-inner"><div className={`h-full transition-all duration-500 ${usagePercentage > 90 ? 'bg-red-500' : usagePercentage > 75 ? 'bg-orange-400' : 'bg-green-500'}`} style={{ width: `${usagePercentage}%` }}></div></div>{paymentMethod === 'STORE_CREDIT' && potentialNewBalance < -creditLimit && (<div className="mt-2 flex items-center text-[10px] text-red-600 dark:text-red-400 font-bold bg-red-50 dark:bg-red-900/20 p-1.5 rounded border border-red-100 dark:border-red-800"><ShieldAlert size={12} className="mr-1 shrink-0"/><span>Limit Exceeded by {symbol}{Math.abs(potentialNewBalance + creditLimit).toFixed(2)}</span></div>)}</div>
                        )}
                        {selectedCustomer.type === 'MEMBER' && (
                            <div className="grid grid-cols-1 pt-1"><button onClick={handleOpenAccountPayment} className={`w-full py-2.5 text-xs font-bold rounded-lg transition flex items-center justify-center border shadow-sm ${isDebt ? 'text-red-100 bg-red-600 hover:bg-red-700 border-red-500' : 'text-indigo-700 dark:text-indigo-300 bg-indigo-50 dark:bg-indigo-900/30 hover:bg-indigo-100 dark:hover:bg-indigo-900/50 border-indigo-200 dark:border-indigo-800'}`}>{isDebt ? <ShieldCheck size={14} className="mr-1.5"/> : <Banknote size={14} className="mr-1.5"/>}{isDebt ? 'Pay Outstanding Debt' : 'Top-up Wallet'}</button></div>
                        )}
                     </div>
                 </div>
             )}
         </div>

         <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-white dark:bg-slate-800">
             {cart.length === 0 ? <div className="h-full flex flex-col items-center justify-center text-slate-400 space-y-4 opacity-50"><ShoppingCart size={48} /><p>Cart is empty</p></div> : 
             cart.map(item => (
                 <div key={item.id} className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-700/50 rounded-lg border border-slate-100 dark:border-slate-700"><div className="flex-1 min-w-0 mr-3"><p className="font-medium text-sm text-slate-800 dark:text-slate-200 truncate">{item.name} {item.unit && <span className="text-xs text-slate-500 dark:text-slate-400">({item.unit})</span>}</p><p className="text-xs text-slate-500 dark:text-slate-400">{symbol}{formatCurrency(item.price)} / unit</p></div><div className="flex items-center space-x-3"><div className="flex items-center bg-white dark:bg-slate-700 rounded border border-slate-200 dark:border-slate-600 shadow-sm overflow-hidden"><button onClick={() => updateQuantity(item.id, -1)} className="p-1.5 hover:bg-slate-100 dark:hover:bg-slate-600 text-slate-500 dark:text-slate-300 border-r border-slate-100 dark:border-slate-600"><Minus size={12}/></button><input type="number" min={item.allowDecimal ? "0.001" : "1"} step={item.allowDecimal ? "0.001" : "1"} max={item.stock} value={item.quantity === 0 ? '' : item.quantity} onChange={(e) => setItemQuantity(item.id, e.target.value)} onBlur={() => handleInputBlur(item.id, item.quantity)} onFocus={(e) => e.target.select()} className={`w-14 text-center text-sm font-semibold outline-none bg-transparent ${item.quantity > item.stock ? 'text-orange-500 dark:text-orange-400' : 'text-slate-800 dark:text-white'} [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none`}/><button onClick={() => updateQuantity(item.id, 1)} disabled={item.quantity >= item.stock} className="p-1.5 hover:bg-slate-100 dark:hover:bg-slate-600 text-slate-500 dark:text-slate-300 disabled:opacity-30 disabled:cursor-not-allowed border-l border-slate-100 dark:border-slate-600"><Plus size={12}/></button></div><button onClick={() => removeFromCart(item.id)} className="text-red-400 hover:text-red-600"><Trash2 size={16} /></button></div></div>
             ))}
         </div>

         {/* Checkout Section */}
