const POS = forwardRef<POSRef, POSProps>(({ 
  products, 
  onCompleteSale, 
  currentUser, 
  customers, 
  onAddCustomer, 
  sales, 
  returns,
  onProcessReturn,
  heldTransactions,
  onHoldTransaction,
  onResumeHold,
  onVoidHold,
  currency,
  showToast,
  storeSettings,
  onCartUpdate,
  resumeHoldId,
  onClearResumeHold,
