  // Frequent Items Calculation
  const frequentProducts = useMemo(() => {
    const salesCounts: Record<string, number> = {};
    sales.forEach(s => {
        s.items.forEach(i => {
            salesCounts[i.productId] = (salesCounts[i.productId] || 0) + i.quantity;
        });
    });
    return products
        .map(p => ({ ...p, count: salesCounts[p.id] || 0 }))
