nk-0"><img src={(s.item as Product).imageUrl || "https://placehold.co/40?text=No+Img"} alt="" className="w-full h-full object-cover"/></div><div className="flex-1"><p className="text-sm font-medium text-slate-800 dark:text-white">{(s.item as Product).name}</p><div className="flex items-center text-xs text-slate-500 dark:text-slate-400"><span className="text-green-600 dark:text-green-400 font-bold">{symbol}{formatCurrency((s.item as Product).price)}</span>{(s.item as Product).unit && <span className="ml-1 text-slate-400">/ {(s.item as Product).unit}</span>}<span className="ml-auto text-[10px] font-mono opacity-50">{(s.item as Product).sku}</span></div></div></>)}</div>))}</div>)}</div>
