0 dark:text-slate-200'}`}>{symbol}{availableCredit.toFixed(2)}</span></span><span>Limit: {symbol}{creditLimit.toFixed(2)}</span></div><div className="h-2 bg-slate-200 dark:bg-slate-600 rounded-full overflow-hidden shadow-inner"><div className={`h-full transition-all duration-500 ${usagePercentage > 90 ? 'bg-red-500' : usagePercentage > 75 ? 'bg-orange-400' : 'bg-green-500'}`} style={{ width: `${usagePercentage}%` }}></div></div>{paymentMethod === 'STORE_CREDIT' && potentialNewBalance < -creditLimit && (<div className="mt-2 flex items-center text-[10px] text-red-600 dark:text-red-400 font-bold bg-red-50 dark:bg-red-900/20 p-1.5 rounded border border-red-100 dark:border-red-800"><ShieldAlert size={12} className="mr-1 shrink-0"/><span>Limit Exceeded by {symbol}{Math.abs(potentialNewBalance + creditLimit).toFixed(2)}</span></div>)}</div>)}{selectedCustomer.type === 'MEMBER' && (<div className="grid grid-cols-1 pt-1"><button onClick={handleOpenAccountPayment} className={`w-full py-2.5 text-xs font-bold rounded-lg transition flex items-center justify-center border shadow-sm ${isDebt ? 'text-red-100 bg-red-600 hover:bg-red-700 border-red-500' : 'text-indigo-700 dark:text-indigo-300 bg-indigo-50 dark:bg-indigo-900/30 hover:bg-indigo-100 dark:hover:bg-indigo-900/50 border-indigo-200 dark:border-indigo-800'}`}>{isDebt ? <ShieldCheck size={14} className="mr-1.5"/> : <Banknote size={14} className="mr-1.5"/>}{isDebt ? 'Pay Outstanding Debt' : 'Top-up Wallet'}</button></div>)}</div></div>
