ocus value={accountPaymentAmount} onChange={(e) => setAccountPaymentAmount(e.target.value)} className="w-full p-3 border rounded-lg outline-none focus:ring-2 focus:ring-indigo-500 text-lg font-bold bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" placeholder="0.00" />{accountPaymentAmount && (<div className="mt-2 p-2 bg-slate-50 dark:bg-slate-700/50 rounded flex justify-between items-center text-xs"><span className="text-slate-500 dark:text-slate-400">New Balance:</span><span className={`font-bold ${previewBalance < 0 ? 'text-red-500' : 'text-green-500'}`}>{symbol}{Math.abs(previewBalance).toFixed(2)} {previewBalance < 0 ? '(DR)' : '(CR)'}</span></div>)}</div><div><label className="block text-xs font-medium text-slate-500 dark:text-slate-400 mb-1">Payment Method</label><div className="flex space-x-2">{['CASH', 'CARD', 'DIGITAL'].map(m => (<button key={m} onClick={() => setAccountPaymentMethod(m as any)} className={`flex-1 py-2 text-xs font-bold rounded border transition ${accountPaymentMethod === m ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white dark:bg-slate-700 text-slate-500 dark:text-slate-300 border-slate-200 dark:border-slate-600 hover:bg-slate-50 dark:hover:bg-slate-600'}`}>{m}</button>))}</div></div></div><div className="flex justify-end space-x-2 mt-6"><button onClick={() => setIsPaymentModalOpen(false)} className="px-4 py-2 text-sm text-slate-500 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-700 rounded-lg">Cancel</button><button onClick={handleAccountPayment} className="px-4 py-2 text-sm bg-indigo-600 text-white font-bold rounded-lg hover:bg-indigo-700 shadow-md">{(selectedCustomer.storeCredit || 0) < 0 ? 'Confirm Payment' : 'Confirm Deposit'}</button></div></div></div>
      )}

