 storeSettings.creditTerms.length > 0 && (<div className="mb-4 p-3 bg-indigo-50 dark:bg-slate-700/50 rounded-lg border border-indigo-100 dark:border-slate-600"><label className="block text-xs font-medium text-indigo-600 dark:text-slate-300 mb-1">Payment Term / Due Date</label><div className="relative"><select value={selectedCreditTermId} onChange={(e) => setSelectedCreditTermId(e.target.value)} className="w-full p-2 bg-white dark:bg-slate-800 border border-indigo-200 dark:border-slate-500 rounded-md text-sm outline-none focus:ring-2 focus:ring-indigo-500 appearance-none">{storeSettings.creditTerms.map(term => (<option key={term.id} value={term.id}>{term.name} ({term.rate}% Interest) - {term.days} Days</option>))}</select><ChevronDown className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={14}/></div></div>)}<div className="space-y-1 mb-4 border-t border-slate-200 dark:border-slate-600 pt-3"><div className="flex justify-between items-center text-sm text-slate-600 dark:text-slate-400"><span>Subtotal</span><span>{symbol}{formatCurrency(cartSubtotal)}</span></div>{storeSettings.taxRate > 0 && (<div className="flex justify-between items-center text-sm text-slate-600 dark:text-slate-400"><span>{storeSettings.taxName} ({storeSettings.taxRate}%) {storeSettings.taxType === 'EXCLUSIVE' ? 'Added' : 'Inc.'}</span><span>{symbol}{formatCurrency(calculatedTax)}</span></div>)}{creditMarkupAmount > 0 && (<div className="flex justify-between items-center text-sm text-slate-600 dark:text-slate-400"><span>Credit Interest ({currentCreditTerm ? currentCreditTerm.rate : storeSettings.creditMarkupRate}%)</span><span>{symbol}{formatCurrency(creditMarkupAmount)}</span></div>)}<div className="flex justify-between items-center text-xl font-bold text-slate-800 dark:text-white pt-1"><span>Total</span><span>{symbol}{formatCurrency(finalPayableAmount)}</span></div></div><div className="grid grid-cols-4 gap-2"><button onClick={handleHoldClick} disabled={cart.length === 0 || !canHold} className={`col-span-1 py-3 rounded-lg font-bold flex flex-col items-center justify-center transition border ${cart.length > 0 && canHold ? 'bg-orange-50 dark:bg-orange-900/30 border-orange-200 dark:border-orange-800 text-orange-600 dark:text-orange-400 hover:bg-orange-100 dark:hover:bg-orange-900/50' : 'bg-slate-100 dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-400 cursor-not-allowed opacity-75'}`} title={!canHold ? "Hold not available for Members/Credit" : "Hold Transaction"}><PauseCircle size={20} className="mb-0.5"/><span className="text-[10px] uppercase">Hold</span></button><button onClick={handleCheckout} disabled={cart.length === 0 || (paymentMethod === 'CASH' && changeDue < 0)} className={`col-span-3 py-3 rounded-lg font-bold text-white shadow-lg transition ${cart.length > 0 && !(paymentMethod === 'CASH' && changeDue < 0) ? 'bg-blue-600 hover:bg-blue-700 transform hover:-translate-y-1' : 'bg-slate-400 cursor-not-allowed'}`}>Complete Sale</button></div></div>
