red-500' : 'text-orange-500'}`}>{isExpired ? 'Expired' : `Expires in ${Math.ceil(timeLeft / 60000)} mins`}</div></div><div className="flex flex-col gap-2"><button onClick={() => resumeHold(h)} className="px-3 py-1.5 bg-blue-600 text-white text-xs font-bold rounded hover:bg-blue-700 shadow-sm flex items-center justify-center"><PlayCircle size={14} className="mr-1"/> Resume</button><button onClick={() => onVoidHold(h.id)} className="px-3 py-1.5 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 text-xs font-bold rounded border border-red-200 dark:border-red-800 flex items-center justify-center"><Trash size={14} className="mr-1"/> Void</button></div></div>); })}</div></div>
