  const categories: string[] = ['All', ...Array.from(new Set(products.map(p => p.category))) as string[]];

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
