             </div>
             <div className="relative" ref={searchInputRef}><div className="absolute left-3 top-1/2 transform -translate-y-1/2 flex items-center gap-2 pointer-events-none"><Search className="text-slate-400" size={20} /></div><input type="text" placeholder={isScannerMode ? "Waiting for barcode scan..." : "Search products by name, SKU, or category..."} value={searchTerm} onFocus={() => setIsSearchFocused(true)} onKeyDown={handleSearchKeyPress} onChange={(e) => { setSearchTerm(e.target.value); setIsSearchFocused(true); }} className={`w-full pl-10 pr-12 py-3 rounded-xl border-2 transition-all focus:outline-none focus:ring-4 bg-slate-50 dark:bg-slate-700 dark:text-white dark:placeholder-slate-400 ${isScannerMode ? 'border-indigo-500 focus:ring-indigo-500/20' : 'border-slate-200 dark:border-slate-600 focus:ring-blue-500/20 focus:border-blue-500'}`}/>{searchTerm && (<button onClick={() => setSearchTerm('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"><X size={20}/></button>)}{isSearchFocused && searchTerm && suggestions.length > 0 && (<div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-800 rounded-xl shadow-2xl border border-slate-100 dark:border-slate-700 overflow-hidden z-[60]">{suggestions.map((s, idx) => (<div key={idx} onClick={() => { if (s.type === 'CATEGORY') { setActiveCategory(s.item); setSearchTerm(''); setIsSearchFocused(false); } else { addToCart(s.item as Product); setIsSearchFocused(false); } }} className="flex items-center p-3 hover:bg-blue-50 dark:hover:bg-slate-700 cursor-pointer border-b border-slate-50 dark:border-slate-700 last:border-0 transition-colors">{s.type === 'CATEGORY' ? (<><Tag size={18} className="text-blue-500 mr-3" /><div><p className="text-sm font-medium text-slate-800 dark:text-white">Category: <span className="text-blue-600 dark:text-blue-400">{s.item}</span></p></div></>) : (<><div className="w-10 h-10 rounded bg-slate-100 dark:bg-slate-700 mr-3 overflow-hidden shrink-0"><img src={(s.item as Product).imageUrl || "https://placehold.co/40?text=No+Img"} alt="" className="w-full h-full object-cover"/></div><div className="flex-1"><p className="text-sm font-medium text-slate-800 dark:text-white">{(s.item as Product).name}</p><div className="flex items-center text-xs text-slate-500 dark:text-slate-400"><span className="text-green-600 dark:text-green-400 font-bold">{symbol}{formatCurrency((s.item as Product).price)}</span>{(s.item as Product).unit && <span className="ml-1 text-slate-400">/ {(s.item as Product).unit}</span>}<span className="ml-auto text-[10px] font-mono opacity-50">{(s.item as Product).sku}</span></div></div></>)}</div>))}</div>)}</div>
             <div className="flex space-x-2 overflow-x-auto pb-1 scrollbar-hide"><button onClick={() => setActiveCategory('All')} className={`px-4 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition flex items-center gap-1.5 ${activeCategory === 'All' ? 'bg-slate-900 text-white shadow-md dark:bg-white dark:text-slate-900' : 'bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600'}`}><Zap size={12}/> All Products</button>{categories.filter(c => c !== 'All').map(cat => (<button key={cat} onClick={() => setActiveCategory(cat)} className={`px-4 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition ${activeCategory === cat ? 'bg-blue-600 text-white shadow-md' : 'bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-600'}`}>{cat}</button>))}</div>
          </div>

          {!searchTerm && activeCategory === 'All' && frequentProducts.length > 0 && (<div className="px-4 py-3 bg-blue-50/50 dark:bg-blue-900/10 border-b border-slate-100 dark:border-slate-700"><div className="flex items-center gap-2 mb-2"><Star size={14} className="text-amber-500 fill-amber-500"/><span className="text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400">Top Frequent Items</span></div><div className="flex gap-3 overflow-x-auto pb-1 scrollbar-hide">{frequentProducts.map(p => (<div key={p.id} onClick={() => addToCart(p)} className="bg-white dark:bg-slate-800 rounded-lg p-2 border border-slate-200 dark:border-slate-600 shadow-sm flex items-center gap-3 shrink-0 cursor-pointer hover:border-blue-400 hover:shadow-md transition active:scale-95 group"><div className="w-8 h-8 rounded bg-slate-100 dark:bg-slate-700 shrink-0 overflow-hidden"><img src={p.imageUrl || "https://placehold.co/40"} className="w-full h-full object-cover" alt=""/></div><div><p className="text-xs font-bold text-slate-800 dark:text-white truncate max-w-[80px]">{p.name}</p><p className="text-[10px] font-bold text-blue-600 dark:text-blue-400">{symbol}{formatCurrency(p.price)}</p></div></div>))}</div></div>)}

