const SimpleBarcode = ({ value }: { value: string }) => {
    const bars = [];
    let hash = 0;
    for (let i = 0; i < value.length; i++) {
        hash = ((hash << 5) - hash) + value.charCodeAt(i);
        hash |= 0;
    }
    const seededRandom = () => {
        const x = Math.sin(hash++) * 10000;
        return x - Math.floor(x);
    };
    for(let i=0; i<30; i++) {
        const r = seededRandom();
        let w = 2; 
        if (r > 0.66) w = 4;
        else if (r < 0.33) w = 1;
        bars.push(w);
    }
    return (
        <div className="flex flex-col items-center justify-center w-full py-2">
            <div className="flex justify-center h-12">
                {bars.map((w, i) => (
                    <div key={i} style={{ 
                        width: `${w}px`, 
                        height: '100%', 
                        backgroundColor: 'black', 
                        marginLeft: '2px', 
                        marginRight: '2px' 
                    }}></div>
                ))}
            </div>
            <div className="text-[10px] font-mono mt-1 tracking-[0.3em] uppercase">{value}</div>
        </div>
    );
};

const getMatchScore = (text: string, query: string): number => {
    const t = text.toLowerCase();
    const q = query.toLowerCase().trim();
    if (!q) return 0;
    if (t === q) return 100;
    if (t.startsWith(q)) return 80;
    if (t.includes(q)) return 60;
    const tTokens = t.split(' ');
    const qTokens = q.split(' ');
    if (qTokens.length > 1) {
        const allTokensFound = qTokens.every(qt => tTokens.some(tt => tt.includes(qt)));
        if (allTokensFound) return 70;
    }
    let tIdx = 0;
    let qIdx = 0;
    let matches = 0;
    while (tIdx < t.length && qIdx < q.length) {
        if (t[tIdx] === q[qIdx]) {
            qIdx++;
            matches++;
        }
        tIdx++;
    }
    if (q.length > 2 && matches / q.length > 0.8) return 40;
    return 0;
};

