 storeSettings.creditTerms.length > 0 && (<div className="mb-4 p-3 bg-indigo-50 dark:bg-slate-700/50 rounded-lg border border-indigo-100 dark:border-slate-600"><label className="block text-xs font-medium text-indigo-600 dark:text-slate-300 mb-1">Payment Term / Due Date</label><div className="relative"><select value={selectedCreditTermId} onChange={(e) => setSelectedCreditTermId(e.target.value)} className="w-full p-2 bg-white dark:bg-slate-800 border border-indigo-200 dark:border-slate-500 rounded-md text-sm outline-none focus:ring-2 focus:ring-indigo-500 appearance-none">{storeSettings.creditTerms.map(term => (<option key={term.id} value={term.id}>{term.name} ({term.rate}% Interest) - {term.days} Days</option>))}</select><ChevronDown className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={14}/></div></div>)}<div className="space-y-1 mb-4 border-t border-slate-200 dark:border-slate-600 pt-3"><div className="flex justify-between items-center text-sm text-slate-600 dark:text-slate-400"><span>Subtotal</span><span>{symbol}{formatCurrency(cartSubtotal)}</span></div>{storeSettings.taxRate > 0 && (<div className="flex justify-between items-center text-sm text-slate-600 dark:text-slate-400"><span>{storeSettings.taxName} ({storeSettings.taxRate}%) {storeSettings.taxType === 'EXCLUSIVE' ? 'Added' : 'Inc.'}</span><span>{symbol}{formatCurrency(calculatedTax)}</span></div>)}{creditMarkupAmount > 0 && (<div className="flex justify-between items-center text-sm text-slate-600 dark:text-slate-400"><span>Credit Interest ({currentCreditTerm ? currentCreditTerm.rate : storeSettings.creditMarkupRate}%)</span><span>{symbol}{formatCurrency(creditMarkupAmount)}</span></div>)}<div className="flex justify-between items-center text-xl font-bold text-slate-800 dark:text-white pt-1"><span>Total</span><span>{symbol}{formatCurrency(finalPayableAmount)}</span></div></div><div className="grid grid-cols-4 gap-2"><button onClick={handleHoldClick} disabled={cart.l