= 'A4' ? 'text-2xl' : 'text-base'}`}>{storeSettings.storeName}</h1><div className="text-gray-500 space-y-0.5 leading-tight"><p>{storeSettings.storeAddress}</p><p>Tel: {storeSettings.storePhone}</p>{storeSettings.storeEmail && <p>{storeSettings.storeEmail}</p>}</div></div><div className="border-b border-dashed border-gray-400 mb-2"></div>{completedPayment && (<><div className="text-center mb-4"><h2 className="font-bold text-lg uppercase">Payment Receipt</h2><p className="text-gray-500">{new Date(completedPayment.timestamp).toLocaleString()}</p></div><div className="space-y-2 mb-4"><div className="flex justify-between"><span>Customer:</span><span className="font-bold">{completedPayment.customerName}</span></div><div className="flex justify-between"><span>Ref ID:</span><span>{completedPayment.id.split('-')[1]}</span></div><div className="border-b border-dashed border-gray-400 my-2"></div><div className="flex justify-between"><span>Previous Balance:</span><span>{symbol}{formatCurrency(completedPayment.newBalance - completedPayment.amount)}</span></div><div className="flex justify-between font-bold text-lg"><span>Amount Paid:</span><span>{symbol}{formatCurrency(completedPayment.amount)}</span></div><div className="flex justify-between text-gray-600"><span>Method:</span><span>{completedPayment.paymentMethod || 'CASH'}</span></div><div className="border-b border-dashed border-gray-400 my-2"></div><div className="flex justify-between font-bold"><span>New Balance:</span><span>{symbol}{formatCurrency(completedPayment.newBalance)}</span></div></div></>)}{completedSale && (<><div className="mb-2 space-y-1"><div className="flex justify-between"><span>Date: {new Date(completedSale.timestamp).toLocaleDateString()}</span><span>Time: {new Date(completedSale.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span></div><div className="flex justify-between"><span>Order #: {completedSale.id.split('-')[1]}</span><span>Cashier: {currentUser.name.split(' ')[0]}</span></div>{completedSale.customerName && (<div className="flex justify-between font-bold mt-1"><span>Customer:</span><span>{completedSale.customerName}</span></div>)}</div><div className="border-b border-dashed border-gray-400 mb-2"></div><div className="flex font-bold mb-1 pb-1 border-b border-gray-300"><span className="flex-1">Item</span><span className="w-8 text-center">Qty</span><span className="w-16 text-right">Price</span><span className="w-16 text-right">Total</span></div><div className="flex-1 mb-2">{completedSale.items.map((item, idx) => { const product = products.find(p => p.id === item.productId); return (<div key={idx} className="mb-2"><div className="font-bold">{item.productName}{item.unit && <span className="text-[10px] font-normal ml-1">({item.unit})</span>}</div>{product?.sku && <div className="text-[10px] text-gray-500 mb-0.5">SKU: {product.sku}</div>}<div className="flex"><span className="flex-1"></span><span className="w-8 text-center">{item.quantity}</span><span className="w-16 text-right">{symbol}{formatCurrency(item.priceAtSale)}</span><span className="w-16 text-right font-bold">{symbol}{formatCurrency(item.priceAtSale * item.quantity)}</span></div></div>); })}</div><div className="border-b border-dashed border-gray-400 mb-2"></div><div className="space-y-1 text-right mb-2"><div className="flex justify-between"><span>Subtotal</span><span>{symbol}{formatCurrency(completedSale.subTotal)}</span></div>{completedSale.taxRate && completedSale.taxRate > 0 && (<div className="flex justify-between text-gray-600 text-xs"><span>{completedSale.taxName} ({completedSale.taxRate}%){completedSale.taxType === 'INCLUSIVE' ? ' (Included)' : ' (Added)'}</span><span>{symbol}{formatCurrency(completedSale.totalTax)}</span></div>)}{completedSale.creditMarkupAmount && completedSale.creditMarkupAmount > 0 && (<div className="flex justify-between text-gray-600 text-xs"><span>Interest ({completedSale.creditMarkupRate}%) {completedSale.creditTermName}</span><span>{symbol}{formatCurrency(completedSale.creditMarkupAmount)}</span></div>)}<div className="flex justify-between font-bold text-lg border-t border-black pt-1 mt-1"><span>TOTAL</span><span>{symbol}{formatCurrency(completedSale.totalAmount)}</span></div></div><div className="mb-4 pt-1 border-t border-dashed border-gray-400"><div className="flex justify-between font-bold text-sm"><span>Payment Method:</span><span className="uppercase">{completedSale.paymentMethod.replace('_', ' ')}</span></div>{completedSale.paymentMethod === 'STORE_CREDIT' && completedSale.creditDueDate && (<div className="flex justify-between text-xs mt-1 font-medium"><span>Due Date:</span><span>{new Date(completedSale.creditDueDate).toLocaleDateString()}</span></div>)}{completedSale.paymentMethod === 'CASH' && completedSale.amountTendered !== undefined && (<><div className="flex justify-between text-xs mt-1"><span>Cash Tendered:</span><span>{symbol}{formatCurrency(completedSale.amountTendered)}</span></div><div className="flex justify-between text-xs"><span>Change:</span><span>{symbol}{formatCurrency(completedSale.change || 0)}</span></div></>)}</div></>)}<div className="text-center mt-auto">{storeSettings.receiptHeader && <p className="font-bold mb-1">{storeSettings.receiptHeader}</p>}{storeSettings.receiptFooter ? <p className="text-xs text-gray-500 mb-2 whitespace-pre-wrap">{storeSettings.receiptFooter}</p> : <p className="text-xs text-gray-500 mb-2">Thank you for your business!</p>}{completedSale && <SimpleBarcode value={completedSale.id.toUpperCase()} />}{completedPayment && <SimpleBarcode value={completedPayment.id.toUpperCase()} />}</div></div></div><div className="p-4 border-t border-slate-100 dark:border-slate-700 bg-slate-50 dark:bg-slate-700/50 rounded-b-xl flex justify-center no-print"><button onClick={handleNewSale} className="text-blue-600 dark:text-blue-400 font-bold hover:underline">Start New Sale</button></div></div></div>
        )}

        {isCustomerModalOpen && (
            <div className="fixed inset-0 bg-black/50 z-[120] flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-sm:w-full max-w-sm p-6 animate-in slide-in-from-top-10 duration-200"><h3 className="text-lg font-bold mb-4 text-slate-800 dark:text-white">New Customer</h3><div className="space-y-4"><div><label className="block text-xs font-medium text-slate-500 dark:text-slate-400 mb-1">Name <span className="text-red-500">*</span></label><input type="text" value={newCustomerName} onChange={(e) => setNewCustomerName(e.target.value)} className="w-full p-2 border rounded-lg outline-none focus:border-blue-500 bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white dark:placeholder-slate-400" placeholder="Full Name" /></div><div><label className="block text-xs font-medium text-slate-500 dark:text-slate-400 mb-1">Phone</label><input type="text" value={newCustomerPhone} onChange={(e) => setNewCustomerPhone(e.target.value)} className="w-full p-2 border rounded-lg outline-none focus:border-blue-500 bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white dark:placeholder-slate-400" /></div><div><label className="block text-xs font-medium text-slate-500 dark:text-slate-400 mb-1">Email</label><input type="email" value={newCustomerEmail} onChange={(e) => setNewCustomerEmail(e.target.value)} className="w-full p-2 border rounded-lg outline-none focus:border-blue-500 bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white dark:placeholder-slate-400" /></div><div className="flex justify-end space-x-2 pt-2"><button onClick={() => setIsCustomerModalOpen(false)} className="px-3 py-2 text-sm text-slate-500 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-700 rounded-lg">Cancel</button><button onClick={handleCreateCustomer} disabled={!newCustomerName} className="px-3 py-2 text-sm bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50">Create</button></div></div></div>
            </div>
        )}

        {isHoldModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-[120] flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-sm:w-full max-w-sm p-6 animate-in fade-in zoom-in-95 duration-200"><div className="flex items-center text-orange-600 mb-4"><PauseCircle size={24} className="mr-2"/><h3 className="text-lg font-bold text-slate-800 dark:text-white">Hold Transaction</h3></div><p className="text-sm text-slate-500 dark:text-slate-400 mb-4">Save current transaction to resume later. This will clear the current cart.</p><div className="space-y-4"><div><label className="block text-xs font-medium text-slate-500 dark:text-slate-400 mb-1">Customer</label><div className="font-bold text-slate-800 dark:text-white">{selectedCustomer?.name || 'Guest'}</div></div><div><label className="block text-xs font-medium text-slate-500 dark:text-slate-400 mb-1">Resume Within (Minutes)</label><div className="flex space-x-2">{[15, 30, 60].map(m => (<button key={m} onClick={() => setHoldDuration(m)} className={`flex-1 py-2 text-sm font-medium rounded border ${holdDuration === m ? 'bg-orange-50 dark:bg-orange-900/30 border-orange-200 dark:border-orange-800 text-orange-700 dark:text-orange-400' : 'bg-white dark:bg-slate-700 border-slate-200 dark:border-slate-600 text-slate-600 dark:text-slate-300'}`}>{m}m</button>))}</div></div><div><label className="block text-xs font-medium text-slate-500 dark:text-slate-400 mb-1">Note (Optional)</label><input type="text" value={holdNote} onChange={e => setHoldNote(e.target.value)} className="w-full p-2 border rounded-lg outline-none focus:ring-2 focus:ring-orange-500 bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" placeholder="e.g. Forgot wallet"/></div></div><div className="flex justify-end space-x-2 mt-6"><button onClick={() => setIsHoldModalOpen(false)} className="px-4 py-2 text-slate-500 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-700 rounded-lg">Cancel</button><button onClick={confirmHold} className="px-4 py-2 bg-orange-600 text-white font-bold rounded-lg hover:bg-orange-700 shadow-md">Confirm Hold</button></div></div>
          </div>
        )}

        {isHeldListOpen && (
            <div className="fixed inset-0 bg-black/50 z-[120] flex items-center justify-center p-4 backdrop-blur-sm">
                <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col animate-in zoom-in-95 duration-200"><div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-xl"><h3 className="font-bold text-slate-800 dark:text-white flex items-center"><PauseCircle className="mr-2 text-orange-500" size={20}/> Held Transactions</h3><button onClick={() => setIsHeldListOpen(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200"><X size={24}/></button></div><div className="p-4 border-b border-slate-100 dark:border-slate-700"><div className="relative"><Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="Search holds..." value={heldSearch} onChange={(e) => setHeldSearch(e.target.value)} className="w-full pl-10 p-2 border rounded-lg bg-slate-50 dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div></div><div className="flex-1 overflow-y-auto p-4 space-y-3">{filteredHeldTransactions.length === 0 ? <div className="text-center text-slate-400 py-8">No held transactions found.</div> : filteredHeldTransactions.map(h => { const timeLeft = h.expiryTime - Date.now(); const isExpired = timeLeft < 0; return (<div key={h.id} className={`p-4 rounded-lg border flex justify-between items-center ${isExpired ? 'bg-red-50 dark:bg-red-900/10 border-red-100 dark:border-red-800' : 'bg-white dark:bg-slate-700/50 border-slate-200 dark:border-slate-600'}`}><div><div className="font-bold text-slate-800 dark:text-white">{h.customer.name}</div><div className="text-xs text-slate-500 dark:text-slate-400">{h.items.length} items • held {new Date(h.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</div>{h.note && <div className="text-xs italic text-slate-500 mt-1">"{h.note}"</div>}<div className={`text-xs font-bold mt-1 ${isExpired ? 'text-red-500' : 'text-orange-500'}`}>{isExpired ? 'Expired' : `Expires in ${Math.ceil(timeLeft / 60000)} mins`}</div></div><div className="flex flex-col gap-2"><button onClick={() => resumeHold(h)} className="px-3 py-1.5 bg-blue-600 text-white text-xs font-bold rounded hover:bg-blue-700 shadow-sm flex items-center justify-center"><PlayCircle size={14} className="mr-1"/> Resume</button><button onClick={() => onVoidHold(h.id)} className="px-3 py-1.5 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 text-xs font-bold rounded border border-red-200 dark:border-red-800 flex items-center justify-center"><Trash size={14} className="mr-1"/> Void</button></div></div>); })}</div></div>
            </div>
        )}
    </div>
  );
});

export default POS;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, StockAdjustment, AdjustmentType, User, ReturnTransaction, Customer, Sale, PriceHistory } from '../types';
import { generateProductDescription, suggestRestock } from '../services/geminiService';
import { Plus, Edit2, Trash2, Search, Wand2, RefreshCw, AlertCircle, AlertTriangle, CheckCircle, ClipboardEdit, History, X, ArrowRight, RotateCcw, ClipboardList, Filter, ArrowUp, ArrowDown, ChevronsUpDown, XCircle, ChevronDown, Check, TrendingUp, DollarSign, BarChart3, Package, Eye, Tags, ArrowBigUp, ArrowBigDown, Printer, FileSpreadsheet, Upload, Image as ImageIcon, ArrowRightLeft, Boxes, Scale, CheckSquare, Layers, Clock } from 'lucide-react';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  stockAdjustments: StockAdjustment[];
  onAdjustStock: (adjustment: StockAdjustment) => void;
  onBulkAdjustStock: (adjustments: StockAdjustment[]) => void;
  currentUser: User;
  currency: string;
  showToast: (message: string, type: 'SUCCESS' | 'ERROR' | 'INFO') => void;
  returns: ReturnTransaction[];
  customers: Customer[];
  sales: Sale[];
  priceHistory: PriceHistory[];
  onLogPriceChange: (log: PriceHistory) => void;
}

type SortField = 'name' | 'sku' | 'category' | 'price' | 'stock' | 'stockExpiryDate' | 'cost' | 'margin';
type SortDirection = 'asc' | 'desc';

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, stockAdjustments, onAdjustStock, onBulkAdjustStock, currentUser, currency, showToast, returns, customers, sales, priceHistory, onLogPriceChange }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Search & Filter State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('ALL');
  const [filterStockStatus, setFilterStockStatus] = useState<'ALL' | 'LOW' | 'OUT' | 'IN'>('ALL');
  const [filterExpiry, setFilterExpiry] = useState<'ALL' | 'EXPIRED' | 'SOON' | 'VALID'>('ALL');

  // Sorting State
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');

  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [isLoadingAi, setIsLoadingAi] = useState(false);

  // Adjustment State
  const [isAdjModalOpen, setIsAdjModalOpen] = useState(false);
  const [selectedProductForAdj, setSelectedProductForAdj] = useState<Product | null>(null);
  const [adjType, setAdjType] = useState<AdjustmentType>('ADD');
  const [adjQuantity, setAdjQuantity] = useState(0);
  const [adjReason, setAdjReason] = useState('Stock Count Correction');
  const [adjNotes, setAdjNotes] = useState('');

  // Bulk Adjustment State
  const [isBulkAdjModalOpen, setIsBulkAdjModalOpen] = useState(false);
  const [bulkAdjType, setBulkAdjType] = useState<AdjustmentType>('ADD');
  const [bulkAdjQuantity, setBulkAdjQuantity] = useState(0);
  const [bulkAdjReason, setBulkAdjReason] = useState('Stock Count Correction');
  const [bulkAdjNotes, setBulkAdjNotes] = useState('');

  // Conversion State
  const [isConversionModalOpen, setIsConversionModalOpen] = useState(false);
  const [convSourceId, setConvSourceId] = useState('');
  const [convTargetId, setConvTargetId] = useState('');
  const [convSourceQty, setConvSourceQty] = useState(1);
  const [convTargetQty, setConvTargetQty] = useState(1);

  // Detailed View State
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
  const [selectedProductDetails, setSelectedProductDetails] = useState<Product | null>(null);
  const [historyView, setHistoryView] = useState<'ADJUSTMENTS' | 'RETURNS' | 'PRICE'>('ADJUSTMENTS');

  // Dropdown Refs
  const categoryDropdownRef = useRef<HTMLDivElement>(null);
  const unitDropdownRef = useRef<HTMLDivElement>(null);
  const [isCategoryDropdownOpen, setIsCategoryDropdownOpen] = useState(false);
  const [isUnitDropdownOpen, setIsUnitDropdownOpen] = useState(false);

  // Form State
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false
  });

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  };

  const symbol = getCurrencySymbol(currency);
  const formatCurrency = (val: number) => val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const formatNumber = (val: number) => val.toLocaleString('en-US', { maximumFractionDigits: 3 });

  const categories = useMemo(() => {
      const cats = new Set(products.map(p => p.category).filter(Boolean));
      return ['ALL', ...Array.from(cats).sort()];
  }, [products]);

  const uniqueCategories = useMemo(() => {
      const cats = new Set(products.map(p => p.category).filter(Boolean));
      return Array.from(cats).sort();
  }, [products]);

  const uniqueUnits = useMemo(() => {
      const productUnits = new Set(products.map(p => p.unit).filter(Boolean) as string[]);
      const defaultUnits = ['pcs', 'kg', 'g', 'mg', 'l', 'ml', 'box', 'pack', 'sack', 'bottle', 'can', 'jar', 'm', 'cm', 'roll', 'set', 'pair', 'dozen', 'bundle', 'tray'];
      defaultUnits.forEach(u => productUnits.add(u));
      return Array.from(productUnits).sort();
  }, [products]);

  const processedProducts = useMemo(() => {
      let filtered = products.filter(p => 
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        p.sku.toLowerCase().includes(searchTerm.toLowerCase())
      );
      if (filterCategory !== 'ALL') filtered = filtered.filter(p => p.category === filterCategory);
      if (filterStockStatus !== 'ALL') {
          if (filterStockStatus === 'OUT') filtered = filtered.filter(p => p.stock === 0);
          if (filterStockStatus === 'LOW') filtered = filtered.filter(p => p.stock > 0 && p.stock <= p.minStockLevel);
          if (filterStockStatus === 'IN') filtered = filtered.filter(p => p.stock > p.minStockLevel);
      }
      if (filterExpiry !== 'ALL') {
          filtered = filtered.filter(p => {
              const days = getDaysUntilExpiry(p.stockExpiryDate);
              if (filterExpiry === 'EXPIRED') return days !== null && days < 0;
              if (filterExpiry === 'SOON') return days !== null && days >= 0 && days <= 30;
              if (filterExpiry === 'VALID') return days === null || days > 30;
              return true;
          });
      }
      return filtered.sort((a, b) => {
          let valA: any = a[sortField];
          let valB: any = b[sortField];
          if (sortField === 'margin') {
              valA = a.price > 0 ? ((a.price - a.cost) / a.price) : -999;
              valB = b.price > 0 ? ((b.price - b.cost) / b.price) : -999;
          }
          if (typeof valA === 'string') return sortDirection === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
          return sortDirection === 'asc' ? (valA < valB ? -1 : 1) : (valB < valA ? -1 : 1);
      });
  }, [products, searchTerm, filterCategory, filterStockStatus, filterExpiry, sortField, sortDirection]);

  // Excel/CSV Export Feature
  const exportToExcel = () => {
    const headers = ["Product Name", "SKU", "Category", "Stock", "Unit", "Cost Price", "Selling Price", "Min Level", "Expiry Date", "Margin (%)"];
    const rows = processedProducts.map(p => {
        const margin = p.price > 0 ? ((p.price - p.cost) / p.price * 100).toFixed(2) : '0';
        return [
            `"${p.name.replace(/"/g, '""')}"`, 
            `"${p.sku}"`, 
            `"${p.category}"`, 
            p.stock, 
            `"${p.unit || 'pcs'}"`, 
            p.cost.toFixed(2), 
            p.price.toFixed(2), 
            p.minStockLevel, 
            `"${p.stockExpiryDate || 'N/A'}"`, 
            `"${margin}%"`
        ].join(",");
    });
    const csvContent = "\uFEFF" + [headers.join(","), ...rows].join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `nexus_inventory_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast("Inventory list exported to CSV (Excel format).", "SUCCESS");
  };

  const getDaysUntilExpiry = (dateString?: string) => {
      if (!dateString) return null;
      const [year, month, day] = dateString.split('-').map(Number);
      const expiry = new Date(year, month - 1, day);
      const diffTime = expiry.getTime() - new Date().setHours(0,0,0,0);
      return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const getExpiryStatus = (days: number | null) => {
      if (days === null) return 'NONE';
      if (days < 0) return 'EXPIRED';
      if (days <= 30) return 'WARNING';
      return 'OK';
  };

  const handleOpenModal = (product?: Product) => {
    if (product) { setEditingProduct(product); setFormData(product); }
    else { setEditingProduct(null); setFormData({ name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false }); }
    setIsModalOpen(true);
  };

  const handleOpenAdjModal = (product: Product) => { setSelectedProductForAdj(product); setAdjType('ADD'); setAdjQuantity(0); setAdjReason('Stock Count Correction'); setAdjNotes(''); setIsAdjModalOpen(true); };

  const handleSave = () => {
    if (!formData.name || !formData.price || !formData.category) { showToast("Name, Category, and Price are required.", 'ERROR'); return; }
    if (editingProduct) {
      if (formData.price !== editingProduct.price) onLogPriceChange({ id: `ph-${Date.now()}-p`, productId: editingProduct.id, type: 'PRICE', oldValue: editingProduct.price, newValue: formData.price || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      if (formData.cost !== editingProduct.cost) onLogPriceChange({ id: `ph-${Date.now()}-c`, productId: editingProduct.id, type: 'COST', oldValue: editingProduct.cost, newValue: formData.cost || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      setProducts(prev => prev.map(p => p.id === editingProduct.id ? { ...p, ...formData } as Product : p));
      showToast("Product updated.", 'SUCCESS');
    } else {
      setProducts(prev => [...prev, { id: `p-${Date.now()}`, ...formData as Product }]);
      showToast("Product added.", 'SUCCESS');
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => { if (window.confirm('Delete this product?')) { setProducts(prev => prev.filter(p => p.id !== id)); showToast("Product deleted.", 'INFO'); } };

  const handleSubmitAdjustment = () => {
      if (!selectedProductForAdj) return;
      let newStock = selectedProductForAdj.stock;
      if (adjType === 'ADD') newStock = parseFloat((selectedProductForAdj.stock + adjQuantity).toFixed(3));
      if (adjType === 'REMOVE') newStock = parseFloat((selectedProductForAdj.stock - adjQuantity).toFixed(3));
      if (adjType === 'SET') newStock = adjQuantity;
      if (newStock < 0) { showToast("Stock cannot be negative.", 'ERROR'); return; }
      onAdjustStock({ id: `adj-${Date.now()}`, productId: selectedProductForAdj.id, productName: selectedProductForAdj.name, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now(), type: adjType, quantity: adjQuantity, previousStock: selectedProductForAdj.stock, newStock, reason: adjReason, notes: adjNotes });
      setIsAdjModalOpen(false);
  };

  const handleRestockCheck = async () => { setIsLoadingAi(true); const suggestions = await suggestRestock(products); setAiSuggestions(suggestions); setIsLoadingAi(false); showToast("AI analysis complete.", 'SUCCESS'); };

  const handleSort = (field: SortField) => { if (sortField === field) setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc'); else { setSortField(field); setSortDirection('asc'); } };

  const HeaderCell = ({ field, label, align = 'left' }: { field: SortField, label: string, align?: 'left' | 'center' | 'right' }) => (
      <th className={`p-4 text-xs font-semibold text-slate-600 dark:text-slate-300 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700 transition select-none text-${align}`} onClick={() => handleSort(field)}>
          <div className={`flex items-center ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
              {label}{sortField === field ? (sortDirection === 'asc' ? <ArrowUp size={14} className="ml-1 text-blue-500" /> : <ArrowDown size={14} className="ml-1 text-blue-500" />) : <ChevronsUpDown size={14} className="ml-1 text-slate-400" />}
          </div>
      </th>
  );

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-full mr-4"><Package size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Total Items</p><p className="text-lg font-bold text-slate-800 dark:text-white">{formatNumber(products.reduce((acc, p) => acc + p.stock, 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-full mr-4"><DollarSign size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Inventory Value</p><p className="text-lg font-bold text-slate-800 dark:text-white">{symbol}{formatCurrency(products.reduce((acc, p) => acc + (p.price * p.stock), 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 rounded-full mr-4"><AlertTriangle size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Low Stock</p><p className="text-lg font-bold text-slate-800 dark:text-white">{products.filter(p => p.stock <= p.minStockLevel).length}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 rounded-full mr-4"><History size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Expired</p><p className="text-lg font-bold text-slate-800 dark:text-white">{products.filter(p => (getDaysUntilExpiry(p.stockExpiryDate) || 0) < 0).length}</p></div>
          </div>
      </div>

      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
          <div className="flex flex-col md:flex-row gap-4 w-full xl:w-auto">
              <div className="relative w-full md:w-64"><Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"/></div>
              <div className="flex gap-2">
                  <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 outline-none">
                      {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  <select value={filterStockStatus} onChange={(e) => setFilterStockStatus(e.target.value as any)} className="pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 outline-none">
                      <option value="ALL">All Stock</option><option value="LOW">Low</option><option value="OUT">Out</option><option value="IN">In</option>
                  </select>
              </div>
          </div>
          <div className="flex flex-wrap gap-2 w-full xl:w-auto justify-end">
              <button onClick={exportToExcel} className="px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-medium hover:bg-emerald-700 transition flex items-center shadow-sm">
                  <FileSpreadsheet size={16} className="mr-2"/> Export Excel
              </button>
              <button onClick={handleRestockCheck} disabled={isLoadingAi} className="px-4 py-2 bg-purple-600 text-white rounded-lg text-sm font-medium hover:bg-purple-700 transition flex items-center shadow-sm">
                  <Wand2 size={16} className={`mr-2 ${isLoadingAi ? 'animate-spin' : ''}`}/> AI Audit
              </button>
              <button onClick={() => handleOpenModal()} className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition flex items-center shadow-sm">
                  <Plus size={16} className="mr-2"/> Add Product
              </button>
          </div>
      </div>

      {aiSuggestions.length > 0 && (
          <div className="bg-gradient-to-r from-purple-50 to-indigo-50 dark:from-purple-900/20 dark:to-indigo-900/20 border border-purple-100 dark:border-purple-800 rounded-xl p-4 flex items-start gap-4">
              <div className="p-2 bg-purple-100 dark:bg-purple-900/50 rounded-full text-purple-600 dark:text-purple-300 shrink-0"><Wand2 size={20}/></div>
              <div className="flex-1"><h4 className="font-bold text-purple-900 dark:text-purple-300 mb-2 text-sm">AI Analysis</h4><div className="flex flex-wrap gap-2">{aiSuggestions.map((s, i) => (<div key={i} className="bg-white dark:bg-slate-800 px-3 py-1 rounded-lg shadow-sm border border-purple-100 dark:border-slate-700 text-xs flex items-center"><span className="font-bold mr-2">{s.productName}:</span><span>{s.suggestedAction}</span></div>))}</div></div>
              <button onClick={() => setAiSuggestions([])}><X size={18} className="text-slate-400"/></button>
          </div>
      )}

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
          <div className="overflow-x-auto">
              <table className="w-full text-left">
                  <thead className="bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-700">
                      <tr>
                          <HeaderCell field="name" label="Product" />
                          <HeaderCell field="sku" label="SKU" />
                          <HeaderCell field="category" label="Category" />
                          <HeaderCell field="stockExpiryDate" label="Expiry" />
                          <HeaderCell field="price" label="Price" align="right" />
                          <HeaderCell field="margin" label="Margin" align="right" />
                          <HeaderCell field="stock" label="Stock" align="center" />
                          <th className="p-4 text-xs font-semibold text-right">Actions</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                      {processedProducts.map(product => {
                          const days = getDaysUntilExpiry(product.stockExpiryDate);
                          const status = getExpiryStatus(days);
                          const margin = product.price > 0 ? ((product.price - product.cost) / product.price * 100) : 0;
                          return (
                              <tr key={product.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition group">
                                  <td className="p-4"><div className="flex items-center"><div className="w-10 h-10 rounded bg-slate-100 dark:bg-slate-700 mr-3 overflow-hidden flex items-center justify-center shrink-0"><img src={product.imageUrl || "https://placehold.co/40"} alt="" className="w-full h-full object-cover"/></div><div className="text-sm font-medium">{product.name}</div></div></td>
                                  <td className="p-4 text-xs font-mono text-slate-500">{product.sku}</td>
                                  <td className="p-4"><span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300">{product.category}</span></td>
                                  <td className="p-4 text-xs">{product.stockExpiryDate ? <div className={`${status === 'EXPIRED' ? 'text-red-500 font-bold' : status === 'WARNING' ? 'text-orange-500' : 'text-slate-500'}`}>{product.stockExpiryDate}</div> : '-'}</td>
                                  <td className="p-4 text-right font-medium">{symbol}{product.price.toFixed(2)}</td>
                                  <td className="p-4 text-right"><span className={`text-xs font-bold ${margin < 15 ? 'text-red-500' : 'text-green-600'}`}>{margin.toFixed(1)}%</span></td>
                                  <td className="p-4 text-center font-bold">{product.stock} <span className="text-[10px] text-slate-400 font-normal">{product.unit}</span></td>
                                  <td className="p-4 text-right"><div className="flex items-center justify-end space-x-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => handleOpenAdjModal(product)} className="p-1.5 text-blue-600 rounded" title="Adjust Stock"><Scale size={16}/></button><button onClick={() => handleOpenModal(product)} className="p-1.5 text-slate-600 rounded" title="Edit"><Edit2 size={16}/></button><button onClick={() => handleDelete(product.id)} className="p-1.5 text-red-500 rounded" title="Delete"><Trash2 size={16}/></button></div></td>
                              </tr>
                          );
                      })}
                  </tbody>
              </table>
          </div>
      </div>

      {isModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col">
                  <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-xl"><h3 className="font-bold">{editingProduct ? 'Edit Product' : 'Add Product'}</h3><button onClick={() => setIsModalOpen(false)}><X size={20}/></button></div>
                  <div className="flex-1 overflow-y-auto p-6 space-y-4">
                      <div className="grid grid-cols-2 gap-4">
                          <div className="col-span-2"><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Name</label><input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">SKU</label><input type="text" value={formData.sku} onChange={e => setFormData({...formData, sku: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Category</label><input type="text" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Cost Price</label><input type="number" value={formData.cost} onChange={e => setFormData({...formData, cost: parseFloat(e.target.value)})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Selling Price</label><input type="number" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                      </div>
                      <div className="flex items-center gap-2"><input type="checkbox" id="decimal" checked={formData.allowDecimal} onChange={e => setFormData({...formData, allowDecimal: e.target.checked})} className="rounded text-blue-600"/><label htmlFor="decimal" className="text-sm font-medium">Allow Decimal Quantities</label></div>
                  </div>
                  <div className="p-4 border-t flex justify-end gap-2 bg-slate-50 dark:bg-slate-800/50 rounded-b-xl"><button onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm text-slate-500">Cancel</button><button onClick={handleSave} className="px-6 py-2 bg-blue-600 text-white rounded-lg font-bold">Save</button></div>
              </div>
          </div>
      )}

      {isAdjModalOpen && selectedProductForAdj && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-sm p-6">
                  <h3 className="text-lg font-bold mb-4">Adjust Stock: {selectedProductForAdj.name}</h3>
                  <div className="space-y-4">
                      <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-lg">
                          {['ADD', 'REMOVE', 'SET'].map(type => (
                              <button key={type} onClick={() => setAdjType(type as AdjustmentType)} className={`flex-1 py-1.5 text-xs font-bold rounded ${adjType === type ? 'bg-white dark:bg-slate-600 shadow text-blue-600' : 'text-slate-500'}`}>{type}</button>
                          ))}
                      </div>
                      <input type="number" step={selectedProductForAdj.allowDecimal ? "0.001" : "1"} value={adjQuantity} onChange={e => setAdjQuantity(parseFloat(e.target.value) || 0)} className="w-full p-3 text-center text-2xl font-bold border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" autoFocus/>
                      <select value={adjReason} onChange={e => setAdjReason(e.target.value)} className="w-full p-2 border rounded text-sm bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white"><option>Stock Count Correction</option><option>Damage</option><option>Received Shipment</option></select>
                  </div>
                  <div className="mt-6 flex justify-end gap-2"><button onClick={() => setIsAdjModalOpen(false)} className="px-4 py-2 text-slate-500 text-sm">Cancel</button><button onClick={handleSubmitAdjustment} className="px-6 py-2 bg-blue-600 text-white font-bold rounded-lg text-sm">Confirm</button></div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, StockAdjustment, AdjustmentType, User, ReturnTransaction, Customer, Sale, PriceHistory } from '../types';
import { suggestRestock } from '../services/geminiService';
import { Plus, Edit2, Trash2, Search, Wand2, History, X, FileSpreadsheet, Package, DollarSign, AlertTriangle, Scale, ArrowUp, ArrowDown, ChevronsUpDown } from 'lucide-react';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  stockAdjustments: StockAdjustment[];
  onAdjustStock: (adjustment: StockAdjustment) => void;
  onBulkAdjustStock: (adjustments: StockAdjustment[]) => void;
  currentUser: User;
  currency: string;
  showToast: (message: string, type: 'SUCCESS' | 'ERROR' | 'INFO') => void;
  returns: ReturnTransaction[];
  customers: Customer[];
  sales: Sale[];
  priceHistory: PriceHistory[];
  onLogPriceChange: (log: PriceHistory) => void;
}

type SortField = 'name' | 'sku' | 'category' | 'price' | 'stock' | 'stockExpiryDate' | 'cost' | 'margin';
type SortDirection = 'asc' | 'desc';

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, stockAdjustments, onAdjustStock, onBulkAdjustStock, currentUser, currency, showToast, returns, customers, sales, priceHistory, onLogPriceChange }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);

  // Search & Filter State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('ALL');
  const [filterStockStatus, setFilterStockStatus] = useState<'ALL' | 'LOW' | 'OUT' | 'IN'>('ALL');
  const [filterExpiry, setFilterExpiry] = useState<'ALL' | 'EXPIRED' | 'SOON' | 'VALID'>('ALL');

  // Sorting State
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');

  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [isLoadingAi, setIsLoadingAi] = useState(false);

  // Adjustment State
  const [isAdjModalOpen, setIsAdjModalOpen] = useState(false);
  const [selectedProductForAdj, setSelectedProductForAdj] = useState<Product | null>(null);
  const [adjType, setAdjType] = useState<AdjustmentType>('ADD');
  const [adjQuantity, setAdjQuantity] = useState(0);
  const [adjReason, setAdjReason] = useState('Stock Count Correction');
  const [adjNotes, setAdjNotes] = useState('');

  // Form State
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false
  });

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  };

  const symbol = getCurrencySymbol(currency);
  const formatCurrency = (val: number) => val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const formatNumber = (val: number) => val.toLocaleString('en-US', { maximumFractionDigits: 3 });

  const categories = useMemo(() => {
      const cats = new Set(products.map(p => p.category).filter(Boolean));
      return ['ALL', ...Array.from(cats).sort()];
  }, [products]);

  const processedProducts = useMemo(() => {
      let filtered = products.filter(p => 
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        p.sku.toLowerCase().includes(searchTerm.toLowerCase())
      );
      if (filterCategory !== 'ALL') filtered = filtered.filter(p => p.category === filterCategory);
      if (filterStockStatus !== 'ALL') {
          if (filterStockStatus === 'OUT') filtered = filtered.filter(p => p.stock === 0);
          if (filterStockStatus === 'LOW') filtered = filtered.filter(p => p.stock > 0 && p.stock <= p.minStockLevel);
          if (filterStockStatus === 'IN') filtered = filtered.filter(p => p.stock > p.minStockLevel);
      }
      if (filterExpiry !== 'ALL') {
          filtered = filtered.filter(p => {
              const days = getDaysUntilExpiry(p.stockExpiryDate);
              if (filterExpiry === 'EXPIRED') return days !== null && days < 0;
              if (filterExpiry === 'SOON') return days !== null && days >= 0 && days <= 30;
              if (filterExpiry === 'VALID') return days === null || days > 30;
              return true;
          });
      }
      return filtered.sort((a, b) => {
          let valA: any = a[sortField];
          let valB: any = b[sortField];
          if (sortField === 'margin') {
              valA = a.price > 0 ? ((a.price - a.cost) / a.price) : -999;
              valB = b.price > 0 ? ((b.price - b.cost) / b.price) : -999;
          }
          if (typeof valA === 'string') return sortDirection === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
          return sortDirection === 'asc' ? (valA < valB ? -1 : 1) : (valB < valA ? -1 : 1);
      });
  }, [products, searchTerm, filterCategory, filterStockStatus, filterExpiry, sortField, sortDirection]);

  // Detailed Inventory Export Feature with Hierarchy and Performance Metrics
  const exportToExcel = () => {
    const headers = [
      "Category", "Product Name", "SKU", "Stock", "Unit", 
      "Cost Price", "Selling Price", "Total Sold", "Total Returned", 
      "Net Sold", "Revenue (Net)", "Cost Total (Net)", "Profit/Loss", "Margin (%)"
    ];

    // Group items by category for hierarchy
    const groupedProducts: Record<string, Product[]> = {};
    processedProducts.forEach(p => {
        const cat = p.category || 'Uncategorized';
        if (!groupedProducts[cat]) groupedProducts[cat] = [];
        groupedProducts[cat].push(p);
    });

    const rows: string[] = [];

    Object.keys(groupedProducts).sort().forEach(cat => {
        // Add Category Header Row
        rows.push([`"--- CATEGORY: ${cat.toUpperCase()} ---"`, "", "", "", "", "", "", "", "", "", "", "", "", ""].join(","));

        let catTotalRevenue = 0;
        let catTotalCost = 0;
        let catTotalProfit = 0;
        let catTotalSold = 0;
        let catTotalReturned = 0;

        groupedProducts[cat].forEach(p => {
            // Performance Calculations
            const soldItems = sales.flatMap(s => s.items.filter(i => i.productId === p.id));
            const totalSold = soldItems.reduce((sum, i) => sum + i.quantity, 0);

            const returnedItems = returns.flatMap(r => r.items.filter(ri => ri.productId === p.id));
            const totalReturned = returnedItems.reduce((sum, i) => sum + i.quantity, 0);

            const netSold = totalSold - totalReturned;

            const revenue = soldItems.reduce((sum, i) => sum + (i.priceAtSale * i.quantity), 0);
            const costOfSales = soldItems.reduce((sum, i) => sum + (i.costAtSale * i.quantity), 0);

            const refunds = returns.reduce((sum, r) => {
                const pReturn = r.items.find(ri => ri.productId === p.id);
                return sum + (pReturn ? pReturn.refundAmount : 0);
            }, 0);

            const returnCostImpact = returns.reduce((sum, r) => {
                const origSale = sales.find(s => s.id === r.originalSaleId);
                if (!origSale) return sum;
                const pReturn = r.items.find(ri => ri.productId === p.id);
                const origItem = origSale.items.find(si => si.productId === p.id);
                if (!pReturn || !origItem) return sum;
                return sum + (origItem.costAtSale * pReturn.quantity);
            }, 0);

            const netRevenue = revenue - refunds;
            const netCostTotal = costOfSales - returnCostImpact;
            const profitLoss = netRevenue - netCostTotal;
            const margin = netRevenue > 0 ? (profitLoss / netRevenue * 100).toFixed(2) : (p.price > 0 ? ((p.price - p.cost) / p.price * 100).toFixed(2) : '0');

            // Accumulate category totals
            catTotalRevenue += netRevenue;
            catTotalCost += netCostTotal;
            catTotalProfit += profitLoss;
            catTotalSold += totalSold;
            catTotalReturned += totalReturned;

            rows.push([
                `"${cat}"`,
                `"${p.name.replace(/"/g, '""')}"`,
                `"${p.sku}"`,
                p.stock,
                `"${p.unit || 'pcs'}"`,
                p.cost.toFixed(2),
                p.price.toFixed(2),
                totalSold,
                totalReturned,
                netSold,
                netRevenue.toFixed(2),
                netCostTotal.toFixed(2),
                profitLoss.toFixed(2),
                `"${margin}%"`
            ].join(","));
        });

        // Add Category Summary Row (Hierarchy Sub-total)
        rows.push([
            `"TOTAL FOR ${cat.toUpperCase()}"`, 
            "", "", "", "", "", "", 
            catTotalSold, 
            catTotalReturned, 
            catTotalSold - catTotalReturned, 
            catTotalRevenue.toFixed(2), 
            catTotalCost.toFixed(2), 
            catTotalProfit.toFixed(2), 
            `"${catTotalRevenue > 0 ? (catTotalProfit / catTotalRevenue * 100).toFixed(2) : '0'}%"`
        ].join(","));

        // Blank line for spacing in Excel
        rows.push("");
    });

    const csvContent = "\uFEFF" + [headers.join(","), ...rows].join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `Detailed_Inventory_Report_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast("Detailed inventory report exported.", "SUCCESS");
  };

  const getDaysUntilExpiry = (dateString?: string) => {
      if (!dateString) return null;
      const [year, month, day] = dateString.split('-').map(Number);
      const expiry = new Date(year, month - 1, day);
      const diffTime = expiry.getTime() - new Date().setHours(0,0,0,0);
      return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const getExpiryStatus = (days: number | null) => {
      if (days === null) return 'NONE';
      if (days < 0) return 'EXPIRED';
      if (days <= 30) return 'WARNING';
      return 'OK';
  };

  const handleOpenModal = (product?: Product) => {
    if (product) { setEditingProduct(product); setFormData(product); }
    else { setEditingProduct(null); setFormData({ name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false }); }
    setIsModalOpen(true);
  };

  const handleOpenAdjModal = (product: Product) => { setSelectedProductForAdj(product); setAdjType('ADD'); setAdjQuantity(0); setAdjReason('Stock Count Correction'); setAdjNotes(''); setIsAdjModalOpen(true); };

  const handleSave = () => {
    if (!formData.name || !formData.price || !formData.category) { showToast("Name, Category, and Price are required.", 'ERROR'); return; }
    if (editingProduct) {
      if (formData.price !== editingProduct.price) onLogPriceChange({ id: `ph-${Date.now()}-p`, productId: editingProduct.id, type: 'PRICE', oldValue: editingProduct.price, newValue: formData.price || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      if (formData.cost !== editingProduct.cost) onLogPriceChange({ id: `ph-${Date.now()}-c`, productId: editingProduct.id, type: 'COST', oldValue: editingProduct.cost, newValue: formData.cost || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      setProducts(prev => prev.map(p => p.id === editingProduct.id ? { ...p, ...formData } as Product : p));
      showToast("Product updated.", 'SUCCESS');
    } else {
      setProducts(prev => [...prev, { id: `p-${Date.now()}`, ...formData as Product }]);
      showToast("Product added.", 'SUCCESS');
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => { if (window.confirm('Delete this product?')) { setProducts(prev => prev.filter(p => p.id !== id)); showToast("Product deleted.", 'INFO'); } };

  const handleSubmitAdjustment = () => {
      if (!selectedProductForAdj) return;
      let newStock = selectedProductForAdj.stock;
      if (adjType === 'ADD') newStock = parseFloat((selectedProductForAdj.stock + adjQuantity).toFixed(3));
      if (adjType === 'REMOVE') newStock = parseFloat((selectedProductForAdj.stock - adjQuantity).toFixed(3));
      if (adjType === 'SET') newStock = adjQuantity;
      if (newStock < 0) { showToast("Stock cannot be negative.", 'ERROR'); return; }
      onAdjustStock({ id: `adj-${Date.now()}`, productId: selectedProductForAdj.id, productName: selectedProductForAdj.name, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now(), type: adjType, quantity: adjQuantity, previousStock: selectedProductForAdj.stock, newStock, reason: adjReason, notes: adjNotes });
      setIsAdjModalOpen(false);
  };

  const handleRestockCheck = async () => { setIsLoadingAi(true); const suggestions = await suggestRestock(products); setAiSuggestions(suggestions); setIsLoadingAi(false); showToast("AI analysis complete.", 'SUCCESS'); };

  const handleSort = (field: SortField) => { if (sortField === field) setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc'); else { setSortField(field); setSortDirection('asc'); } };

  const HeaderCell = ({ field, label, align = 'left' }: { field: SortField, label: string, align?: 'left' | 'center' | 'right' }) => (
      <th className={`p-4 text-xs font-semibold text-slate-600 dark:text-slate-300 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700 transition select-none text-${align}`} onClick={() => handleSort(field)}>
          <div className={`flex items-center ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
              {label}{sortField === field ? (sortDirection === 'asc' ? <ArrowUp size={14} className="ml-1 text-blue-500" /> : <ArrowDown size={14} className="ml-1 text-blue-500" />) : <ChevronsUpDown size={14} className="ml-1 text-slate-400" />}
          </div>
      </th>
  );

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-full mr-4"><Package size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Total Items</p><p className="text-lg font-bold text-slate-800 dark:text-white">{formatNumber(products.reduce((acc, p) => acc + p.stock, 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-full mr-4"><DollarSign size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Inventory Value</p><p className="text-lg font-bold text-slate-800 dark:text-white">{symbol}{formatCurrency(products.reduce((acc, p) => acc + (p.price * p.stock), 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 rounded-full mr-4"><AlertTriangle size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Low Stock</p><p className="text-lg font-bold text-slate-800 dark:text-white">{products.filter(p => p.stock <= p.minStockLevel).length}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 rounded-full mr-4"><History size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Expired</p><p className="text-lg font-bold text-slate-800 dark:text-white">{products.filter(p => (getDaysUntilExpiry(p.stockExpiryDate) || 0) < 0).length}</p></div>
          </div>
      </div>

      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
          <div className="flex flex-col md:flex-row gap-4 w-full xl:w-auto">
              <div className="relative w-full md:w-64"><Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"/></div>
              <div className="flex gap-2">
                  <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 outline-none">
                      {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  <select value={filterStockStatus} onChange={(e) => setFilterStockStatus(e.target.value as any)} className="pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 outline-none">
                      <option value="ALL">All Stock</option><option value="LOW">Low</option><option value="OUT">Out</option><option value="IN">In</option>
                  </select>
              </div>
          </div>
          <div className="flex flex-wrap gap-2 w-full xl:w-auto justify-end">
              <button onClick={exportToExcel} className="px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-medium hover:bg-emerald-700 transition flex items-center shadow-sm">
                  <FileSpreadsheet size={16} className="mr-2"/> Export Detailed CSV
              </button>
              <button onClick={handleRestockCheck} disabled={isLoadingAi} className="px-4 py-2 bg-purple-600 text-white rounded-lg text-sm font-medium hover:bg-purple-700 transition flex items-center shadow-sm">
                  <Wand2 size={16} className={`mr-2 ${isLoadingAi ? 'animate-spin' : ''}`}/> AI Audit
              </button>
              <button onClick={() => handleOpenModal()} className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition flex items-center shadow-sm">
                  <Plus size={16} className="mr-2"/> Add Product
              </button>
          </div>
      </div>

      {aiSuggestions.length > 0 && (
          <div className="bg-gradient-to-r from-purple-50 to-indigo-50 dark:from-purple-900/20 dark:to-indigo-900/20 border border-purple-100 dark:border-purple-800 rounded-xl p-4 flex items-start gap-4">
              <div className="p-2 bg-purple-100 dark:bg-purple-900/50 rounded-full text-purple-600 dark:text-purple-300 shrink-0"><Wand2 size={20}/></div>
              <div className="flex-1"><h4 className="font-bold text-purple-900 dark:text-purple-300 mb-2 text-sm">AI Analysis</h4><div className="flex flex-wrap gap-2">{aiSuggestions.map((s, i) => (<div key={i} className="bg-white dark:bg-slate-800 px-3 py-1 rounded-lg shadow-sm border border-purple-100 dark:border-slate-700 text-xs flex items-center"><span className="font-bold mr-2">{s.productName}:</span><span>{s.suggestedAction}</span></div>))}</div></div>
              <button onClick={() => setAiSuggestions([])}><X size={18} className="text-slate-400"/></button>
          </div>
      )}

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
          <div className="overflow-x-auto">
              <table className="w-full text-left">
                  <thead className="bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-700">
                      <tr>
                          <HeaderCell field="name" label="Product" />
                          <HeaderCell field="sku" label="SKU" />
                          <HeaderCell field="category" label="Category" />
                          <HeaderCell field="stockExpiryDate" label="Expiry" />
                          <HeaderCell field="price" label="Price" align="right" />
                          <HeaderCell field="margin" label="Margin" align="right" />
                          <HeaderCell field="stock" label="Stock" align="center" />
                          <th className="p-4 text-xs font-semibold text-right">Actions</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                      {processedProducts.map(product => {
                          const days = getDaysUntilExpiry(product.stockExpiryDate);
                          const status = getExpiryStatus(days);
                          const margin = product.price > 0 ? ((product.price - product.cost) / product.price * 100) : 0;
                          return (
                              <tr key={product.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition group">
                                  <td className="p-4"><div className="flex items-center"><div className="w-10 h-10 rounded bg-slate-100 dark:bg-slate-700 mr-3 overflow-hidden flex items-center justify-center shrink-0"><img src={product.imageUrl || "https://placehold.co/40"} alt="" className="w-full h-full object-cover"/></div><div className="text-sm font-medium">{product.name}</div></div></td>
                                  <td className="p-4 text-xs font-mono text-slate-500">{product.sku}</td>
                                  <td className="p-4"><span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300">{product.category}</span></td>
                                  <td className="p-4 text-xs">{product.stockExpiryDate ? <div className={`${status === 'EXPIRED' ? 'text-red-500 font-bold' : status === 'WARNING' ? 'text-orange-500' : 'text-slate-500'}`}>{product.stockExpiryDate}</div> : '-'}</td>
                                  <td className="p-4 text-right font-medium">{symbol}{product.price.toFixed(2)}</td>
                                  <td className="p-4 text-right"><span className={`text-xs font-bold ${margin < 15 ? 'text-red-500' : 'text-green-600'}`}>{margin.toFixed(1)}%</span></td>
                                  <td className="p-4 text-center font-bold">{product.stock} <span className="text-[10px] text-slate-400 font-normal">{product.unit}</span></td>
                                  <td className="p-4 text-right"><div className="flex items-center justify-end space-x-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => handleOpenAdjModal(product)} className="p-1.5 text-blue-600 rounded" title="Adjust Stock"><Scale size={16}/></button><button onClick={() => handleOpenModal(product)} className="p-1.5 text-slate-600 rounded" title="Edit"><Edit2 size={16}/></button><button onClick={() => handleDelete(product.id)} className="p-1.5 text-red-500 rounded" title="Delete"><Trash2 size={16}/></button></div></td>
                              </tr>
                          );
                      })}
                  </tbody>
              </table>
          </div>
      </div>

      {isModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col">
                  <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-xl"><h3 className="font-bold">{editingProduct ? 'Edit Product' : 'Add Product'}</h3><button onClick={() => setIsModalOpen(false)}><X size={20}/></button></div>
                  <div className="flex-1 overflow-y-auto p-6 space-y-4">
                      <div className="grid grid-cols-2 gap-4">
                          <div className="col-span-2"><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Name</label><input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">SKU</label><input type="text" value={formData.sku} onChange={e => setFormData({...formData, sku: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Category</label><input type="text" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Cost Price</label><input type="number" value={formData.cost} onChange={e => setFormData({...formData, cost: parseFloat(e.target.value)})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Selling Price</label><input type="number" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                      </div>
                      <div className="flex items-center gap-2"><input type="checkbox" id="decimal" checked={formData.allowDecimal} onChange={e => setFormData({...formData, allowDecimal: e.target.checked})} className="rounded text-blue-600"/><label htmlFor="decimal" className="text-sm font-medium">Allow Decimal Quantities</label></div>
                  </div>
                  <div className="p-4 border-t flex justify-end gap-2 bg-slate-50 dark:bg-slate-800/50 rounded-b-xl"><button onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm text-slate-500">Cancel</button><button onClick={handleSave} className="px-6 py-2 bg-blue-600 text-white rounded-lg font-bold">Save</button></div>
              </div>
          </div>
      )}

      {isAdjModalOpen && selectedProductForAdj && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-sm p-6">
                  <h3 className="text-lg font-bold mb-4">Adjust Stock: {selectedProductForAdj.name}</h3>
                  <div className="space-y-4">
                      <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-lg">
                          {['ADD', 'REMOVE', 'SET'].map(type => (
                              <button key={type} onClick={() => setAdjType(type as AdjustmentType)} className={`flex-1 py-1.5 text-xs font-bold rounded ${adjType === type ? 'bg-white dark:bg-slate-600 shadow text-blue-600' : 'text-slate-500'}`}>{type}</button>
                          ))}
                      </div>
                      <input type="number" step={selectedProductForAdj.allowDecimal ? "0.001" : "1"} value={adjQuantity} onChange={e => setAdjQuantity(parseFloat(e.target.value) || 0)} className="w-full p-3 text-center text-2xl font-bold border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" autoFocus/>
                      <select value={adjReason} onChange={e => setAdjReason(e.target.value)} className="w-full p-2 border rounded text-sm bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white"><option>Stock Count Correction</option><option>Damage</option><option>Received Shipment</option></select>
                  </div>
                  <div className="mt-6 flex justify-end gap-2"><button onClick={() => setIsAdjModalOpen(false)} className="px-4 py-2 text-slate-500 text-sm">Cancel</button><button onClick={handleSubmitAdjustment} className="px-6 py-2 bg-blue-600 text-white font-bold rounded-lg text-sm">Confirm</button></div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, StockAdjustment, AdjustmentType, User, ReturnTransaction, Customer, Sale, PriceHistory } from '../types';
import { suggestRestock } from '../services/geminiService';
import { Plus, Edit2, Trash2, Search, Wand2, History, X, FileSpreadsheet, Package, DollarSign, AlertTriangle, Scale, ArrowUp, ArrowDown, ChevronsUpDown } from 'lucide-react';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  stockAdjustments: StockAdjustment[];
  onAdjustStock: (adjustment: StockAdjustment) => void;
  onBulkAdjustStock: (adjustments: StockAdjustment[]) => void;
  currentUser: User;
  currency: string;
  showToast: (message: string, type: 'SUCCESS' | 'ERROR' | 'INFO') => void;
  returns: ReturnTransaction[];
  customers: Customer[];
  sales: Sale[];
  priceHistory: PriceHistory[];
  onLogPriceChange: (log: PriceHistory) => void;
}

type SortField = 'name' | 'sku' | 'category' | 'price' | 'stock' | 'stockExpiryDate' | 'cost' | 'margin';
type SortDirection = 'asc' | 'desc';

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, stockAdjustments, onAdjustStock, onBulkAdjustStock, currentUser, currency, showToast, returns, customers, sales, priceHistory, onLogPriceChange }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);

  // Search & Filter State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('ALL');
  const [filterStockStatus, setFilterStockStatus] = useState<'ALL' | 'LOW' | 'OUT' | 'IN'>('ALL');
  const [filterExpiry, setFilterExpiry] = useState<'ALL' | 'EXPIRED' | 'SOON' | 'VALID'>('ALL');

  // Sorting State
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');

  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [isLoadingAi, setIsLoadingAi] = useState(false);

  // Adjustment State
  const [isAdjModalOpen, setIsAdjModalOpen] = useState(false);
  const [selectedProductForAdj, setSelectedProductForAdj] = useState<Product | null>(null);
  const [adjType, setAdjType] = useState<AdjustmentType>('ADD');
  const [adjQuantity, setAdjQuantity] = useState(0);
  const [adjReason, setAdjReason] = useState('Stock Count Correction');
  const [adjNotes, setAdjNotes] = useState('');

  // Form State
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false
  });

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  };

  const symbol = getCurrencySymbol(currency);
  const formatCurrency = (val: number) => val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const formatNumber = (val: number) => val.toLocaleString('en-US', { maximumFractionDigits: 3 });

  const categories = useMemo(() => {
      const cats = new Set(products.map(p => p.category).filter(Boolean));
      return ['ALL', ...Array.from(cats).sort()];
  }, [products]);

  const processedProducts = useMemo(() => {
      let filtered = products.filter(p => 
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        p.sku.toLowerCase().includes(searchTerm.toLowerCase())
      );
      if (filterCategory !== 'ALL') filtered = filtered.filter(p => p.category === filterCategory);
      if (filterStockStatus !== 'ALL') {
          if (filterStockStatus === 'OUT') filtered = filtered.filter(p => p.stock === 0);
          if (filterStockStatus === 'LOW') filtered = filtered.filter(p => p.stock > 0 && p.stock <= p.minStockLevel);
          if (filterStockStatus === 'IN') filtered = filtered.filter(p => p.stock > p.minStockLevel);
      }
      if (filterExpiry !== 'ALL') {
          filtered = filtered.filter(p => {
              const days = getDaysUntilExpiry(p.stockExpiryDate);
              if (filterExpiry === 'EXPIRED') return days !== null && days < 0;
              if (filterExpiry === 'SOON') return days !== null && days >= 0 && days <= 30;
              if (filterExpiry === 'VALID') return days === null || days > 30;
              return true;
          });
      }
      return filtered.sort((a, b) => {
          let valA: any = a[sortField];
          let valB: any = b[sortField];
          if (sortField === 'margin') {
              valA = a.price > 0 ? ((a.price - a.cost) / a.price) : -999;
              valB = b.price > 0 ? ((b.price - b.cost) / b.price) : -999;
          }
          if (typeof valA === 'string') return sortDirection === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
          return sortDirection === 'asc' ? (valA < valB ? -1 : 1) : (valB < valA ? -1 : 1);
      });
  }, [products, searchTerm, filterCategory, filterStockStatus, filterExpiry, sortField, sortDirection]);

  // High-Design Hierarchy Export
  const exportToExcel = () => {
    const headers = [
      "CATEGORY / HIERARCHY", 
      "PRODUCT NAME", 
      "SKU", 
      "CURRENT STOCK", 
      "UNIT", 
      "COST PRICE", 
      "SELLING PRICE", 
      "STOCK SOLD (QTY)", 
      "STOCK RETURNED (QTY)", 
      "NET SOLD (QTY)", 
      "REVENUE (NET)", 
      "COST OF GOODS SOLD (COGS)", 
      "PROFIT / LOSS", 
      "MARGIN (%)"
    ];

    // Group items by category
    const groupedProducts: Record<string, Product[]> = {};
    processedProducts.forEach(p => {
        const cat = p.category || 'Uncategorized';
        if (!groupedProducts[cat]) groupedProducts[cat] = [];
        groupedProducts[cat].push(p);
    });

    const rows: string[] = [];

    // Grand Totals trackers
    let grandRevenue = 0;
    let grandCost = 0;
    let grandProfit = 0;
    let grandSold = 0;
    let grandReturned = 0;

    // Report Branding
    rows.push([`"NEXUS INVENTORY & PERFORMANCE REPORT"`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`].join(","));
    rows.push([`"Generated on: ${new Date().toLocaleString()}"`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`].join(","));
    rows.push([""]); // Spacer

    Object.keys(groupedProducts).sort().forEach(cat => {
        // Category Header Section
        rows.push([`"--- SECTION: ${cat.toUpperCase()} ---"`, "", "", "", "", "", "", "", "", "", "", "", "", ""].join(","));

        let catRevenue = 0;
        let catCost = 0;
        let catProfit = 0;
        let catSold = 0;
        let catReturned = 0;

        groupedProducts[cat].forEach(p => {
            // Calculate specific metrics for this product
            const productSales = sales.flatMap(s => s.items.filter(i => i.productId === p.id));
            const totalSold = productSales.reduce((sum, i) => sum + i.quantity, 0);

            const productReturns = returns.flatMap(r => r.items.filter(ri => ri.productId === p.id));
            const totalReturned = productReturns.reduce((sum, i) => sum + i.quantity, 0);

            const netSold = totalSold - totalReturned;

            // Financial Calculations
            const grossRevenue = productSales.reduce((sum, i) => sum + (i.priceAtSale * i.quantity), 0);
            const grossCOGS = productSales.reduce((sum, i) => sum + (i.costAtSale * i.quantity), 0);

            // Refund Impact
            const totalRefundedAmt = returns.reduce((sum, r) => {
                const ri = r.items.find(item => item.productId === p.id);
                return sum + (ri ? ri.refundAmount : 0);
            }, 0);

            const refundedCOGS = returns.reduce((sum, r) => {
                const origSale = sales.find(s => s.id === r.originalSaleId);
                if (!origSale) return sum;
                const ri = r.items.find(item => item.productId === p.id);
                const si = origSale.items.find(item => item.productId === p.id);
                return sum + (ri && si ? (si.costAtSale * ri.quantity) : 0);
            }, 0);

            const netRevenue = grossRevenue - totalRefundedAmt;
            const netCOGS = grossCOGS - refundedCOGS;
            const netProfit = netRevenue - netCOGS;
            const margin = netRevenue > 0 ? (netProfit / netRevenue * 100).toFixed(2) : (p.price > 0 ? ((p.price - p.cost) / p.price * 100).toFixed(2) : '0');

            // Category aggregation
            catRevenue += netRevenue;
            catCost += netCOGS;
            catProfit += netProfit;
            catSold += totalSold;
            catReturned += totalReturned;

            rows.push([
                `"    ${cat}"`, // Indented category name
                `"${p.name.replace(/"/g, '""')}"`,
                `"${p.sku}"`,
                p.stock,
                `"${p.unit || 'pcs'}"`,
                p.cost.toFixed(2),
                p.price.toFixed(2),
                totalSold,
                totalReturned,
                netSold,
                netRevenue.toFixed(2),
                netCOGS.toFixed(2),
                netProfit.toFixed(2),
                `"${margin}%"`
            ].join(","));
        });

        // Add Category Sub-total Hierarchy Row
        rows.push([
            `"SUB-TOTAL: ${cat.toUpperCase()}"`, 
            `""`, `""`, `""`, `""`, `""`, `""`, 
            catSold, 
            catReturned, 
            catSold - catReturned, 
            catRevenue.toFixed(2), 
            catCost.toFixed(2), 
            catProfit.toFixed(2), 
            `"${catRevenue > 0 ? (catProfit / catRevenue * 100).toFixed(2) : '0'}%"`
        ].join(","));

        rows.push([""]); // Vertical spacer between categories

        // Add to Grand Totals
        grandRevenue += catRevenue;
        grandCost += catCost;
        grandProfit += catProfit;
        grandSold += catSold;
        grandReturned += catReturned;
    });

    // Final Report Footer Summary
    rows.push([""]);
    rows.push([`"=========================================================================================================="`]);
    rows.push([`"GRAND REPORT TOTALS"`, `""`, `""`, `""`, `""`, `""`, `""`, grandSold, grandReturned, grandSold - grandReturned, grandRevenue.toFixed(2), grandCost.toFixed(2), grandProfit.toFixed(2), `"${grandRevenue > 0 ? (grandProfit / grandRevenue * 100).toFixed(2) : '0'}%"`].join(","));
    rows.push([`"=========================================================================================================="`]);

    const csvContent = "\uFEFF" + [headers.join(","), ...rows].join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `Detailed_Nexus_Inventory_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast("Designed hierarchical report exported successfully.", "SUCCESS");
  };

  const getDaysUntilExpiry = (dateString?: string) => {
      if (!dateString) return null;
      const [year, month, day] = dateString.split('-').map(Number);
      const expiry = new Date(year, month - 1, day);
      const diffTime = expiry.getTime() - new Date().setHours(0,0,0,0);
      return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const getExpiryStatus = (days: number | null) => {
      if (days === null) return 'NONE';
      if (days < 0) return 'EXPIRED';
      if (days <= 30) return 'WARNING';
      return 'OK';
  };

  const handleOpenModal = (product?: Product) => {
    if (product) { setEditingProduct(product); setFormData(product); }
    else { setEditingProduct(null); setFormData({ name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false }); }
    setIsModalOpen(true);
  };

  const handleOpenAdjModal = (product: Product) => { setSelectedProductForAdj(product); setAdjType('ADD'); setAdjQuantity(0); setAdjReason('Stock Count Correction'); setAdjNotes(''); setIsAdjModalOpen(true); };

  const handleSave = () => {
    if (!formData.name || !formData.price || !formData.category) { showToast("Name, Category, and Price are required.", 'ERROR'); return; }
    if (editingProduct) {
      if (formData.price !== editingProduct.price) onLogPriceChange({ id: `ph-${Date.now()}-p`, productId: editingProduct.id, type: 'PRICE', oldValue: editingProduct.price, newValue: formData.price || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      if (formData.cost !== editingProduct.cost) onLogPriceChange({ id: `ph-${Date.now()}-c`, productId: editingProduct.id, type: 'COST', oldValue: editingProduct.cost, newValue: formData.cost || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      setProducts(prev => prev.map(p => p.id === editingProduct.id ? { ...p, ...formData } as Product : p));
      showToast("Product updated.", 'SUCCESS');
    } else {
      setProducts(prev => [...prev, { id: `p-${Date.now()}`, ...formData as Product }]);
      showToast("Product added.", 'SUCCESS');
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => { if (window.confirm('Delete this product?')) { setProducts(prev => prev.filter(p => p.id !== id)); showToast("Product deleted.", 'INFO'); } };

  const handleSubmitAdjustment = () => {
      if (!selectedProductForAdj) return;
      let newStock = selectedProductForAdj.stock;
      if (adjType === 'ADD') newStock = parseFloat((selectedProductForAdj.stock + adjQuantity).toFixed(3));
      if (adjType === 'REMOVE') newStock = parseFloat((selectedProductForAdj.stock - adjQuantity).toFixed(3));
      if (adjType === 'SET') newStock = adjQuantity;
      if (newStock < 0) { showToast("Stock cannot be negative.", 'ERROR'); return; }
      onAdjustStock({ id: `adj-${Date.now()}`, productId: selectedProductForAdj.id, productName: selectedProductForAdj.name, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now(), type: adjType, quantity: adjQuantity, previousStock: selectedProductForAdj.stock, newStock, reason: adjReason, notes: adjNotes });
      setIsAdjModalOpen(false);
  };

  const handleRestockCheck = async () => { setIsLoadingAi(true); const suggestions = await suggestRestock(products); setAiSuggestions(suggestions); setIsLoadingAi(false); showToast("AI analysis complete.", 'SUCCESS'); };

  const handleSort = (field: SortField) => { if (sortField === field) setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc'); else { setSortField(field); setSortDirection('asc'); } };

  const HeaderCell = ({ field, label, align = 'left' }: { field: SortField, label: string, align?: 'left' | 'center' | 'right' }) => (
      <th className={`p-4 text-xs font-semibold text-slate-600 dark:text-slate-300 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700 transition select-none text-${align}`} onClick={() => handleSort(field)}>
          <div className={`flex items-center ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
              {label}{sortField === field ? (sortDirection === 'asc' ? <ArrowUp size={14} className="ml-1 text-blue-500" /> : <ArrowDown size={14} className="ml-1 text-blue-500" />) : <ChevronsUpDown size={14} className="ml-1 text-slate-400" />}
          </div>
      </th>
  );

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-full mr-4"><Package size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Total Items</p><p className="text-lg font-bold text-slate-800 dark:text-white">{formatNumber(products.reduce((acc, p) => acc + p.stock, 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-full mr-4"><DollarSign size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Inventory Value</p><p className="text-lg font-bold text-slate-800 dark:text-white">{symbol}{formatCurrency(products.reduce((acc, p) => acc + (p.price * p.stock), 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 rounded-full mr-4"><AlertTriangle size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Low Stock</p><p className="text-lg font-bold text-slate-800 dark:text-white">{products.filter(p => p.stock <= p.minStockLevel).length}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 rounded-full mr-4"><History size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Expired</p><p className="text-lg font-bold text-slate-800 dark:text-white">{products.filter(p => (getDaysUntilExpiry(p.stockExpiryDate) || 0) < 0).length}</p></div>
          </div>
      </div>

      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
          <div className="flex flex-col md:flex-row gap-4 w-full xl:w-auto">
              <div className="relative w-full md:w-64"><Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"/></div>
              <div className="flex gap-2">
                  <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 outline-none">
                      {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  <select value={filterStockStatus} onChange={(e) => setFilterStockStatus(e.target.value as any)} className="pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 outline-none">
                      <option value="ALL">All Stock</option><option value="LOW">Low</option><option value="OUT">Out</option><option value="IN">In</option>
                  </select>
              </div>
          </div>
          <div className="flex flex-wrap gap-2 w-full xl:w-auto justify-end">
              <button onClick={exportToExcel} className="px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-medium hover:bg-emerald-700 transition flex items-center shadow-sm">
                  <FileSpreadsheet size={16} className="mr-2"/> Export Designed CSV
              </button>
              <button onClick={handleRestockCheck} disabled={isLoadingAi} className="px-4 py-2 bg-purple-600 text-white rounded-lg text-sm font-medium hover:bg-purple-700 transition flex items-center shadow-sm">
                  <Wand2 size={16} className={`mr-2 ${isLoadingAi ? 'animate-spin' : ''}`}/> AI Audit
              </button>
              <button onClick={() => handleOpenModal()} className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition flex items-center shadow-sm">
                  <Plus size={16} className="mr-2"/> Add Product
              </button>
          </div>
      </div>

      {aiSuggestions.length > 0 && (
          <div className="bg-gradient-to-r from-purple-50 to-indigo-50 dark:from-purple-900/20 dark:to-indigo-900/20 border border-purple-100 dark:border-purple-800 rounded-xl p-4 flex items-start gap-4">
              <div className="p-2 bg-purple-100 dark:bg-purple-900/50 rounded-full text-purple-600 dark:text-purple-300 shrink-0"><Wand2 size={20}/></div>
              <div className="flex-1"><h4 className="font-bold text-purple-900 dark:text-purple-300 mb-2 text-sm">AI Analysis</h4><div className="flex flex-wrap gap-2">{aiSuggestions.map((s, i) => (<div key={i} className="bg-white dark:bg-slate-800 px-3 py-1 rounded-lg shadow-sm border border-purple-100 dark:border-slate-700 text-xs flex items-center"><span className="font-bold mr-2">{s.productName}:</span><span>{s.suggestedAction}</span></div>))}</div></div>
              <button onClick={() => setAiSuggestions([])}><X size={18} className="text-slate-400"/></button>
          </div>
      )}

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
          <div className="overflow-x-auto">
              <table className="w-full text-left">
                  <thead className="bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-700">
                      <tr>
                          <HeaderCell field="name" label="Product" />
                          <HeaderCell field="sku" label="SKU" />
                          <HeaderCell field="category" label="Category" />
                          <HeaderCell field="stockExpiryDate" label="Expiry" />
                          <HeaderCell field="price" label="Price" align="right" />
                          <HeaderCell field="margin" label="Margin" align="right" />
                          <HeaderCell field="stock" label="Stock" align="center" />
                          <th className="p-4 text-xs font-semibold text-right">Actions</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                      {processedProducts.map(product => {
                          const days = getDaysUntilExpiry(product.stockExpiryDate);
                          const status = getExpiryStatus(days);
                          const margin = product.price > 0 ? ((product.price - product.cost) / product.price * 100) : 0;
                          return (
                              <tr key={product.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition group">
                                  <td className="p-4"><div className="flex items-center"><div className="w-10 h-10 rounded bg-slate-100 dark:bg-slate-700 mr-3 overflow-hidden flex items-center justify-center shrink-0"><img src={product.imageUrl || "https://placehold.co/40"} alt="" className="w-full h-full object-cover"/></div><div className="text-sm font-medium">{product.name}</div></div></td>
                                  <td className="p-4 text-xs font-mono text-slate-500">{product.sku}</td>
                                  <td className="p-4"><span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300">{product.category}</span></td>
                                  <td className="p-4 text-xs">{product.stockExpiryDate ? <div className={`${status === 'EXPIRED' ? 'text-red-500 font-bold' : status === 'WARNING' ? 'text-orange-500' : 'text-slate-500'}`}>{product.stockExpiryDate}</div> : '-'}</td>
                                  <td className="p-4 text-right font-medium">{symbol}{product.price.toFixed(2)}</td>
                                  <td className="p-4 text-right"><span className={`text-xs font-bold ${margin < 15 ? 'text-red-500' : 'text-green-600'}`}>{margin.toFixed(1)}%</span></td>
                                  <td className="p-4 text-center font-bold">{product.stock} <span className="text-[10px] text-slate-400 font-normal">{product.unit}</span></td>
                                  <td className="p-4 text-right"><div className="flex items-center justify-end space-x-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => handleOpenAdjModal(product)} className="p-1.5 text-blue-600 rounded" title="Adjust Stock"><Scale size={16}/></button><button onClick={() => handleOpenModal(product)} className="p-1.5 text-slate-600 rounded" title="Edit"><Edit2 size={16}/></button><button onClick={() => handleDelete(product.id)} className="p-1.5 text-red-500 rounded" title="Delete"><Trash2 size={16}/></button></div></td>
                              </tr>
                          );
                      })}
                  </tbody>
              </table>
          </div>
      </div>

      {isModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col">
                  <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-xl"><h3 className="font-bold">{editingProduct ? 'Edit Product' : 'Add Product'}</h3><button onClick={() => setIsModalOpen(false)}><X size={20}/></button></div>
                  <div className="flex-1 overflow-y-auto p-6 space-y-4">
                      <div className="grid grid-cols-2 gap-4">
                          <div className="col-span-2"><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Name</label><input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">SKU</label><input type="text" value={formData.sku} onChange={e => setFormData({...formData, sku: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Category</label><input type="text" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Cost Price</label><input type="number" value={formData.cost} onChange={e => setFormData({...formData, cost: parseFloat(e.target.value)})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Selling Price</label><input type="number" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                      </div>
                      <div className="flex items-center gap-2"><input type="checkbox" id="decimal" checked={formData.allowDecimal} onChange={e => setFormData({...formData, allowDecimal: e.target.checked})} className="rounded text-blue-600"/><label htmlFor="decimal" className="text-sm font-medium">Allow Decimal Quantities</label></div>
                  </div>
                  <div className="p-4 border-t flex justify-end gap-2 bg-slate-50 dark:bg-slate-800/50 rounded-b-xl"><button onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm text-slate-500">Cancel</button><button onClick={handleSave} className="px-6 py-2 bg-blue-600 text-white rounded-lg font-bold">Save</button></div>
              </div>
          </div>
      )}

      {isAdjModalOpen && selectedProductForAdj && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-sm p-6">
                  <h3 className="text-lg font-bold mb-4">Adjust Stock: {selectedProductForAdj.name}</h3>
                  <div className="space-y-4">
                      <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-lg">
                          {['ADD', 'REMOVE', 'SET'].map(type => (
                              <button key={type} onClick={() => setAdjType(type as AdjustmentType)} className={`flex-1 py-1.5 text-xs font-bold rounded ${adjType === type ? 'bg-white dark:bg-slate-600 shadow text-blue-600' : 'text-slate-500'}`}>{type}</button>
                          ))}
                      </div>
                      <input type="number" step={selectedProductForAdj.allowDecimal ? "0.001" : "1"} value={adjQuantity} onChange={e => setAdjQuantity(parseFloat(e.target.value) || 0)} className="w-full p-3 text-center text-2xl font-bold border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" autoFocus/>
                      <select value={adjReason} onChange={e => setAdjReason(e.target.value)} className="w-full p-2 border rounded text-sm bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white"><option>Stock Count Correction</option><option>Damage</option><option>Received Shipment</option></select>
                  </div>
                  <div className="mt-6 flex justify-end gap-2"><button onClick={() => setIsAdjModalOpen(false)} className="px-4 py-2 text-slate-500 text-sm">Cancel</button><button onClick={handleSubmitAdjustment} className="px-6 py-2 bg-blue-600 text-white font-bold rounded-lg text-sm">Confirm</button></div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Inventory;

import { GoogleGenAI, Type } from "@google/genai";
import { Product, Sale } from "../types";

// Always use process.env.API_KEY directly for initialization.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateProductDescription = async (name: string, category: string): Promise<string> => {
  if (!process.env.API_KEY) return "API Key missing. Cannot generate description.";

  try {
    const response = await ai.models.generateContent({
      // Use gemini-3-flash-preview for basic text tasks.
      model: "gemini-3-flash-preview",
      contents: `Write a short, engaging, and sales-oriented product description (max 2 sentences) for a product named "${name}" in the category "${category}".`,
    });
    // Access .text property directly.
    return response.text || "No description generated.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Failed to generate description due to an error.";
  }
};

export const analyzeBusinessData = async (sales: Sale[], products: Product[]): Promise<string> => {
  if (!process.env.API_KEY) return "API Key missing. Cannot analyze data.";

  // Summarize data to avoid token limits.
  const totalRevenue = sales.reduce((acc, sale) => acc + sale.totalAmount, 0);
  const lowStockProducts = products.filter(p => p.stock <= p.minStockLevel).map(p => p.name);
  const recentSalesCount = sales.length;

  const prompt = `
    Analyze the following business snapshot and provide 3 brief, actionable insights (bullet points):
    - Total Revenue: $${totalRevenue.toFixed(2)}
    - Recent Transaction Count: ${recentSalesCount}
    - Products with Low Stock: ${lowStockProducts.join(', ') || 'None'}

    Focus on inventory health and sales performance.
  `;

  try {
    const response = await ai.models.generateContent({
      // Use gemini-3-flash-preview for complex reasoning tasks.
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 } // Speed over deep thought for dashboard.
      }
    });
    // Access .text property directly.
    return response.text || "No insights available.";
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return "Unable to analyze business data at this time.";
  }
};

export const suggestRestock = async (products: Product[]): Promise<any[]> => {
    if (!process.env.API_KEY) return [];

    const inventoryData = products.map(p => ({
        name: p.name,
        currentStock: p.stock,
        minLevel: p.minStockLevel,
        salesVelocity: 'Unknown' // In a real app, calculate this.
    }));

    try {
        const response = await ai.models.generateContent({
            // Use gemini-3-flash-preview for JSON response tasks.
            model: "gemini-3-flash-preview",
            contents: `Given this inventory list: ${JSON.stringify(inventoryData)}. 
            Return a JSON array of objects with properties: "productName" and "suggestedAction" (e.g., "Restock Urgent", "Monitor", "OK"). 
            Only include items that need attention.`,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            productName: { type: Type.STRING },
                            suggestedAction: { type: Type.STRING }
                        }
                    }
                }
            }
        });

        // Access .text property directly.
        const text = response.text;
        if (!text) return [];
        return JSON.parse(text);
    } catch (e) {
        console.error("Restock Suggestion Error", e);
        return [];
    }
}

import React, { useEffect, useState } from 'react';
import { Sale, Product, ReturnTransaction } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, LineChart, Line, PieChart, Pie, Cell, Legend, ComposedChart } from 'recharts';
import { analyzeBusinessData } from '../services/geminiService';
import { TrendingUp, AlertTriangle, DollarSign, Package, PieChart as PieChartIcon, Calendar, ArrowDownRight } from 'lucide-react';

interface DashboardProps {
  sales: Sale[];
  products: Product[];
  returns: ReturnTransaction[];
  currency: string;
}

const Dashboard: React.FC<DashboardProps> = ({ sales, products, returns, currency }) => {
  const [insight, setInsight] = useState<string>('Loading AI insights...');

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  };

  const symbol = getCurrencySymbol(currency);

  // --- Calculations ---

  // 1. Gross Revenue (from Sales)
  const grossRevenue = sales.reduce((acc, s) => acc + s.totalAmount, 0);

  // 2. Total Refunds (from Returns)
  const totalRefunds = returns.reduce((acc, r) => acc + r.totalRefund, 0);

  // 3. Net Revenue
  const netRevenue = grossRevenue - totalRefunds;

  // 4. Net Profit Calculation
  // Gross Profit from Sales
  const grossProfit = sales.reduce((acc, s) => acc + s.totalProfit, 0);

  // Refunded Profit (We must reverse the profit gained from items that were returned)
  // Logic: For each returned item, find the original SaleItem to get (Price - Cost) * ReturnedQty
  const profitLostFromReturns = returns.reduce((totalLost, ret) => {
      const originalSale = sales.find(s => s.id === ret.originalSaleId);
      if (!originalSale) return totalLost; // Should not happen if data integrity is kept

      const returnLoss = ret.items.reduce((itemLost, retItem) => {
          const originalItem = originalSale.items.find(i => i.productId === retItem.productId);
          if (!originalItem) return itemLost;

          // Profit per unit = PriceAtSale - CostAtSale
          const unitProfit = originalItem.priceAtSale - originalItem.costAtSale;
          return itemLost + (unitProfit * retItem.quantity);
      }, 0);

      return totalLost + returnLoss;
  }, 0);

  const netProfit = grossProfit - profitLostFromReturns;

  const lowStockCount = products.filter(p => p.stock <= p.minStockLevel).length;

  // --- Chart Data Preparation ---

  // Sales Trend (Last 7 Days) - Net Revenue
  const last7Days = Array.from({length: 7}, (_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - i);
    return d.toISOString().split('T')[0];
  }).reverse();

  const salesData = last7Days.map(date => {
    // Sales on this day
    const daySales = sales.filter(s => new Date(s.timestamp).toISOString().split('T')[0] === date);
    const dayGross = daySales.reduce((sum, s) => sum + s.totalAmount, 0);

    // Returns on this day
    const dayReturns = returns.filter(r => new Date(r.timestamp).toISOString().split('T')[0] === date);
    const dayRefunds = dayReturns.reduce((sum, r) => sum + r.totalRefund, 0);

    return {
      date: date.slice(5), // MM-DD
      amount: dayGross - dayRefunds // Net
    };
  });

  // Current Month Performance (Daily)
  const now = new Date();
  const currentMonth = now.getMonth();
  const currentYear = now.getFullYear();

  // Filter for Current Month
  const currentMonthSales = sales.filter(s => {
      const d = new Date(s.timestamp);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
  });

  const currentMonthReturns = returns.filter(r => {
      const d = new Date(r.timestamp);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
  });

  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
  const monthDailyData = Array.from({ length: daysInMonth }, (_, i) => {
      const day = i + 1;

      // Sales for Day
      const daySales = currentMonthSales.filter(s => new Date(s.timestamp).getDate() === day);
      const dailyGross = daySales.reduce((acc, s) => acc + s.totalAmount, 0);

      // Returns for Day
      const dayReturns = currentMonthReturns.filter(r => new Date(r.timestamp).getDate() === day);
      const dailyRefunds = dayReturns.reduce((acc, r) => acc + r.totalRefund, 0);

      // Profit Calculation for Day
      const dailyGrossProfit = daySales.reduce((acc, s) => acc + s.totalProfit, 0);

      const dailyReturnProfitLoss = dayReturns.reduce((totalLost, ret) => {
          const originalSale = sales.find(s => s.id === ret.originalSaleId); // Look in ALL sales for history
          if (!originalSale) return totalLost;
          return totalLost + ret.items.reduce((itemLost, retItem) => {
              const originalItem = originalSale.items.find(item => item.productId === retItem.productId);
              if (!originalItem) return itemLost;
              return itemLost + ((originalItem.priceAtSale - originalItem.costAtSale) * retItem.quantity);
          }, 0);
      }, 0);

      return {
          day: day.toString(),
          sales: dailyGross - dailyRefunds,
          profit: dailyGrossProfit - dailyReturnProfitLoss,
          transactions: daySales.length // Count sales transactions only for foot traffic approximation
      };
  });

  // Category Map Logic (Based on Net Sales)
  // We iterate sales to add, and returns to subtract from category totals
  const categoryMap: Record<string, number> = {};

