import { Plus, Edit2, Trash2, Search, Wand2, History, X, FileSpreadsheet, Package, DollarSign, AlertTriangle, Scale, ArrowUp, ArrowDown, ChevronsUpDown } from 'lucide-react';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  stockAdjustments: StockAdjustment[];
  onAdjustStock: (adjustment: StockAdjustment) => void;
  onBulkAdjustStock: (adjustments: StockAdjustment[]) => void;
  currentUser: User;
  currency: string;
  showToast: (message: string, type: 'SUCCESS' | 'ERROR' | 'INFO') => void;
  returns: ReturnTransaction[];
  customers: Customer[];
  sales: Sale[];
  priceHistory: PriceHistory[];
  onLogPriceChange: (log: PriceHistory) => void;
}

type SortField = 'name' | 'sku' | 'category' | 'price' | 'stock' | 'stockExpiryDate' | 'cost' | 'margin';
type SortDirection = 'asc' | 'desc';

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, stockAdjustments, onAdjustStock, onBulkAdjustStock, currentUser, currency, showToast, returns, customers, sales, priceHistory, onLogPriceChange }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);

  // Search & Filter State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('ALL');
  const [filterStockStatus, setFilterStockStatus] = useState<'ALL' | 'LOW' | 'OUT' | 'IN'>('ALL');
  const [filterExpiry, setFilterExpiry] = useState<'ALL' | 'EXPIRED' | 'SOON' | 'VALID'>('ALL');

  // Sorting State
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');

  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [isLoadingAi, setIsLoadingAi] = useState(false);

  // Adjustment State
  const [isAdjModalOpen, setIsAdjModalOpen] = useState(false);
  const [selectedProductForAdj, setSelectedProductForAdj] = useState<Product | null>(null);
  const [adjType, setAdjType] = useState<AdjustmentType>('ADD');
  const [adjQuantity, setAdjQuantity] = useState(0);
  const [adjReason, setAdjReason] = useState('Stock Count Correction');
  const [adjNotes, setAdjNotes] = useState('');

  // Form State
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false
  });

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  };

  const symbol = getCurrencySymbol(currency);
  const formatCurrency = (val: number) => val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const formatNumber = (val: number) => val.toLocaleString('en-US', { maximumFractionDigits: 3 });

  const categories = useMemo(() => {
      const cats = new Set(products.map(p => p.category).filter(Boolean));
      return ['ALL', ...Array.from(cats).sort()];
  }, [products]);

  const processedProducts = useMemo(() => {
      let filtered = products.filter(p => 
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        p.sku.toLowerCase().includes(searchTerm.toLowerCase())
      );
      if (filterCategory !== 'ALL') filtered = filtered.filter(p => p.category === filterCategory);
      if (filterStockStatus !== 'ALL') {
          if (filterStockStatus === 'OUT') filtered = filtered.filter(p => p.stock === 0);
          if (filterStockStatus === 'LOW') filtered = filtered.filter(p => p.stock > 0 && p.stock <= p.minStockLevel);
          if (filterStockStatus === 'IN') filtered = filtered.filter(p => p.stock > p.minStockLevel);
      }
      if (filterExpiry !== 'ALL') {
          filtered = filtered.filter(p => {
              const days = getDaysUntilExpiry(p.stockExpiryDate);
              if (filterExpiry === 'EXPIRED') return days !== null && days < 0;
              if (filterExpiry === 'SOON') return days !== null && days >= 0 && days <= 30;
              if (filterExpiry === 'VALID') return days === null || days > 30;
              return true;
          });
      }
      return filtered.sort((a, b) => {
          let valA: any = a[sortField];
          let valB: any = b[sortField];
          if (sortField === 'margin') {
              valA = a.price > 0 ? ((a.price - a.cost) / a.price) : -999;
              valB = b.price > 0 ? ((b.price - b.cost) / b.price) : -999;
          }
          if (typeof valA === 'string') return sortDirection === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
          return sortDirection === 'asc' ? (valA < valB ? -1 : 1) : (valB < valA ? -1 : 1);
      });
  }, [products, searchTerm, filterCategory, filterStockStatus, filterExpiry, sortField, sortDirection]);

  // High-Design Hierarchy Export
  const exportToExcel = () => {
    const headers = [
      "CATEGORY / HIERARCHY", 
      "PRODUCT NAME", 
      "SKU", 
      "CURRENT STOCK", 
      "UNIT", 
      "COST PRICE", 
      "SELLING PRICE", 
      "STOCK SOLD (QTY)", 
      "STOCK RETURNED (QTY)", 
      "NET SOLD (QTY)", 
      "REVENUE (NET)", 
      "COST OF GOODS SOLD (COGS)", 
      "PROFIT / LOSS", 
      "MARGIN (%)"
    ];

    // Group items by category
    const groupedProducts: Record<string, Product[]> = {};
    processedProducts.forEach(p => {
        const cat = p.category || 'Uncategorized';
        if (!groupedProducts[cat]) groupedProducts[cat] = [];
        groupedProducts[cat].push(p);
    });

    const rows: string[] = [];

    // Grand Totals trackers
    let grandRevenue = 0;
    let grandCost = 0;
    let grandProfit = 0;
    let grandSold = 0;
    let grandReturned = 0;

    // Report Branding
    rows.push([`"NEXUS INVENTORY & PERFORMANCE REPORT"`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`].join(","));
    rows.push([`"Generated on: ${new Date().toLocaleString()}"`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`, `""`].join(","));
    // FIX: rows.push expects a string, not string[]. (Error on Line 144)
    rows.push(""); // Spacer

    Object.keys(groupedProducts).sort().forEach(cat => {
        // Category Header Section
        rows.push([`"--- SECTION: ${cat.toUpperCase()} ---"`, "", "", "", "", "", "", "", "", "", "", "", "", ""].join(","));

        let catRevenue = 0;
        let catCost = 0;
        let catProfit = 0;
        let catSold = 0;
        let catReturned = 0;

        groupedProducts[cat].forEach(p => {
            // Calculate specific metrics for this product
            const productSales = sales.flatMap(s => s.items.filter(i => i.productId === p.id));
            const totalSold = productSales.reduce((sum, i) => sum + i.quantity, 0);

            const productReturns = returns.flatMap(r => r.items.filter(ri => ri.productId === p.id));
            const totalReturned = productReturns.reduce((sum, i) => sum + i.quantity, 0);

            const netSold = totalSold - totalReturned;

            // Financial Calculations
            const grossRevenue = productSales.reduce((sum, i) => sum + (i.priceAtSale * i.quantity), 0);
            const grossCOGS = productSales.reduce((sum, i) => sum + (i.costAtSale * i.quantity), 0);

            // Refund Impact
            const totalRefundedAmt = returns.reduce((sum, r) => {
                const ri = r.items.find(item => item.productId === p.id);
                return sum + (ri ? ri.refundAmount : 0);
            }, 0);

            const refundedCOGS = returns.reduce((sum, r) => {
                const origSale = sales.find(s => s.id === r.originalSaleId);
                if (!origSale) return sum;
                const ri = r.items.find(item => item.productId === p.id);
                const si = origSale.items.find(item => item.productId === p.id);
                return sum + (ri && si ? (si.costAtSale * ri.quantity) : 0);
            }, 0);

            const netRevenue = grossRevenue - totalRefundedAmt;
            const netCOGS = grossCOGS - refundedCOGS;
            const netProfit = netRevenue - netCOGS;
            const margin = netRevenue > 0 ? (netProfit / netRevenue * 100).toFixed(2) : (p.price > 0 ? ((p.price - p.cost) / p.price * 100).toFixed(2) : '0');

            // Category aggregation
            catRevenue += netRevenue;
            catCost += netCOGS;
            catProfit += netProfit;
            catSold += totalSold;
            catReturned += totalReturned;

            // FIX: Ensure all array items joined are strings for consistent type safety. (Error on Line 227)
            rows.push([
                `"    ${cat}"`, // Indented category name
                `"${p.name.replace(/"/g, '""')}"`,
                `"${p.sku}"`,
                String(p.stock),
                `"${p.unit || 'pcs'}"`,
                p.cost.toFixed(2),
                p.price.toFixed(2),
                String(totalSold),
                String(totalReturned),
                String(netSold),
                netRevenue.toFixed(2),
                netCOGS.toFixed(2),
                netProfit.toFixed(2),
                `"${margin}%"`
            ].join(","));
        });

        // Add Category Sub-total Hierarchy Row
        rows.push([
            `"SUB-TOTAL: ${cat.toUpperCase()}"`, 
            `""`, `""`, `""`, `""`, `""`, `""`, 
            String(catSold), 
            String(catReturned), 
            String(catSold - catReturned), 
            catRevenue.toFixed(2), 
            catCost.toFixed(2), 
            catProfit.toFixed(2), 
            `"${catRevenue > 0 ? (catProfit / catRevenue * 100).toFixed(2) : '0'}%"`
        ].join(","));

        // FIX: rows.push expects a string, not string[]. (Error on Line 238)
        rows.push(""); // Vertical spacer between categories

        // Add to Grand Totals
        grandRevenue += catRevenue;
        grandCost += catCost;
        grandProfit += catProfit;
        grandSold += catSold;
        grandReturned += catReturned;
    });

    // Final Report Footer Summary
    // FIX: rows.push expects a string, not string[]. (Error on Line 241)
    rows.push("");
    // FIX: rows.push expects a string. (Error on Line 242)
    rows.push("==========================================================================================================");
    // FIX: Use grandProfit for the overall report total instead of the loop-scoped catProfit.
    rows.push([`"GRAND REPORT TOTALS"`, `""`, `""`, `""`, `""`, `""`, `""`, String(grandSold), String(grandReturned), String(grandSold - grandReturned), grandRevenue.toFixed(2), grandCost.toFixed(2), grandProfit.toFixed(2), `"${grandRevenue > 0 ? (grandProfit / grandRevenue * 100).toFixed(2) : '0'}%"`].join(","));
    rows.push("==========================================================================================================");

    const csvContent = "\uFEFF" + [headers.join(","), ...rows].join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `Detailed_Nexus_Inventory_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast("Designed hierarchical report exported successfully.", "SUCCESS");
  };

  const getDaysUntilExpiry = (dateString?: string) => {
      if (!dateString) return null;
      const [year, month, day] = dateString.split('-').map(Number);
      const expiry = new Date(year, month - 1, day);
      const diffTime = expiry.getTime() - new Date().setHours(0,0,0,0);
      return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const getExpiryStatus = (days: number | null) => {
      if (days === null) return 'NONE';
      if (days < 0) return 'EXPIRED';
      if (days <= 30) return 'WARNING';
      return 'OK';
  };

  const handleOpenModal = (product?: Product) => {
    if (product) { setEditingProduct(product); setFormData(product); }
    else { setEditingProduct(null); setFormData({ name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false }); }
    setIsModalOpen(true);
  };

  const handleOpenAdjModal = (product: Product) => { setSelectedProductForAdj(product); setAdjType('ADD'); setAdjQuantity(0); setAdjReason('Stock Count Correction'); setAdjNotes(''); setIsAdjModalOpen(true); };

  const handleSave = () => {
    if (!formData.name || !formData.price || !formData.category) { showToast("Name, Category, and Price are required.", 'ERROR'); return; }
    if (editingProduct) {
      if (formData.price !== editingProduct.price) onLogPriceChange({ id: `ph-${Date.now()}-p`, productId: editingProduct.id, type: 'PRICE', oldValue: editingProduct.price, newValue: formData.price || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      if (formData.cost !== editingProduct.cost) onLogPriceChange({ id: `ph-${Date.now()}-c`, productId: editingProduct.id, type: 'COST', oldValue: editingProduct.cost, newValue: formData.cost || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      setProducts(prev => prev.map(p => p.id === editingProduct.id ? { ...p, ...formData } as Product : p));
      showToast("Product updated.", 'SUCCESS');
    } else {
      setProducts(prev => [...prev, { id: `p-${Date.now()}`, ...formData as Product }]);
      showToast("Product added.", 'SUCCESS');
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => { if (window.confirm('Delete this product?')) { setProducts(prev => prev.filter(p => p.id !== id)); showToast("Product deleted.", 'INFO'); } };

  const handleSubmitAdjustment = () => {
      if (!selectedProductForAdj) return;
      let newStock = selectedProductForAdj.stock;
      if (adjType === 'ADD') newStock = parseFloat((selectedProductForAdj.stock + adjQuantity).toFixed(3));
      if (adjType === 'REMOVE') newStock = parseFloat((selectedProductForAdj.stock - adjQuantity).toFixed(3));
      if (adjType === 'SET') newStock = adjQuantity;
      if (newStock < 0) { showToast("Stock cannot be negative.", 'ERROR'); return; }
      onAdjustStock({ id: `adj-${Date.now()}`, productId: selectedProductForAdj.id, productName: selectedProductForAdj.name, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now(), type: adjType, quantity: adjQuantity, previousStock: selectedProductForAdj.stock, newStock, reason: adjReason, notes: adjNotes });
      setIsAdjModalOpen(false);
  };

  const handleRestockCheck = async () => { setIsLoadingAi(true); const suggestions = await suggestRestock(products); setAiSuggestions(suggestions); setIsLoadingAi(false); showToast("AI analysis complete.", 'SUCCESS'); };

  const handleSort = (field: SortField) => { if (sortField === field) setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc'); else { setSortField(field); setSortDirection('asc'); } };

  const HeaderCell = ({ field, label, align = 'left' }: { field: SortField, label: string, align?: 'left' | 'center' | 'right' }) => (
      <th className={`p-4 text-xs font-semibold text-slate-600 dark:text-slate-300 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700 transition select-none text-${align}`} onClick={() => handleSort(field)}>
          <div className={`flex items-center ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
              {label}{sortField === field ? (sortDirection === 'asc' ? <ArrowUp size={14} className="ml-1 text-blue-500" /> : <ArrowDown size={14} className="ml-1 text-blue-500" />) : <ChevronsUpDown size={14} className="ml-1 text-slate-400" />}
          </div>
      </th>
  );

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-full mr-4"><Package size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Total Items</p><p className="text-lg font-bold text-slate-800 dark:text-white">{formatNumber(products.reduce((acc, p) => acc + p.stock, 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-full mr-4"><DollarSign size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Inventory Value</p><p className="text-lg font-bold text-slate-800 dark:text-white">{symbol}{formatCurrency(products.reduce((acc, p) => acc + (p.price * p.stock), 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 rounded-full mr-4"><AlertTriangle size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Low Stock</p><p className="text-lg font-bold text-slate-800 dark:text-white">{products.filter(p => p.stock <= p.minStockLevel).length}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 rounded-full mr-4"><History size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Expired</p><p className="text-lg font-bold text-slate-800 dark:text-white">{products.filter(p => (getDaysUntilExpiry(p.stockExpiryDate) || 0) < 0).length}</p></div>
          </div>
      </div>

      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
          <div className="flex flex-col md:flex-row gap-4 w-full xl:w-auto">
              <div className="relative w-full md:w-64"><Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"/></div>
              <div className="flex gap-2">
                  <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 outline-none">
                      {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  <select value={filterStockStatus} onChange={(e) => setFilterStockStatus(e.target.value as any)} className="pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 outline-none">
                      <option value="ALL">All Stock</option><option value="LOW">Low</option><option value="OUT">Out</option><option value="IN">In</option>
                  </select>
              </div>
          </div>
          <div className="flex flex-wrap gap-2 w-full xl:w-auto justify-end">
              <button onClick={exportToExcel} className="px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-medium hover:bg-emerald-700 transition flex items-center shadow-sm">
                  <FileSpreadsheet size={16} className="mr-2"/> Export Designed CSV
              </button>
              <button onClick={handleRestockCheck} disabled={isLoadingAi} className="px-4 py-2 bg-purple-600 text-white rounded-lg text-sm font-medium hover:bg-purple-700 transition flex items-center shadow-sm">
                  <Wand2 size={16} className={`mr-2 ${isLoadingAi ? 'animate-spin' : ''}`}/> AI Audit
              </button>
              <button onClick={() => handleOpenModal()} className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition flex items-center shadow-sm">
                  <Plus size={16} className="mr-2"/> Add Product
              </button>
          </div>
      </div>

      {aiSuggestions.length > 0 && (
          <div className="bg-gradient-to-r from-purple-50 to-indigo-50 dark:from-purple-900/20 dark:to-indigo-900/20 border border-purple-100 dark:border-purple-800 rounded-xl p-4 flex items-start gap-4">
              <div className="p-2 bg-purple-100 dark:bg-purple-900/50 rounded-full text-purple-600 dark:text-purple-300 shrink-0"><Wand2 size={20}/></div>
              <div className="flex-1"><h4 className="font-bold text-purple-900 dark:text-purple-300 mb-2 text-sm">AI Analysis</h4><div className="flex flex-wrap gap-2">{aiSuggestions.map((s, i) => (<div key={i} className="bg-white dark:bg-slate-800 px-3 py-1 rounded-lg shadow-sm border border-purple-100 dark:border-slate-700 text-xs flex items-center"><span className="font-bold mr-2">{s.productName}:</span><span>{s.suggestedAction}</span></div>))}</div></div>
              <button onClick={() => setAiSuggestions([])}><X size={18} className="text-slate-400"/></button>
          </div>
      )}

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
          <div className="overflow-x-auto">
              <table className="w-full text-left">
                  <thead className="bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-700">
                      <tr>
                          <HeaderCell field="name" label="Product" />
                          <HeaderCell field="sku" label="SKU" />
                          <HeaderCell field="category" label="Category" />
                          <HeaderCell field="stockExpiryDate" label="Expiry" />
                          <HeaderCell field="price" label="Price" align="right" />
                          <HeaderCell field="margin" label="Margin" align="right" />
                          <HeaderCell field="stock" label="Stock" align="center" />
                          <th className="p-4 text-xs font-semibold text-right">Actions</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                      {processedProducts.map(product => {
                          const days = getDaysUntilExpiry(product.stockExpiryDate);
                          const status = getExpiryStatus(days);
                          const margin = product.price > 0 ? ((product.price - product.cost) / product.price * 100) : 0;
                          return (
                              <tr key={product.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition group">
                                  <td className="p-4"><div className="flex items-center"><div className="w-10 h-10 rounded bg-slate-100 dark:bg-slate-700 mr-3 overflow-hidden flex items-center justify-center shrink-0"><img src={product.imageUrl || "https://placehold.co/40"} alt="" className="w-full h-full object-cover"/></div><div className="text-sm font-medium">{product.name}</div></div></td>
                                  <td className="p-4 text-xs font-mono text-slate-500">{product.sku}</td>
                                  <td className="p-4"><span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300">{product.category}</span></td>
                                  <td className="p-4 text-xs">{product.stockExpiryDate ? <div className={`${status === 'EXPIRED' ? 'text-red-500 font-bold' : status === 'WARNING' ? 'text-orange-500' : 'text-slate-500'}`}>{product.stockExpiryDate}</div> : '-'}</td>
                                  <td className="p-4 text-right font-medium">{symbol}{product.price.toFixed(2)}</td>
                                  <td className="p-4 text-right"><span className={`text-xs font-bold ${margin < 15 ? 'text-red-500' : 'text-green-600'}`}>{margin.toFixed(1)}%</span></td>
                                  <td className="p-4 text-center font-bold">{product.stock} <span className="text-[10px] text-slate-400 font-normal">{product.unit}</span></td>
                                  <td className="p-4 text-right"><div className="flex items-center justify-end space-x-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => handleOpenAdjModal(product)} className="p-1.5 text-blue-600 rounded" title="Adjust Stock"><Scale size={16}/></button><button onClick={() => handleOpenModal(product)} className="p-1.5 text-slate-600 rounded" title="Edit"><Edit2 size={16}/></button><button onClick={() => handleDelete(product.id)} className="p-1.5 text-red-500 rounded" title="Delete"><Trash2 size={16}/></button></div></td>
                              </tr>
                          );
                      })}
                  </tbody>
              </table>
          </div>
      </div>

      {isModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col">
                  <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-xl"><h3 className="font-bold">{editingProduct ? 'Edit Product' : 'Add Product'}</h3><button onClick={() => setIsModalOpen(false)}><X size={20}/></button></div>
                  <div className="flex-1 overflow-y-auto p-6 space-y-4">
                      <div className="grid grid-cols-2 gap-4">
                          <div className="col-span-2"><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Name</label><input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">SKU</label><input type="text" value={formData.sku} onChange={e => setFormData({...formData, sku: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Category</label><input type="text" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Cost Price</label><input type="number" value={formData.cost} onChange={e => setFormData({...formData, cost: parseFloat(e.target.value)})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Selling Price</label><input type="number" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                      </div>
                      <div className="flex items-center gap-2"><input type="checkbox" id="decimal" checked={formData.allowDecimal} onChange={e => setFormData({...formData, allowDecimal: e.target.checked})} className="rounded text-blue-600"/><label htmlFor="decimal" className="text-sm font-medium">Allow Decimal Quantities</label></div>
                  </div>
                  <div className="p-4 border-t flex justify-end gap-2 bg-slate-50 dark:bg-slate-800/50 rounded-b-xl"><button onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm text-slate-500">Cancel</button><button onClick={handleSave} className="px-6 py-2 bg-blue-600 text-white rounded-lg font-bold">Save</button></div>
              </div>
          </div>
      )}

      {isAdjModalOpen && selectedProductForAdj && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-sm:w-full max-w-sm p-6">
                  <h3 className="text-lg font-bold mb-4">Adjust Stock: {selectedProductForAdj.name}</h3>
                  <div className="space-y-4">
                      <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-lg">
                          {['ADD', 'REMOVE', 'SET'].map(type => (
                              <button key={type} onClick={() => setAdjType(type as AdjustmentType)} className={`flex-1 py-1.5 text-xs font-bold rounded ${adjType === type ? 'bg-white dark:bg-slate-600 shadow text-blue-600' : 'text-slate-500'}`}>{type}</button>
                          ))}
                      </div>
                      <input type="number" step={selectedProductForAdj.allowDecimal ? "0.001" : "1"} value={adjQuantity} onChange={e => setAdjQuantity(parseFloat(e.target.value) || 0)} className="w-full p-3 text-center text-2xl font-bold border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" autoFocus/>
                      <select value={adjReason} onChange={e => setAdjReason(e.target.value)} className="w-full p-2 border rounded text-sm bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white"><option>Stock Count Correction</option><option>Damage</option><option>Received Shipment</option></select>
                  </div>
                  <div className="mt-6 flex justify-end gap-2"><button onClick={() => setIsAdjModalOpen(false)} className="px-4 py-2 text-slate-500 text-sm">Cancel</button><button onClick={handleSubmitAdjustment} className="px-6 py-2 bg-blue-600 text-white font-bold rounded-lg text-sm">Confirm</button></div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, StockAdjustment, AdjustmentType, User, ReturnTransaction, Customer, Sale, PriceHistory } from '../types';
import { suggestRestock } from '../services/geminiService';
import { Plus, Edit2, Trash2, Search, Wand2, History, X, FileSpreadsheet, Package, DollarSign, AlertTriangle, Scale, ArrowUp, ArrowDown, ChevronsUpDown } from 'lucide-react';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  stockAdjustments: StockAdjustment[];
  onAdjustStock: (adjustment: StockAdjustment) => void;
  onBulkAdjustStock: (adjustments: StockAdjustment[]) => void;
  currentUser: User;
  currency: string;
  showToast: (message: string, type: 'SUCCESS' | 'ERROR' | 'INFO') => void;
  returns: ReturnTransaction[];
  customers: Customer[];
  sales: Sale[];
  priceHistory: PriceHistory[];
  onLogPriceChange: (log: PriceHistory) => void;
}

type SortField = 'name' | 'sku' | 'category' | 'price' | 'stock' | 'stockExpiryDate' | 'cost' | 'margin';
type SortDirection = 'asc' | 'desc';

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, stockAdjustments, onAdjustStock, onBulkAdjustStock, currentUser, currency, showToast, returns, customers, sales, priceHistory, onLogPriceChange }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);

  // Search & Filter State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('ALL');
  const [filterStockStatus, setFilterStockStatus] = useState<'ALL' | 'LOW' | 'OUT' | 'IN'>('ALL');
  const [filterExpiry, setFilterExpiry] = useState<'ALL' | 'EXPIRED' | 'SOON' | 'VALID'>('ALL');

  // Sorting State
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');

  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [isLoadingAi, setIsLoadingAi] = useState(false);

  // Adjustment State
  const [isAdjModalOpen, setIsAdjModalOpen] = useState(false);
  const [selectedProductForAdj, setSelectedProductForAdj] = useState<Product | null>(null);
  const [adjType, setAdjType] = useState<AdjustmentType>('ADD');
  const [adjQuantity, setAdjQuantity] = useState(0);
  const [adjReason, setAdjReason] = useState('Stock Count Correction');
  const [adjNotes, setAdjNotes] = useState('');

  // Form State
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false
  });

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  };

  const symbol = getCurrencySymbol(currency);
  const formatCurrency = (val: number) => val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const formatNumber = (val: number) => val.toLocaleString('en-US', { maximumFractionDigits: 3 });

  const categories = useMemo(() => {
      const cats = new Set(products.map(p => p.category).filter(Boolean));
      return ['ALL', ...Array.from(cats).sort()];
  }, [products]);

  const processedProducts = useMemo(() => {
      let filtered = products.filter(p => 
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        p.sku.toLowerCase().includes(searchTerm.toLowerCase())
      );
      if (filterCategory !== 'ALL') filtered = filtered.filter(p => p.category === filterCategory);
      if (filterStockStatus !== 'ALL') {
          if (filterStockStatus === 'OUT') filtered = filtered.filter(p => p.stock === 0);
          if (filterStockStatus === 'LOW') filtered = filtered.filter(p => p.stock > 0 && p.stock <= p.minStockLevel);
          if (filterStockStatus === 'IN') filtered = filtered.filter(p => p.stock > p.minStockLevel);
      }
      if (filterExpiry !== 'ALL') {
          filtered = filtered.filter(p => {
              const days = getDaysUntilExpiry(p.stockExpiryDate);
              if (filterExpiry === 'EXPIRED') return days !== null && days < 0;
              if (filterExpiry === 'SOON') return days !== null && days >= 0 && days <= 30;
              if (filterExpiry === 'VALID') return days === null || days > 30;
              return true;
          });
      }
      return filtered.sort((a, b) => {
          let valA: any = a[sortField];
          let valB: any = b[sortField];
          if (sortField === 'margin') {
              valA = a.price > 0 ? ((a.price - a.cost) / a.price) : -999;
              valB = b.price > 0 ? ((b.price - b.cost) / b.price) : -999;
          }
          if (typeof valA === 'string') return sortDirection === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
          return sortDirection === 'asc' ? (valA < valB ? -1 : 1) : (valB < valA ? -1 : 1);
      });
  }, [products, searchTerm, filterCategory, filterStockStatus, filterExpiry, sortField, sortDirection]);

  // Exact Match for Requested Hierarchy and Design shown in the image
  const exportToExcel = () => {
    // 16 Columns based on the screenshot provided
    const headers = [
      "Product Name", "SKU", "Description", "Cost Price", "Selling Price", "Margin %", 
      "Stock", "Status", "Asset Value", "Retail Value", "Units Sold", "Total Revenue", 
      "Units Returned", "Total Refunded", "Net Profit", "Expiry Date"
    ];

    // Group items by category to create the hierarchy
    const groupedProducts: Record<string, Product[]> = {};
    processedProducts.forEach(p => {
        const cat = p.category || 'Uncategorized';
        if (!groupedProducts[cat]) groupedProducts[cat] = [];
        groupedProducts[cat].push(p);
    });

    const rows: string[] = [];

    // Grand Totals Accumulators
    let grandStock = 0;
    let grandAssetValue = 0;
    let grandRetailValue = 0;
    let grandUnitsSold = 0;
    let grandTotalRevenue = 0;
    let grandUnitsReturned = 0;
    let grandTotalRefunded = 0;
    let grandNetProfit = 0;

    Object.keys(groupedProducts).sort().forEach(cat => {
        // Add Category Hierarchy Header Row (matches visual style of image)
        rows.push([`"${cat}"`, "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""].join(","));

        groupedProducts[cat].forEach(p => {
            // Calculation Logic
            const margin = p.price > 0 ? ((p.price - p.cost) / p.price * 100).toFixed(2) + "%" : "0%";
            const statusText = p.stock === 0 ? "Out of Stock" : p.stock <= p.minStockLevel ? "Low Stock" : "In Stock";
            const assetValue = p.stock * p.cost;
            const retailValue = p.stock * p.price;

            // Sales Performance Data
            const productSales = sales.flatMap(s => s.items.filter(i => i.productId === p.id));
            const unitsSold = productSales.reduce((sum, i) => sum + i.quantity, 0);
            const totalRevenue = productSales.reduce((sum, i) => sum + (i.priceAtSale * i.quantity), 0);

            const productReturns = returns.flatMap(r => r.items.filter(ri => ri.productId === p.id));
            const unitsReturned = productReturns.reduce((sum, i) => sum + i.quantity, 0);
            const totalRefunded = productReturns.reduce((sum, i) => sum + i.refundAmount, 0);

            // Profit Calculation
            // Net Profit = (Revenue - Refunds) - COGS for net units sold
            // COGS of Net Units = (Sold - Returned) * Avg Cost (or cost at sale if we want depth)
            const cogs = productSales.reduce((sum, i) => sum + (i.costAtSale * i.quantity), 0);
            const refundCogsImpact = returns.reduce((sum, r) => {
                const origSale = sales.find(s => s.id === r.originalSaleId);
                if (!origSale) return sum;
                const rItem = r.items.find(ri => ri.productId === p.id);
                const sItem = origSale.items.find(si => si.productId === p.id);
                return sum + (rItem && sItem ? (sItem.costAtSale * rItem.quantity) : 0);
            }, 0);

            const netRevenue = totalRevenue - totalRefunded;
            const netCogs = cogs - refundCogsImpact;
            const netProfit = netRevenue - netCogs;

            // Grand Total Updates
            grandStock += p.stock;
            grandAssetValue += assetValue;
            grandRetailValue += retailValue;
            grandUnitsSold += unitsSold;
            grandTotalRevenue += totalRevenue;
            grandUnitsReturned += unitsReturned;
            grandTotalRefunded += totalRefunded;
            grandNetProfit += netProfit;

            rows.push([
                `"${p.name.replace(/"/g, '""')}"`,
                `"${p.sku}"`,
                `"${(p.description || '').replace(/"/g, '""')}"`,
                p.cost.toFixed(2),
                p.price.toFixed(2),
                `"${margin}"`,
                p.stock,
                `"${statusText}"`,
                assetValue.toFixed(2),
                retailValue.toFixed(2),
                unitsSold,
                totalRevenue.toFixed(2),
                unitsReturned,
                totalRefunded.toFixed(2),
                netProfit.toFixed(2),
                `"${p.stockExpiryDate || 'N/A'}"`
            ].join(","));
        });
    });

    // Add Grand Totals Row (matching footer style of image)
    rows.push([
        "", "", "", "", "", `"GRAND TOTALS"`, 
        grandStock, 
        "", 
        grandAssetValue.toFixed(2), 
        grandRetailValue.toFixed(2), 
        grandUnitsSold, 
        grandTotalRevenue.toFixed(2), 
        grandUnitsReturned, 
        grandTotalRefunded.toFixed(2), 
        grandNetProfit.toFixed(2), 
        ""
    ].join(","));

    // Prepare CSV with BOM for proper Excel rendering of currency symbols
    const csvContent = "\uFEFF" + [headers.join(","), ...rows].join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `Inventory_Hierarchy_Report_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast("Designed hierarchical report exported.", "SUCCESS");
  };

  const getDaysUntilExpiry = (dateString?: string) => {
      if (!dateString) return null;
      const [year, month, day] = dateString.split('-').map(Number);
      const expiry = new Date(year, month - 1, day);
      const diffTime = expiry.getTime() - new Date().setHours(0,0,0,0);
      return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const getExpiryStatus = (days: number | null) => {
      if (days === null) return 'NONE';
      if (days < 0) return 'EXPIRED';
      if (days <= 30) return 'WARNING';
      return 'OK';
  };

  const handleOpenModal = (product?: Product) => {
    if (product) { setEditingProduct(product); setFormData(product); }
    else { setEditingProduct(null); setFormData({ name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false }); }
    setIsModalOpen(true);
  };

  const handleOpenAdjModal = (product: Product) => { setSelectedProductForAdj(product); setAdjType('ADD'); setAdjQuantity(0); setAdjReason('Stock Count Correction'); setAdjNotes(''); setIsAdjModalOpen(true); };

  const handleSave = () => {
    if (!formData.name || !formData.price || !formData.category) { showToast("Name, Category, and Price are required.", 'ERROR'); return; }
    if (editingProduct) {
      if (formData.price !== editingProduct.price) onLogPriceChange({ id: `ph-${Date.now()}-p`, productId: editingProduct.id, type: 'PRICE', oldValue: editingProduct.price, newValue: formData.price || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      if (formData.cost !== editingProduct.cost) onLogPriceChange({ id: `ph-${Date.now()}-c`, productId: editingProduct.id, type: 'COST', oldValue: editingProduct.cost, newValue: formData.cost || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      setProducts(prev => prev.map(p => p.id === editingProduct.id ? { ...p, ...formData } as Product : p));
      showToast("Product updated.", 'SUCCESS');
    } else {
      setProducts(prev => [...prev, { id: `p-${Date.now()}`, ...formData as Product }]);
      showToast("Product added.", 'SUCCESS');
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => { if (window.confirm('Delete this product?')) { setProducts(prev => prev.filter(p => p.id !== id)); showToast("Product deleted.", 'INFO'); } };

  const handleSubmitAdjustment = () => {
      if (!selectedProductForAdj) return;
      let newStock = selectedProductForAdj.stock;
      if (adjType === 'ADD') newStock = parseFloat((selectedProductForAdj.stock + adjQuantity).toFixed(3));
      if (adjType === 'REMOVE') newStock = parseFloat((selectedProductForAdj.stock - adjQuantity).toFixed(3));
      if (adjType === 'SET') newStock = adjQuantity;
      if (newStock < 0) { showToast("Stock cannot be negative.", 'ERROR'); return; }
      onAdjustStock({ id: `adj-${Date.now()}`, productId: selectedProductForAdj.id, productName: selectedProductForAdj.name, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now(), type: adjType, quantity: adjQuantity, previousStock: selectedProductForAdj.stock, newStock, reason: adjReason, notes: adjNotes });
      setIsAdjModalOpen(false);
  };

  const handleRestockCheck = async () => { setIsLoadingAi(true); const suggestions = await suggestRestock(products); setAiSuggestions(suggestions); setIsLoadingAi(false); showToast("AI analysis complete.", 'SUCCESS'); };

  const handleSort = (field: SortField) => { if (sortField === field) setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc'); else { setSortField(field); setSortDirection('asc'); } };

  const HeaderCell = ({ field, label, align = 'left' }: { field: SortField, label: string, align?: 'left' | 'center' | 'right' }) => (
      <th className={`p-4 text-xs font-semibold text-slate-600 dark:text-slate-300 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700 transition select-none text-${align}`} onClick={() => handleSort(field)}>
          <div className={`flex items-center ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
              {label}{sortField === field ? (sortDirection === 'asc' ? <ArrowUp size={14} className="ml-1 text-blue-500" /> : <ArrowDown size={14} className="ml-1 text-blue-500" />) : <ChevronsUpDown size={14} className="ml-1 text-slate-400" />}
          </div>
      </th>
  );

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-full mr-4"><Package size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Total Items</p><p className="text-lg font-bold text-slate-800 dark:text-white">{formatNumber(products.reduce((acc, p) => acc + p.stock, 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-full mr-4"><DollarSign size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Inventory Value</p><p className="text-lg font-bold text-slate-800 dark:text-white">{symbol}{formatCurrency(products.reduce((acc, p) => acc + (p.price * p.stock), 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 rounded-full mr-4"><AlertTriangle size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Low Stock</p><p className="text-lg font-bold text-slate-800 dark:text-white">{products.filter(p => p.stock <= p.minStockLevel).length}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 rounded-full mr-4"><History size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Expired</p><p className="text-lg font-bold text-slate-800 dark:text-white">{products.filter(p => (getDaysUntilExpiry(p.stockExpiryDate) || 0) < 0).length}</p></div>
          </div>
      </div>

      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
          <div className="flex flex-col md:flex-row gap-4 w-full xl:w-auto">
              <div className="relative w-full md:w-64"><Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"/></div>
              <div className="flex gap-2">
                  <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 outline-none">
                      {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  <select value={filterStockStatus} onChange={(e) => setFilterStockStatus(e.target.value as any)} className="pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 outline-none">
                      <option value="ALL">All Stock</option><option value="LOW">Low</option><option value="OUT">Out</option><option value="IN">In</option>
                  </select>
              </div>
          </div>
          <div className="flex flex-wrap gap-2 w-full xl:w-auto justify-end">
              <button onClick={exportToExcel} className="px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-medium hover:bg-emerald-700 transition flex items-center shadow-sm">
                  <FileSpreadsheet size={16} className="mr-2"/> Export Designed Hierarchy CSV
              </button>
              <button onClick={handleRestockCheck} disabled={isLoadingAi} className="px-4 py-2 bg-purple-600 text-white rounded-lg text-sm font-medium hover:bg-purple-700 transition flex items-center shadow-sm">
                  <Wand2 size={16} className={`mr-2 ${isLoadingAi ? 'animate-spin' : ''}`}/> AI Audit
              </button>
              <button onClick={() => handleOpenModal()} className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition flex items-center shadow-sm">
                  <Plus size={16} className="mr-2"/> Add Product
              </button>
          </div>
      </div>

      {aiSuggestions.length > 0 && (
          <div className="bg-gradient-to-r from-purple-50 to-indigo-50 dark:from-purple-900/20 dark:to-indigo-900/20 border border-purple-100 dark:border-purple-800 rounded-xl p-4 flex items-start gap-4">
              <div className="p-2 bg-purple-100 dark:bg-purple-900/50 rounded-full text-purple-600 dark:text-purple-300 shrink-0"><Wand2 size={20}/></div>
              <div className="flex-1"><h4 className="font-bold text-purple-900 dark:text-purple-300 mb-2 text-sm">AI Analysis</h4><div className="flex flex-wrap gap-2">{aiSuggestions.map((s, i) => (<div key={i} className="bg-white dark:bg-slate-800 px-3 py-1 rounded-lg shadow-sm border border-purple-100 dark:border-slate-700 text-xs flex items-center"><span className="font-bold mr-2">{s.productName}:</span><span>{s.suggestedAction}</span></div>))}</div></div>
              <button onClick={() => setAiSuggestions([])}><X size={18} className="text-slate-400"/></button>
          </div>
      )}

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
          <div className="overflow-x-auto">
              <table className="w-full text-left">
                  <thead className="bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-700">
                      <tr>
                          <HeaderCell field="name" label="Product" />
                          <HeaderCell field="sku" label="SKU" />
                          <HeaderCell field="category" label="Category" />
                          <HeaderCell field="stockExpiryDate" label="Expiry" />
                          <HeaderCell field="price" label="Price" align="right" />
                          <HeaderCell field="margin" label="Margin" align="right" />
                          <HeaderCell field="stock" label="Stock" align="center" />
                          <th className="p-4 text-xs font-semibold text-right">Actions</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                      {processedProducts.map(product => {
                          const days = getDaysUntilExpiry(product.stockExpiryDate);
                          const status = getExpiryStatus(days);
                          const margin = product.price > 0 ? ((product.price - product.cost) / product.price * 100) : 0;
                          return (
                              <tr key={product.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition group">
                                  <td className="p-4"><div className="flex items-center"><div className="w-10 h-10 rounded bg-slate-100 dark:bg-slate-700 mr-3 overflow-hidden flex items-center justify-center shrink-0"><img src={product.imageUrl || "https://placehold.co/40"} alt="" className="w-full h-full object-cover"/></div><div className="text-sm font-medium">{product.name}</div></div></td>
                                  <td className="p-4 text-xs font-mono text-slate-500">{product.sku}</td>
                                  <td className="p-4"><span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300">{product.category}</span></td>
                                  <td className="p-4 text-xs">{product.stockExpiryDate ? <div className={`${status === 'EXPIRED' ? 'text-red-500 font-bold' : status === 'WARNING' ? 'text-orange-500' : 'text-slate-500'}`}>{product.stockExpiryDate}</div> : '-'}</td>
                                  <td className="p-4 text-right font-medium">{symbol}{product.price.toFixed(2)}</td>
                                  <td className="p-4 text-right"><span className={`text-xs font-bold ${margin < 15 ? 'text-red-500' : 'text-green-600'}`}>{margin.toFixed(1)}%</span></td>
                                  <td className="p-4 text-center font-bold">{product.stock} <span className="text-[10px] text-slate-400 font-normal">{product.unit}</span></td>
                                  <td className="p-4 text-right"><div className="flex items-center justify-end space-x-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => handleOpenAdjModal(product)} className="p-1.5 text-blue-600 rounded" title="Adjust Stock"><Scale size={16}/></button><button onClick={() => handleOpenModal(product)} className="p-1.5 text-slate-600 rounded" title="Edit"><Edit2 size={16}/></button><button onClick={() => handleDelete(product.id)} className="p-1.5 text-red-500 rounded" title="Delete"><Trash2 size={16}/></button></div></td>
                              </tr>
                          );
                      })}
                  </tbody>
              </table>
          </div>
      </div>

      {isModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col">
                  <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-xl"><h3 className="font-bold">{editingProduct ? 'Edit Product' : 'Add Product'}</h3><button onClick={() => setIsModalOpen(false)}><X size={20}/></button></div>
                  <div className="flex-1 overflow-y-auto p-6 space-y-4">
                      <div className="grid grid-cols-2 gap-4">
                          <div className="col-span-2"><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Name</label><input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">SKU</label><input type="text" value={formData.sku} onChange={e => setFormData({...formData, sku: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Category</label><input type="text" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Cost Price</label><input type="number" value={formData.cost} onChange={e => setFormData({...formData, cost: parseFloat(e.target.value)})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Selling Price</label><input type="number" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                      </div>
                      <div className="flex items-center gap-2"><input type="checkbox" id="decimal" checked={formData.allowDecimal} onChange={e => setFormData({...formData, allowDecimal: e.target.checked})} className="rounded text-blue-600"/><label htmlFor="decimal" className="text-sm font-medium">Allow Decimal Quantities</label></div>
                  </div>
                  <div className="p-4 border-t flex justify-end gap-2 bg-slate-50 dark:bg-slate-800/50 rounded-b-xl"><button onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm text-slate-500">Cancel</button><button onClick={handleSave} className="px-6 py-2 bg-blue-600 text-white rounded-lg font-bold">Save</button></div>
              </div>
          </div>
      )}

      {isAdjModalOpen && selectedProductForAdj && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-sm:w-full max-w-sm p-6">
                  <h3 className="text-lg font-bold mb-4">Adjust Stock: {selectedProductForAdj.name}</h3>
                  <div className="space-y-4">
                      <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-lg">
                          {['ADD', 'REMOVE', 'SET'].map(type => (
                              <button key={type} onClick={() => setAdjType(type as AdjustmentType)} className={`flex-1 py-1.5 text-xs font-bold rounded ${adjType === type ? 'bg-white dark:bg-slate-600 shadow text-blue-600' : 'text-slate-500'}`}>{type}</button>
                          ))}
                      </div>
                      <input type="number" step={selectedProductForAdj.allowDecimal ? "0.001" : "1"} value={adjQuantity} onChange={e => setAdjQuantity(parseFloat(e.target.value) || 0)} className="w-full p-3 text-center text-2xl font-bold border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" autoFocus/>
                      <select value={adjReason} onChange={e => setAdjReason(e.target.value)} className="w-full p-2 border rounded text-sm bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white"><option>Stock Count Correction</option><option>Damage</option><option>Received Shipment</option></select>
                  </div>
                  <div className="mt-6 flex justify-end gap-2"><button onClick={() => setIsAdjModalOpen(false)} className="px-4 py-2 text-slate-500 text-sm">Cancel</button><button onClick={handleSubmitAdjustment} className="px-6 py-2 bg-blue-600 text-white font-bold rounded-lg text-sm">Confirm</button></div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useMemo } from 'react';
import { Product, StockAdjustment, AdjustmentType, User, ReturnTransaction, Customer, Sale, PriceHistory } from '../types';
import { suggestRestock } from '../services/geminiService';
import { Plus, Edit2, Trash2, Search, Wand2, History, X, FileSpreadsheet, Package, DollarSign, AlertTriangle, Scale, ArrowUp, ArrowDown, ChevronsUpDown } from 'lucide-react';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  stockAdjustments: StockAdjustment[];
  onAdjustStock: (adjustment: StockAdjustment) => void;
  onBulkAdjustStock: (adjustments: StockAdjustment[]) => void;
  currentUser: User;
  currency: string;
  showToast: (message: string, type: 'SUCCESS' | 'ERROR' | 'INFO') => void;
  returns: ReturnTransaction[];
  customers: Customer[];
  sales: Sale[];
  priceHistory: PriceHistory[];
  onLogPriceChange: (log: PriceHistory) => void;
}

type SortField = 'name' | 'sku' | 'category' | 'price' | 'stock' | 'stockExpiryDate' | 'cost' | 'margin';
type SortDirection = 'asc' | 'desc';

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, stockAdjustments, onAdjustStock, onBulkAdjustStock, currentUser, currency, showToast, returns, customers, sales, priceHistory, onLogPriceChange }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('ALL');
  const [filterStockStatus, setFilterStockStatus] = useState<'ALL' | 'LOW' | 'OUT' | 'IN'>('ALL');
  const [filterExpiry, setFilterExpiry] = useState<'ALL' | 'EXPIRED' | 'SOON' | 'VALID'>('ALL');
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');
  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [isLoadingAi, setIsLoadingAi] = useState(false);
  const [isAdjModalOpen, setIsAdjModalOpen] = useState(false);
  const [selectedProductForAdj, setSelectedProductForAdj] = useState<Product | null>(null);
  const [adjType, setAdjType] = useState<AdjustmentType>('ADD');
  const [adjQuantity, setAdjQuantity] = useState(0);
  const [adjReason, setAdjReason] = useState('Stock Count Correction');
  const [adjNotes, setAdjNotes] = useState('');

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false
  });

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  };

  const symbol = getCurrencySymbol(currency);
  const formatCurrency = (val: number) => val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const formatNumber = (val: number) => val.toLocaleString('en-US', { maximumFractionDigits: 3 });

  const categories = useMemo(() => {
      const cats = new Set(products.map(p => p.category).filter(Boolean));
      return ['ALL', ...Array.from(cats).sort()];
  }, [products]);

  const processedProducts = useMemo(() => {
      let filtered = products.filter(p => 
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        p.sku.toLowerCase().includes(searchTerm.toLowerCase())
      );
      if (filterCategory !== 'ALL') filtered = filtered.filter(p => p.category === filterCategory);
      if (filterStockStatus !== 'ALL') {
          if (filterStockStatus === 'OUT') filtered = filtered.filter(p => p.stock === 0);
          if (filterStockStatus === 'LOW') filtered = filtered.filter(p => p.stock > 0 && p.stock <= p.minStockLevel);
          if (filterStockStatus === 'IN') filtered = filtered.filter(p => p.stock > p.minStockLevel);
      }
      if (filterExpiry !== 'ALL') {
          filtered = filtered.filter(p => {
              const days = getDaysUntilExpiry(p.stockExpiryDate);
              if (filterExpiry === 'EXPIRED') return days !== null && days < 0;
              if (filterExpiry === 'SOON') return days !== null && days >= 0 && days <= 30;
              if (filterExpiry === 'VALID') return days === null || days > 30;
              return true;
          });
      }
      return filtered.sort((a, b) => {
          let valA: any = a[sortField];
          let valB: any = b[sortField];
          if (sortField === 'margin') {
              valA = a.price > 0 ? ((a.price - a.cost) / a.price) : -999;
              valB = b.price > 0 ? ((b.price - b.cost) / b.price) : -999;
          }
          if (typeof valA === 'string') return sortDirection === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
          return sortDirection === 'asc' ? (valA < valB ? -1 : 1) : (valB < valA ? -1 : 1);
      });
  }, [products, searchTerm, filterCategory, filterStockStatus, filterExpiry, sortField, sortDirection]);

  // High-Fidelity Designed Export for Excel (.xls via HTML trick)
  const exportToExcel = () => {
    const headers = [
      "Product Name", "SKU", "Description", "Cost Price", "Selling Price", "Margin %", 
      "Stock", "Status", "Asset Value", "Retail Value", "Units Sold", "Total Revenue", 
      "Units Returned", "Total Refunded", "Net Profit", "Expiry Date"
    ];

    const groupedProducts: Record<string, Product[]> = {};
    processedProducts.forEach(p => {
        const cat = p.category || 'Uncategorized';
        if (!groupedProducts[cat]) groupedProducts[cat] = [];
        groupedProducts[cat].push(p);
    });

    let grandStock = 0, grandAsset = 0, grandRetail = 0, grandSold = 0, grandRev = 0, grandRet = 0, grandRef = 0, grandProf = 0;

    // Build HTML Table with styling to force Excel layout
    let html = `
      <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
      <head>
        <meta http-equiv="content-type" content="application/vnd.ms-excel; charset=UTF-8">
        <style>
          table { border-collapse: collapse; width: 100%; }
          th { background-color: #f1f5f9; border: 1px solid #cbd5e1; font-weight: bold; padding: 8px; text-align: left; }
          td { border: 1px solid #e2e8f0; padding: 6px; font-size: 10pt; }
          .cat-row { background-color: #dbeafe; font-weight: bold; }
          .footer-row { background-color: #f8fafc; font-weight: bold; }
          .num { text-align: right; mso-number-format:"\\#,##0.00"; }
          .pct { text-align: right; mso-number-format:"0.00%"; }
          .qty { text-align: center; }
        </style>
      </head>
      <body>
        <table>
          <thead>
            <tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr>
          </thead>
          <tbody>
    `;

    Object.keys(groupedProducts).sort().forEach(cat => {
        html += `<tr class="cat-row"><td colspan="16">${cat.toUpperCase()}</td></tr>`;

        groupedProducts[cat].forEach(p => {
            const margin = p.price > 0 ? (p.price - p.cost) / p.price : 0;
            const assetValue = p.stock * p.cost;
            const retailValue = p.stock * p.price;

            const pSales = sales.flatMap(s => s.items.filter(i => i.productId === p.id));
            const uSold = pSales.reduce((sum, i) => sum + i.quantity, 0);
            const tRev = pSales.reduce((sum, i) => sum + (i.priceAtSale * i.quantity), 0);
            const pReturns = returns.flatMap(r => r.items.filter(ri => ri.productId === p.id));
            const uRet = pReturns.reduce((sum, i) => sum + i.quantity, 0);
            const tRef = pReturns.reduce((sum, i) => sum + i.refundAmount, 0);

            const cogs = pSales.reduce((sum, i) => sum + (i.costAtSale * i.quantity), 0);
            const refundCogs = returns.reduce((sum, r) => {
                const s = sales.find(s => s.id === r.originalSaleId);
                const ri = r.items.find(item => item.productId === p.id);
                const si = s?.items.find(item => item.productId === p.id);
                return sum + (ri && si ? (si.costAtSale * ri.quantity) : 0);
            }, 0);

            const netProf = (tRev - tRef) - (cogs - refundCogs);
            const status = p.stock === 0 ? "Out of Stock" : p.stock <= p.minStockLevel ? "Low Stock" : "In Stock";

            grandStock += p.stock; grandAsset += assetValue; grandRetail += retailValue; grandSold += uSold; grandRev += tRev; grandRet += uRet; grandRef += tRef; grandProf += netProf;

            html += `
              <tr>
                <td>${p.name}</td>
                <td>${p.sku}</td>
                <td>${p.description || ''}</td>
                <td class="num">${p.cost.toFixed(2)}</td>
                <td class="num">${p.price.toFixed(2)}</td>
                <td class="pct">${margin.toFixed(4)}</td>
                <td class="qty">${p.stock}</td>
                <td>${status}</td>
                <td class="num">${assetValue.toFixed(2)}</td>
                <td class="num">${retailValue.toFixed(2)}</td>
                <td class="qty">${uSold}</td>
                <td class="num">${tRev.toFixed(2)}</td>
                <td class="qty">${uRet}</td>
                <td class="num">${tRef.toFixed(2)}</td>
                <td class="num">${netProf.toFixed(2)}</td>
                <td>${p.stockExpiryDate || 'N/A'}</td>
              </tr>
            `;
        });
    });

    html += `
          </tbody>
          <tfoot>
            <tr class="footer-row">
              <td colspan="5"></td>
              <td align="right">GRAND TOTALS</td>
              <td class="qty">${grandStock}</td>
              <td></td>
              <td class="num">${grandAsset.toFixed(2)}</td>
              <td class="num">${grandRetail.toFixed(2)}</td>
              <td class="qty">${grandSold}</td>
              <td class="num">${grandRev.toFixed(2)}</td>
              <td class="qty">${grandRet}</td>
              <td class="num">${grandRef.toFixed(2)}</td>
              <td class="num" style="color: #16a34a;">${grandProf.toFixed(2)}</td>
              <td></td>
            </tr>
          </tfoot>
        </table>
      </body>
      </html>
    `;

    const blob = new Blob([html], { type: 'application/vnd.ms-excel' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `Nexus_Inventory_Design_${new Date().toISOString().split('T')[0]}.xls`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast("Designed Excel (.xls) file exported.", "SUCCESS");
  };

  const getDaysUntilExpiry = (dateString?: string) => {
      if (!dateString) return null;
      const [year, month, day] = dateString.split('-').map(Number);
      const expiry = new Date(year, month - 1, day);
      const diffTime = expiry.getTime() - new Date().setHours(0,0,0,0);
      return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const getExpiryStatus = (days: number | null) => {
      if (days === null) return 'NONE';
      if (days < 0) return 'EXPIRED';
      if (days <= 30) return 'WARNING';
      return 'OK';
  };

  const handleOpenModal = (product?: Product) => {
    if (product) { setEditingProduct(product); setFormData(product); }
    else { setEditingProduct(null); setFormData({ name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false }); }
    setIsModalOpen(true);
  };

  const handleOpenAdjModal = (product: Product) => { setSelectedProductForAdj(product); setAdjType('ADD'); setAdjQuantity(0); setAdjReason('Stock Count Correction'); setAdjNotes(''); setIsAdjModalOpen(true); };

  const handleSave = () => {
    if (!formData.name || !formData.price || !formData.category) { showToast("Name, Category, and Price are required.", 'ERROR'); return; }
    if (editingProduct) {
      if (formData.price !== editingProduct.price) onLogPriceChange({ id: `ph-${Date.now()}-p`, productId: editingProduct.id, type: 'PRICE', oldValue: editingProduct.price, newValue: formData.price || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      if (formData.cost !== editingProduct.cost) onLogPriceChange({ id: `ph-${Date.now()}-c`, productId: editingProduct.id, type: 'COST', oldValue: editingProduct.cost, newValue: formData.cost || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      setProducts(prev => prev.map(p => p.id === editingProduct.id ? { ...p, ...formData } as Product : p));
      showToast("Product updated.", 'SUCCESS');
    } else {
      setProducts(prev => [...prev, { id: `p-${Date.now()}`, ...formData as Product }]);
      showToast("Product added.", 'SUCCESS');
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => { if (window.confirm('Delete this product?')) { setProducts(prev => prev.filter(p => p.id !== id)); showToast("Product deleted.", 'INFO'); } };

  const handleSubmitAdjustment = () => {
      if (!selectedProductForAdj) return;
      let newStock = selectedProductForAdj.stock;
      if (adjType === 'ADD') newStock = parseFloat((selectedProductForAdj.stock + adjQuantity).toFixed(3));
      if (adjType === 'REMOVE') newStock = parseFloat((selectedProductForAdj.stock - adjQuantity).toFixed(3));
      if (adjType === 'SET') newStock = adjQuantity;
      if (newStock < 0) { showToast("Stock cannot be negative.", 'ERROR'); return; }
      onAdjustStock({ id: `adj-${Date.now()}`, productId: selectedProductForAdj.id, productName: selectedProductForAdj.name, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now(), type: adjType, quantity: adjQuantity, previousStock: selectedProductForAdj.stock, newStock, reason: adjReason, notes: adjNotes });
      setIsAdjModalOpen(false);
  };

  const handleRestockCheck = async () => { setIsLoadingAi(true); const suggestions = await suggestRestock(products); setAiSuggestions(suggestions); setIsLoadingAi(false); showToast("AI analysis complete.", 'SUCCESS'); };

  const handleSort = (field: SortField) => { if (sortField === field) setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc'); else { setSortField(field); setSortDirection('asc'); } };

  const HeaderCell = ({ field, label, align = 'left' }: { field: SortField, label: string, align?: 'left' | 'center' | 'right' }) => (
      <th className={`p-4 text-xs font-semibold text-slate-600 dark:text-slate-300 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700 transition select-none text-${align}`} onClick={() => handleSort(field)}>
          <div className={`flex items-center ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
              {label}{sortField === field ? (sortDirection === 'asc' ? <ArrowUp size={14} className="ml-1 text-blue-500" /> : <ArrowDown size={14} className="ml-1 text-blue-500" />) : <ChevronsUpDown size={14} className="ml-1 text-slate-400" />}
          </div>
      </th>
  );

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-full mr-4"><Package size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Total Items</p><p className="text-lg font-bold text-slate-800 dark:text-white">{formatNumber(products.reduce((acc, p) => acc + p.stock, 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 rounded-full mr-4"><DollarSign size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Inventory Value</p><p className="text-lg font-bold text-slate-800 dark:text-white">{symbol}{formatCurrency(products.reduce((acc, p) => acc + (p.price * p.stock), 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 rounded-full mr-4"><AlertTriangle size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Low Stock</p><p className="text-lg font-bold text-slate-800 dark:text-white">{products.filter(p => p.stock <= p.minStockLevel).length}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center">
              <div className="p-3 bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 rounded-full mr-4"><History size={20}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase">Expired</p><p className="text-lg font-bold text-slate-800 dark:text-white">{products.filter(p => (getDaysUntilExpiry(p.stockExpiryDate) || 0) < 0).length}</p></div>
          </div>
      </div>

      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
          <div className="flex flex-col md:flex-row gap-4 w-full xl:w-auto">
              <div className="relative w-full md:w-64"><Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"/></div>
              <div className="flex gap-2">
                  <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 outline-none">
                      {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  <select value={filterStockStatus} onChange={(e) => setFilterStockStatus(e.target.value as any)} className="pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-sm font-medium text-slate-700 dark:text-slate-200 outline-none">
                      <option value="ALL">All Stock</option><option value="LOW">Low</option><option value="OUT">Out</option><option value="IN">In</option>
                  </select>
              </div>
          </div>
          <div className="flex flex-wrap gap-2 w-full xl:w-auto justify-end">
              <button onClick={exportToExcel} className="px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-medium hover:bg-emerald-700 transition flex items-center shadow-sm">
                  <FileSpreadsheet size={16} className="mr-2"/> Export Designed Excel
              </button>
              <button onClick={handleRestockCheck} disabled={isLoadingAi} className="px-4 py-2 bg-purple-600 text-white rounded-lg text-sm font-medium hover:bg-purple-700 transition flex items-center shadow-sm">
                  <Wand2 size={16} className={`mr-2 ${isLoadingAi ? 'animate-spin' : ''}`}/> AI Audit
              </button>
              <button onClick={() => handleOpenModal()} className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition flex items-center shadow-sm">
                  <Plus size={16} className="mr-2"/> Add Product
              </button>
          </div>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
          <div className="overflow-x-auto">
              <table className="w-full text-left">
                  <thead className="bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-700">
                      <tr>
                          <HeaderCell field="name" label="Product" />
                          <HeaderCell field="sku" label="SKU" />
                          <HeaderCell field="category" label="Category" />
                          <HeaderCell field="stockExpiryDate" label="Expiry" />
                          <HeaderCell field="price" label="Price" align="right" />
                          <HeaderCell field="margin" label="Margin" align="right" />
                          <HeaderCell field="stock" label="Stock" align="center" />
                          <th className="p-4 text-xs font-semibold text-right">Actions</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                      {processedProducts.map(product => {
                          const days = getDaysUntilExpiry(product.stockExpiryDate);
                          const status = getExpiryStatus(days);
                          const margin = product.price > 0 ? ((product.price - product.cost) / product.price * 100) : 0;
                          return (
                              <tr key={product.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition group">
                                  <td className="p-4"><div className="flex items-center"><div className="w-10 h-10 rounded bg-slate-100 dark:bg-slate-700 mr-3 overflow-hidden flex items-center justify-center shrink-0"><img src={product.imageUrl || "https://placehold.co/40"} alt="" className="w-full h-full object-cover"/></div><div className="text-sm font-medium">{product.name}</div></div></td>
                                  <td className="p-4 text-xs font-mono text-slate-500">{product.sku}</td>
                                  <td className="p-4"><span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300">{product.category}</span></td>
                                  <td className="p-4 text-xs">{product.stockExpiryDate ? <div className={`${status === 'EXPIRED' ? 'text-red-500 font-bold' : status === 'WARNING' ? 'text-orange-500' : 'text-slate-500'}`}>{product.stockExpiryDate}</div> : '-'}</td>
                                  <td className="p-4 text-right font-medium">{symbol}{product.price.toFixed(2)}</td>
                                  <td className="p-4 text-right"><span className={`text-xs font-bold ${margin < 15 ? 'text-red-500' : 'text-green-600'}`}>{margin.toFixed(1)}%</span></td>
                                  <td className="p-4 text-center font-bold">{product.stock} <span className="text-[10px] text-slate-400 font-normal">{product.unit}</span></td>
                                  <td className="p-4 text-right"><div className="flex items-center justify-end space-x-1 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => handleOpenAdjModal(product)} className="p-1.5 text-blue-600 rounded" title="Adjust Stock"><Scale size={16}/></button><button onClick={() => handleOpenModal(product)} className="p-1.5 text-slate-600 rounded" title="Edit"><Edit2 size={16}/></button><button onClick={() => handleDelete(product.id)} className="p-1.5 text-red-500 rounded" title="Delete"><Trash2 size={16}/></button></div></td>
                              </tr>
                          );
                      })}
                  </tbody>
              </table>
          </div>
      </div>

      {isModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] flex flex-col">
                  <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-xl"><h3 className="font-bold">{editingProduct ? 'Edit Product' : 'Add Product'}</h3><button onClick={() => setIsModalOpen(false)}><X size={20}/></button></div>
                  <div className="flex-1 overflow-y-auto p-6 space-y-4">
                      <div className="grid grid-cols-2 gap-4">
                          <div className="col-span-2"><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Name</label><input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">SKU</label><input type="text" value={formData.sku} onChange={e => setFormData({...formData, sku: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Category</label><input type="text" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Cost Price</label><input type="number" value={formData.cost} onChange={e => setFormData({...formData, cost: parseFloat(e.target.value)})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                          <div><label className="block text-xs font-bold uppercase text-slate-400 mb-1">Selling Price</label><input type="number" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} className="w-full p-2 border rounded bg-white dark:bg-slate-700 dark:border-slate-600 dark:text-white" /></div>
                      </div>
                      <div className="flex items-center gap-2"><input type="checkbox" id="decimal" checked={formData.allowDecimal} onChange={e => setFormData({...formData, allowDecimal: e.target.checked})} className="rounded text-blue-600"/><label htmlFor="decimal" className="text-sm font-medium">Allow Decimal Quantities</label></div>
                  </div>
                  <div className="p-4 border-t flex justify-end gap-2 bg-slate-50 dark:bg-slate-800/50 rounded-b-xl"><button onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-sm text-slate-500">Cancel</button><button onClick={handleSave} className="px-6 py-2 bg-blue-600 text-white rounded-lg font-bold">Save</button></div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useMemo } from 'react';
import { Product, StockAdjustment, AdjustmentType, User, ReturnTransaction, Customer, Sale, PriceHistory } from '../types';
import { suggestRestock } from '../services/geminiService';
import { Plus, Edit2, Trash2, Search, Wand2, History as HistoryIcon, X, FileSpreadsheet, Package, DollarSign, AlertTriangle, Scale, ArrowUp, ArrowDown, ChevronsUpDown, List, ArrowRight, TrendingUp, TrendingDown, Clock, User as UserIcon } from 'lucide-react';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  stockAdjustments: StockAdjustment[];
  onAdjustStock: (adjustment: StockAdjustment) => void;
  onBulkAdjustStock: (adjustments: StockAdjustment[]) => void;
  currentUser: User;
  currency: string;
  showToast: (message: string, type: 'SUCCESS' | 'ERROR' | 'INFO') => void;
  returns: ReturnTransaction[];
  customers: Customer[];
  sales: Sale[];
  priceHistory: PriceHistory[];
  onLogPriceChange: (log: PriceHistory) => void;
}

type SortField = 'name' | 'sku' | 'category' | 'price' | 'stock' | 'stockExpiryDate' | 'cost' | 'margin';
type SortDirection = 'asc' | 'desc';

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, stockAdjustments, onAdjustStock, onBulkAdjustStock, currentUser, currency, showToast, returns, customers, sales, priceHistory, onLogPriceChange }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'PRODUCTS' | 'HISTORY'>('PRODUCTS');

  // Filter & Sort States
  const [filterCategory, setFilterCategory] = useState('ALL');
  const [filterStockStatus, setFilterStockStatus] = useState<'ALL' | 'LOW' | 'OUT' | 'IN'>('ALL');
  const [filterExpiry, setFilterExpiry] = useState<'ALL' | 'EXPIRED' | 'SOON' | 'VALID'>('ALL');
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');

  // AI & Adjustment States
  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [isLoadingAi, setIsLoadingAi] = useState(false);
  const [isAdjModalOpen, setIsAdjModalOpen] = useState(false);
  const [selectedProductForAdj, setSelectedProductForAdj] = useState<Product | null>(null);
  const [adjType, setAdjType] = useState<AdjustmentType>('ADD');
  const [adjQuantity, setAdjQuantity] = useState(0);
  const [adjReason, setAdjReason] = useState('Stock Count Correction');
  const [adjNotes, setAdjNotes] = useState('');

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false
  });

  const getCurrencySymbol = (code: string) => {
    switch(code) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  };

  const symbol = getCurrencySymbol(currency);
  const formatCurrency = (val: number) => val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const formatNumber = (val: number) => val.toLocaleString('en-US', { maximumFractionDigits: 3 });

  const categories = useMemo(() => {
      const cats = new Set(products.map(p => p.category).filter(Boolean));
      return ['ALL', ...Array.from(cats).sort()];
  }, [products]);

  const processedProducts = useMemo(() => {
      let filtered = products.filter(p => 
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        p.sku.toLowerCase().includes(searchTerm.toLowerCase())
      );
      if (filterCategory !== 'ALL') filtered = filtered.filter(p => p.category === filterCategory);
      if (filterStockStatus !== 'ALL') {
          if (filterStockStatus === 'OUT') filtered = filtered.filter(p => p.stock === 0);
          if (filterStockStatus === 'LOW') filtered = filtered.filter(p => p.stock > 0 && p.stock <= p.minStockLevel);
          if (filterStockStatus === 'IN') filtered = filtered.filter(p => p.stock > p.minStockLevel);
      }
      return filtered.sort((a, b) => {
          let valA: any = a[sortField];
          let valB: any = b[sortField];
          if (sortField === 'margin') {
              valA = a.price > 0 ? ((a.price - a.cost) / a.price) : -999;
              valB = b.price > 0 ? ((b.price - b.cost) / b.price) : -999;
          }
          if (typeof valA === 'string') return sortDirection === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
          return sortDirection === 'asc' ? (valA < valB ? -1 : 1) : (valB < valA ? -1 : 1);
      });
  }, [products, searchTerm, filterCategory, filterStockStatus, sortField, sortDirection]);

  const filteredHistory = useMemo(() => {
    return priceHistory.filter(h => {
        const product = products.find(p => p.id === h.productId);
        const nameMatch = product?.name.toLowerCase().includes(searchTerm.toLowerCase()) || false;
        const userMatch = h.userName.toLowerCase().includes(searchTerm.toLowerCase());
        return nameMatch || userMatch;
    }).sort((a, b) => b.timestamp - a.timestamp);
  }, [priceHistory, searchTerm, products]);

  const exportToExcel = () => {
    const headers = [
      "Product Name", "SKU", "Description", "Cost Price", "Selling Price", "Margin %", 
      "Stock", "Status", "Asset Value", "Retail Value", "Units Sold", "Total Revenue", 
      "Units Returned", "Total Refunded", "Net Profit", "Expiry Date"
    ];

    const groupedProducts: Record<string, Product[]> = {};
    processedProducts.forEach(p => {
        const cat = p.category || 'Uncategorized';
        if (!groupedProducts[cat]) groupedProducts[cat] = [];
        groupedProducts[cat].push(p);
    });

    let grandStock = 0, grandAsset = 0, grandRetail = 0, grandSold = 0, grandRev = 0, grandRet = 0, grandRef = 0, grandProf = 0;

    let html = `
      <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
      <head>
        <meta http-equiv="content-type" content="application/vnd.ms-excel; charset=UTF-8">
        <style>
          table { border-collapse: collapse; width: 100%; }
          th { background-color: #f1f5f9; border: 1px solid #cbd5e1; font-weight: bold; padding: 8px; text-align: left; }
          td { border: 1px solid #e2e8f0; padding: 6px; font-size: 10pt; }
          .cat-row { background-color: #dbeafe; font-weight: bold; }
          .footer-row { background-color: #f8fafc; font-weight: bold; }
          .num { text-align: right; mso-number-format:"\\#,##0.00"; }
          .pct { text-align: right; mso-number-format:"0.00%"; }
          .qty { text-align: center; }
        </style>
      </head>
      <body>
        <table>
          <thead>
            <tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr>
          </thead>
          <tbody>
    `;

    Object.keys(groupedProducts).sort().forEach(cat => {
        html += `<tr class="cat-row"><td colspan="16">${cat.toUpperCase()}</td></tr>`;
        groupedProducts[cat].forEach(p => {
            const margin = p.price > 0 ? (p.price - p.cost) / p.price : 0;
            const assetValue = p.stock * p.cost;
            const retailValue = p.stock * p.price;
            const pSales = sales.flatMap(s => s.items.filter(i => i.productId === p.id));
            const uSold = pSales.reduce((sum, i) => sum + i.quantity, 0);
            const tRev = pSales.reduce((sum, i) => sum + (i.priceAtSale * i.quantity), 0);
            const pReturns = returns.flatMap(r => r.items.filter(ri => ri.productId === p.id));
            const uRet = pReturns.reduce((sum, i) => sum + i.quantity, 0);
            const tRef = pReturns.reduce((sum, i) => sum + i.refundAmount, 0);
            const cogs = pSales.reduce((sum, i) => sum + (i.costAtSale * i.quantity), 0);
            const refundCogs = returns.reduce((sum, r) => {
                const s = sales.find(s => s.id === r.originalSaleId);
                const ri = r.items.find(item => item.productId === p.id);
                const si = s?.items.find(item => item.productId === p.id);
                return sum + (ri && si ? (si.costAtSale * ri.quantity) : 0);
            }, 0);
            const netProf = (tRev - tRef) - (cogs - refundCogs);
            const status = p.stock === 0 ? "Out of Stock" : p.stock <= p.minStockLevel ? "Low Stock" : "In Stock";

            grandStock += p.stock; grandAsset += assetValue; grandRetail += retailValue; grandSold += uSold; grandRev += tRev; grandRet += uRet; grandRef += tRef; grandProf += netProf;

            html += `
              <tr>
                <td>${p.name}</td><td>${p.sku}</td><td>${p.description || ''}</td>
                <td class="num">${p.cost.toFixed(2)}</td><td class="num">${p.price.toFixed(2)}</td>
                <td class="pct">${margin.toFixed(4)}</td><td class="qty">${p.stock}</td>
                <td>${status}</td><td class="num">${assetValue.toFixed(2)}</td>
                <td class="num">${retailValue.toFixed(2)}</td><td class="qty">${uSold}</td>
                <td class="num">${tRev.toFixed(2)}</td><td class="qty">${uRet}</td>
                <td class="num">${tRef.toFixed(2)}</td><td class="num">${netProf.toFixed(2)}</td>
                <td>${p.stockExpiryDate || 'N/A'}</td>
              </tr>
            `;
        });
    });

    html += `
          </tbody>
          <tfoot>
            <tr class="footer-row">
              <td colspan="5"></td><td align="right">GRAND TOTALS</td>
              <td class="qty">${grandStock}</td><td></td>
              <td class="num">${grandAsset.toFixed(2)}</td><td class="num">${grandRetail.toFixed(2)}</td>
              <td class="qty">${grandSold}</td><td class="num">${grandRev.toFixed(2)}</td>
              <td class="qty">${grandRet}</td><td class="num">${grandRef.toFixed(2)}</td>
              <td class="num" style="color: #16a34a;">${grandProf.toFixed(2)}</td><td></td>
            </tr>
          </tfoot>
        </table>
      </body>
      </html>
    `;

    const blob = new Blob([html], { type: 'application/vnd.ms-excel' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `Inventory_Report_${new Date().toISOString().split('T')[0]}.xls`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast("Designed Excel (.xls) file exported.", "SUCCESS");
  };

  const getDaysUntilExpiry = (dateString?: string) => {
      if (!dateString) return null;
      const [year, month, day] = dateString.split('-').map(Number);
      const expiry = new Date(year, month - 1, day);
      const diffTime = expiry.getTime() - new Date().setHours(0,0,0,0);
      return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const getExpiryStatus = (days: number | null) => {
      if (days === null) return 'NONE';
      if (days < 0) return 'EXPIRED';
      if (days <= 30) return 'WARNING';
      return 'OK';
  };

  const handleOpenModal = (product?: Product) => {
    if (product) { setEditingProduct(product); setFormData(product); }
    else { setEditingProduct(null); setFormData({ name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false }); }
    setIsModalOpen(true);
  };

  const handleOpenAdjModal = (product: Product) => { setSelectedProductForAdj(product); setAdjType('ADD'); setAdjQuantity(0); setAdjReason('Stock Count Correction'); setAdjNotes(''); setIsAdjModalOpen(true); };

  const handleSave = () => {
    if (!formData.name || !formData.price || !formData.category) { showToast("Name, Category, and Price are required.", 'ERROR'); return; }
    if (editingProduct) {
      if (formData.price !== editingProduct.price) onLogPriceChange({ id: `ph-${Date.now()}-p`, productId: editingProduct.id, type: 'PRICE', oldValue: editingProduct.price, newValue: formData.price || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      if (formData.cost !== editingProduct.cost) onLogPriceChange({ id: `ph-${Date.now()}-c`, productId: editingProduct.id, type: 'COST', oldValue: editingProduct.cost, newValue: formData.cost || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      setProducts(prev => prev.map(p => p.id === editingProduct.id ? { ...p, ...formData } as Product : p));
      showToast("Product updated.", 'SUCCESS');
    } else {
      setProducts(prev => [...prev, { id: `p-${Date.now()}`, ...formData as Product }]);
      showToast("Product added.", 'SUCCESS');
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => { if (window.confirm('Delete this product?')) { setProducts(prev => prev.filter(p => p.id !== id)); showToast("Product deleted.", 'INFO'); } };

  const handleSubmitAdjustment = () => {
      if (!selectedProductForAdj) return;
      let newStock = selectedProductForAdj.stock;
      if (adjType === 'ADD') newStock = parseFloat((selectedProductForAdj.stock + adjQuantity).toFixed(3));
      if (adjType === 'REMOVE') newStock = parseFloat((selectedProductForAdj.stock - adjQuantity).toFixed(3));
      if (adjType === 'SET') newStock = adjQuantity;
      if (newStock < 0) { showToast("Stock cannot be negative.", 'ERROR'); return; }
      onAdjustStock({ id: `adj-${Date.now()}`, productId: selectedProductForAdj.id, productName: selectedProductForAdj.name, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now(), type: adjType, quantity: adjQuantity, previousStock: selectedProductForAdj.stock, newStock, reason: adjReason, notes: adjNotes });
      setIsAdjModalOpen(false);
  };

  const handleRestockCheck = async () => { setIsLoadingAi(true); const suggestions = await suggestRestock(products); setAiSuggestions(suggestions); setIsLoadingAi(false); showToast("AI analysis complete.", 'SUCCESS'); };

  const handleSort = (field: SortField) => { if (sortField === field) setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc'); else { setSortField(field); setSortDirection('asc'); } };

  const HeaderCell = ({ field, label, align = 'left' }: { field: SortField, label: string, align?: 'left' | 'center' | 'right' }) => (
      <th className={`p-4 text-xs font-semibold text-slate-600 dark:text-slate-300 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700 transition select-none text-${align}`} onClick={() => handleSort(field)}>
          <div className={`flex items-center ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
              {label}{sortField === field ? (sortDirection === 'asc' ? <ArrowUp size={14} className="ml-1 text-blue-500" /> : <ArrowDown size={14} className="ml-1 text-blue-500" />) : <ChevronsUpDown size={14} className="ml-1 text-slate-400" />}
          </div>
      </th>
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 dark:text-white">Inventory</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm mt-1">Manage products, stock levels, and audit price changes.</p>
        </div>
        <div className="flex space-x-2">
            <div className="bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-lg p-1 flex shadow-sm">
                <button 
                    onClick={() => setViewMode('PRODUCTS')}
                    className={`px-3 py-1.5 rounded-md text-sm font-medium transition flex items-center ${viewMode === 'PRODUCTS' ? 'bg-slate-100 dark:bg-slate-600 text-slate-800 dark:text-white shadow-sm' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-300'}`}
                >
                    <List size={16} className="mr-2" /> Products
                </button>
                <button 
                    onClick={() => setViewMode('HISTORY')}
