                                          <td className="p-4 text-center">
                                              <span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase ${log.type === 'PRICE' ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' : 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400'}`}>
