                              <input type="text" value={formData.sku} onChange={e => setFormData({...formData, sku: e.target.value})} className="w-full p-3 border-2 rounded-xl bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white focus:border-blue-500 outline-none transition-colors" placeholder="W-12345" />
                          </div>
                          <div>
                              <label className="block text-[10px] font-black uppercase text-slate-400 mb-1 tracking-widest">Category</label>
                              <input type="text" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full p-3 border-2 rounded-xl bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white focus:border-blue-500 outline-none transition-colors" placeholder="Electronics" />
                          </div>
