                              <input type="number" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} className="w-full p-3 border-2 rounded-xl bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white focus:border-blue-500 outline-none transition-colors" />
