                                  <td className="p-4 text-right font-medium">{symbol}{product.price.toFixed(2)}</td>
                                  <td className="p-4 text-right"><span className={`text-xs font-bold ${margin < 15 ? 'text-red-500' : 'text-green-600'}`}>{margin.toFixed(1)}%</span></td>
                                  <td className="p-4 text-center font-black">
                                      <button onClick={() => handleOpenAdjModal(product)} className={`px-2 py-1 rounded-lg border transition ${isOut ? 'border-red-200 text-red-500 bg-red-50' : isLow ? 'border-orange-200 text-orange-600 bg-orange-50' : 'border-blue-100 text-blue-700 hover:bg-blue-50'}`}>
                                          {product.stock} <span className="text-[10px] font-normal opacity-50 uppercase">{product.unit}</span>
                                      </button>
                                  </td>
                                  <td className="p-4 text-right">
                                      <div className="flex items-center justify-end space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                          <button onClick={() => handleOpenInsights(product)} className="p-2 text-indigo-600 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg" title="Product Intelligence"><Activity size={16}/></button>
                                          <button onClick={() => handleOpenModal(product)} className="p-2 text-slate-600 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg" title="Edit"><Edit2 size={16}/></button>
                                          <button onClick={() => handleDelete(product.id)} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-lg" title="Delete"><Trash2 size={16}/></button>
                                      </div>
                                  </td>
                              </tr>
                          );
                        })
                      )}
                  </tbody>
              </table>
          </div>
      </div>

      {/* Product Insights Modal (Intelligence Hub) */}
      {selectedProductForInsights && (
        <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col animate-in zoom-in-95 duration-200">
                <div className="p-6 border-b border-slate-100 dark:border-slate-700 flex justify-between items-start bg-slate-50 dark:bg-slate-700/50 rounded-t-2xl">
                    <div className="flex items-center gap-4">
                        <div className="w-16 h-16 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black text-2xl shadow-lg shadow-indigo-500/30">
                            {selectedProductForInsights.name.charAt(0)}
                        </div>
                        <div>
                            <h3 className="text-2xl font-black text-slate-800 dark:text-white leading-tight">{selectedProductForInsights.name}</h3>
                            <p className="text-sm font-bold text-slate-500 uppercase tracking-widest">{selectedProductForInsights.sku} • {selectedProductForInsights.category}</p>
                        </div>
                    </div>
                    <button onClick={() => setSelectedProductForInsights(null)} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full transition-colors"><X size={24}/></button>
                </div>

                <div className="flex border-b border-slate-100 dark:border-slate-700 px-6 bg-white dark:bg-slate-800">
                    {[
                        { id: 'FINANCIAL', label: 'Financial Audit', icon: DollarSign },
                        { id: 'SALES', label: 'Sold Logs', icon: ShoppingCart },
                        { id: 'RETURNS', label: 'Returned Logs', icon: RotateCcw },
                        { id: 'ADJUSTMENTS', label: 'Stock Movements', icon: ClipboardList }
                    ].map(tab => (
                        <button 
                            key={tab.id} 
                            onClick={() => setActiveLogTab(tab.id as LogTab)}
                            className={`py-4 px-6 font-black text-[10px] uppercase tracking-widest border-b-2 transition-all flex items-center gap-2 ${activeLogTab === tab.id ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
                        >
                            <tab.icon size={16}/> {tab.label}
                        </button>
                    ))}
                </div>

                <div className="flex-1 overflow-y-auto p-6 bg-slate-50/30 dark:bg-slate-900/50">
                    {activeLogTab === 'FINANCIAL' && (
                        <div className="space-y-4">
                            <div className="grid grid-cols-3 gap-4 mb-4">
                                <div className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-100 dark:border-slate-700 shadow-sm">
                                    <span className="text-[10px] font-black uppercase text-slate-400 block mb-1">Current Selling Price</span>
                                    <span className="text-xl font-black text-slate-800 dark:text-white">{symbol}{selectedProductForInsights.price.toFixed(2)}</span>
                                </div>
                                <div className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-100 dark:border-slate-700 shadow-sm">
                                    <span className="text-[10px] font-black uppercase text-slate-400 block mb-1">Current Unit Cost</span>
                                    <span className="text-xl font-black text-slate-800 dark:text-white">{symbol}{selectedProductForInsights.cost.toFixed(2)}</span>
                                </div>
                                <div className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-100 dark:border-slate-700 shadow-sm">
                                    <span className="text-[10px] font-black uppercase text-slate-400 block mb-1">Net Margin</span>
                                    <span className="text-xl font-black text-green-600">{((selectedProductForInsights.price - selectedProductForInsights.cost) / selectedProductForInsights.price * 100).toFixed(1)}%</span>
                                </div>
                            </div>
                            <table className="w-full text-left">
                                <thead className="bg-white dark:bg-slate-800 text-[10px] font-black uppercase text-slate-400 border-b dark:border-slate-700">
                                    <tr><th className="p-3">Timestamp</th><th className="p-3">Type</th><th className="p-3 text-right">Old Val</th><th className="p-3 text-right">New Val</th><th className="p-3 text-center">Change</th><th className="p-3">By User</th></tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                    {priceHistory.filter(h => h.productId === selectedProductForInsights.id).sort((a,b) => b.timestamp - a.timestamp).map(log => {
                                        const diff = log.newValue - log.oldValue;
                                        const isUp = diff > 0;
                                        return (
                                            <tr key={log.id} className="text-sm">
                                                <td className="p-3 font-medium text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
