export default Inventory;

import React, { useState, useMemo } from 'react';
import { Product, StockAdjustment, AdjustmentType, User, ReturnTransaction, Customer, Sale, PriceHistory } from '../types';
import { suggestRestock, generateProductDescription } from '../services/geminiService';
import { 
  Plus, Edit2, Trash2, Search, Wand2, X, 
  FileSpreadsheet, Package, DollarSign, AlertTriangle, Scale, 
  ArrowUp, ArrowDown, ChevronsUpDown, TrendingUp, 
  TrendingDown, Clock, User as UserIcon, Sparkles, CheckSquare, 
  Square, Trash, Info, Activity, ShoppingCart, RotateCcw, ClipboardList,
  ArrowRight, History, Upload, Image as ImageIcon, Tags, Layers
} from 'lucide-react';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  stockAdjustments: StockAdjustment[];
  onAdjustStock: (adjustment: StockAdjustment) => void;
  onBulkAdjustStock: (adjustments: StockAdjustment[]) => void;
  currentUser: User;
  currency: string;
  showToast: (message: string, type: 'SUCCESS' | 'ERROR' | 'INFO') => void;
  returns: ReturnTransaction[];
  customers: Customer[];
  sales: Sale[];
  priceHistory: PriceHistory[];
  onLogPriceChange: (log: PriceHistory) => void;
}

type SortField = 'name' | 'sku' | 'category' | 'price' | 'stock' | 'stockExpiryDate' | 'cost' | 'margin';
type SortDirection = 'asc' | 'desc';
type LogTab = 'FINANCIAL' | 'SALES' | 'RETURNS' | 'ADJUSTMENTS';

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, stockAdjustments, onAdjustStock, onBulkAdjustStock, currentUser, currency, showToast, returns, customers, sales, priceHistory, onLogPriceChange }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Selection & Bulk State
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  // Product Insights State
  const [selectedProductForInsights, setSelectedProductForInsights] = useState<Product | null>(null);
  const [activeLogTab, setActiveLogTab] = useState<LogTab>('FINANCIAL');

  // Filter & Sort States
  const [filterCategory, setFilterCategory] = useState('ALL');
  const [filterStockStatus, setFilterStockStatus] = useState<'ALL' | 'LOW' | 'OUT' | 'IN' | 'EXPIRED'>('ALL');
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');

  // AI & Adjustment States
  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [isLoadingAi, setIsLoadingAi] = useState(false);
  const [isGeneratingDescription, setIsGeneratingDescription] = useState(false);
  const [isAdjModalOpen, setIsAdjModalOpen] = useState(false);
  const [selectedProductForAdj, setSelectedProductForAdj] = useState<Product | null>(null);
  const [adjType, setAdjType] = useState<AdjustmentType>('ADD');
  const [adjQuantity, setAdjQuantity] = useState(0);
  const [adjReason, setAdjReason] = useState('Stock Count Correction');
  const [adjNotes, setAdjNotes] = useState('');

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false
  });

  const symbol = useMemo(() => {
    switch(currency) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  }, [currency]);

  const formatCurrency = (val: number) => val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const formatNumber = (val: number) => val.toLocaleString('en-US', { maximumFractionDigits: 3 });

  const categories = useMemo(() => {
      const cats = new Set(products.map(p => p.category).filter(Boolean));
      return ['ALL', ...Array.from(cats).sort()];
  }, [products]);

  const getDaysUntilExpiry = (dateString?: string) => {
    if (!dateString) return null;
    const [year, month, day] = dateString.split('-').map(Number);
    const expiry = new Date(year, month - 1, day);
    const diffTime = expiry.getTime() - new Date().setHours(0,0,0,0);
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const processedProducts = useMemo(() => {
      let filtered = products.filter(p => 
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        p.sku.toLowerCase().includes(searchTerm.toLowerCase())
      );
      if (filterCategory !== 'ALL') filtered = filtered.filter(p => p.category === filterCategory);
      if (filterStockStatus !== 'ALL') {
          if (filterStockStatus === 'OUT') filtered = filtered.filter(p => p.stock === 0);
          if (filterStockStatus === 'LOW') filtered = filtered.filter(p => p.stock > 0 && p.stock <= p.minStockLevel);
          if (filterStockStatus === 'IN') filtered = filtered.filter(p => p.stock > p.minStockLevel);
          if (filterStockStatus === 'EXPIRED') filtered = filtered.filter(p => (getDaysUntilExpiry(p.stockExpiryDate) || 0) < 0);
      }
      return filtered.sort((a, b) => {
          let valA: any = a[sortField];
          let valB: any = b[sortField];
          if (sortField === 'margin') {
              valA = a.price > 0 ? ((a.price - a.cost) / a.price) : -999;
              valB = b.price > 0 ? ((b.price - b.cost) / b.price) : -999;
          }
          if (typeof valA === 'string') return sortDirection === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
          return sortDirection === 'asc' ? (valA < valB ? -1 : 1) : (valB < valA ? -1 : 1);
      });
  }, [products, searchTerm, filterCategory, filterStockStatus, sortField, sortDirection]);

  // Bulk Actions
  const toggleSelectAll = () => {
    if (selectedIds.length === processedProducts.length) setSelectedIds([]);
    else setSelectedIds(processedProducts.map(p => p.id));
  };

  const toggleSelect = (id: string) => {
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleBulkDelete = () => {
    if (!window.confirm(`Are you sure you want to delete ${selectedIds.length} products?`)) return;
    setProducts(prev => prev.filter(p => !selectedIds.includes(p.id)));
    setSelectedIds([]);
    showToast(`${selectedIds.length} products removed.`, 'INFO');
  };

  // Image Upload Handler
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  // AI Description Generator
  const handleGenerateDescription = async () => {
    if (!formData.name || !formData.category) {
        showToast("Enter name and category first.", "INFO");
        return;
    }
    setIsGeneratingDescription(true);
    try {
        const desc = await generateProductDescription(formData.name, formData.category);
        setFormData(prev => ({ ...prev, description: desc }));
        showToast("Description generated with AI.", "SUCCESS");
    } catch (e) {
        showToast("AI Generation failed.", "ERROR");
    } finally {
        setIsGeneratingDescription(false);
    }
  };

  const exportToExcel = () => {
    const headers = [
      "Product Name", "SKU", "Description", "Cost Price", "Selling Price", "Margin %", 
      "Stock", "Status", "Asset Value", "Retail Value", "Units Sold", "Total Revenue", 
      "Units Returned", "Total Refunded", "Net Profit", "Expiry Date"
    ];

    const groupedProducts: Record<string, Product[]> = {};
    processedProducts.forEach(p => {
        const cat = p.category || 'Uncategorized';
        if (!groupedProducts[cat]) groupedProducts[cat] = [];
        groupedProducts[cat].push(p);
    });

    let grandStock = 0, grandAsset = 0, grandRetail = 0, grandSold = 0, grandRev = 0, grandRet = 0, grandRef = 0, grandProf = 0;

    let html = `
      <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
      <head>
        <meta http-equiv="content-type" content="application/vnd.ms-excel; charset=UTF-8">
        <style>
          table { border-collapse: collapse; width: 100%; }
          th { background-color: #f1f5f9; border: 1px solid #cbd5e1; font-weight: bold; padding: 8px; text-align: left; }
          td { border: 1px solid #e2e8f0; padding: 6px; font-size: 10pt; }
          .cat-row { background-color: #dbeafe; font-weight: bold; }
          .footer-row { background-color: #f8fafc; font-weight: bold; }
          .num { text-align: right; mso-number-format:"\\#,##0.00"; }
          .pct { text-align: right; mso-number-format:"0.00%"; }
          .qty { text-align: center; }
        </style>
      </head>
      <body>
        <table>
          <thead>
            <tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr>
          </thead>
          <tbody>
    `;

    Object.keys(groupedProducts).sort().forEach(cat => {
        html += `<tr class="cat-row"><td colspan="16">${cat.toUpperCase()}</td></tr>`;
        groupedProducts[cat].forEach(p => {
            const margin = p.price > 0 ? (p.price - p.cost) / p.price : 0;
            const assetValue = p.stock * p.cost;
            const retailValue = p.stock * p.price;
            const pSales = sales.flatMap(s => s.items.filter(i => i.productId === p.id));
            const uSold = pSales.reduce((sum, i) => sum + i.quantity, 0);
            const tRev = pSales.reduce((sum, i) => sum + (i.priceAtSale * i.quantity), 0);
            const pReturns = returns.flatMap(r => r.items.filter(ri => ri.productId === p.id));
            const uRet = pReturns.reduce((sum, i) => sum + i.quantity, 0);
            const tRef = pReturns.reduce((sum, i) => sum + i.refundAmount, 0);
            const cogs = pSales.reduce((sum, i) => sum + (i.costAtSale * i.quantity), 0);
            const refundCogs = returns.reduce((sum, r) => {
                const s = sales.find(s => s.id === r.originalSaleId);
                const ri = r.items.find(item => item.productId === p.id);
                const si = s?.items.find(item => item.productId === p.id);
                return sum + (ri && si ? (si.costAtSale * ri.quantity) : 0);
            }, 0);
            const netProf = (tRev - tRef) - (cogs - refundCogs);
            const status = p.stock === 0 ? "Out of Stock" : p.stock <= p.minStockLevel ? "Low Stock" : "In Stock";

            grandStock += p.stock; grandAsset += assetValue; grandRetail += retailValue; grandSold += uSold; grandRev += tRev; grandRet += uRet; grandRef += tRef; grandProf += netProf;

            html += `
              <tr>
                <td>${p.name}</td><td>${p.sku}</td><td>${p.description || ''}</td>
                <td class="num">${p.cost.toFixed(2)}</td><td class="num">${p.price.toFixed(2)}</td>
                <td class="pct">${margin.toFixed(4)}</td><td class="qty">${p.stock}</td>
                <td>${status}</td><td class="num">${assetValue.toFixed(2)}</td>
                <td class="num">${retailValue.toFixed(2)}</td><td class="qty">${uSold}</td>
                <td class="num">${tRev.toFixed(2)}</td><td class="qty">${uRet}</td>
                <td class="num">${tRef.toFixed(2)}</td><td class="num">${netProf.toFixed(2)}</td>
                <td>${p.stockExpiryDate || 'N/A'}</td>
              </tr>
            `;
        });
    });

    html += `
          </tbody>
          <tfoot>
            <tr class="footer-row">
              <td colspan="5"></td><td align="right">GRAND TOTALS</td>
              <td class="qty">${grandStock}</td><td></td>
              <td class="num">${grandAsset.toFixed(2)}</td><td class="num">${grandRetail.toFixed(2)}</td>
              <td class="qty">${grandSold}</td><td class="num">${grandRev.toFixed(2)}</td>
              <td class="qty">${grandRet}</td><td class="num">${grandRef.toFixed(2)}</td>
              <td class="num" style="color: #16a34a;">${grandProf.toFixed(2)}</td><td></td>
            </tr>
          </tfoot>
        </table>
      </body>
      </html>
    `;

    const blob = new Blob([html], { type: 'application/vnd.ms-excel' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `Inventory_Report_${new Date().toISOString().split('T')[0]}.xls`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast("Designed Excel (.xls) file exported.", "SUCCESS");
  };

  const handleOpenModal = (product?: Product) => {
    if (product) { setEditingProduct(product); setFormData(product); }
    else { setEditingProduct(null); setFormData({ name: '', sku: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false }); }
    setIsModalOpen(true);
  };

  const handleOpenAdjModal = (product: Product) => { setSelectedProductForAdj(product); setAdjType('ADD'); setAdjQuantity(0); setAdjReason('Stock Count Correction'); setAdjNotes(''); setIsAdjModalOpen(true); };

  const handleOpenInsights = (product: Product) => {
    setSelectedProductForInsights(product);
    setActiveLogTab('FINANCIAL');
  };

  const handleSave = () => {
    if (!formData.name || !formData.price || !formData.category) { showToast("Name, Category, and Price are required.", 'ERROR'); return; }
    if (editingProduct) {
      if (formData.price !== editingProduct.price) onLogPriceChange({ id: `ph-${Date.now()}-p`, productId: editingProduct.id, type: 'PRICE', oldValue: editingProduct.price, newValue: formData.price || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      if (formData.cost !== editingProduct.cost) onLogPriceChange({ id: `ph-${Date.now()}-c`, productId: editingProduct.id, type: 'COST', oldValue: editingProduct.cost, newValue: formData.cost || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      setProducts(prev => prev.map(p => p.id === editingProduct.id ? { ...p, ...formData } as Product : p));
      showToast("Product updated.", 'SUCCESS');
    } else {
      setProducts(prev => [...prev, { id: `p-${Date.now()}`, ...formData as Product }]);
      showToast("Product added.", 'SUCCESS');
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => { if (window.confirm('Delete this product?')) { setProducts(prev => prev.filter(p => p.id !== id)); showToast("Product deleted.", 'INFO'); } };

  const handleSubmitAdjustment = () => {
      if (!selectedProductForAdj) return;
      let newStock = selectedProductForAdj.stock;
      if (adjType === 'ADD') newStock = parseFloat((selectedProductForAdj.stock + adjQuantity).toFixed(3));
      if (adjType === 'REMOVE') newStock = parseFloat((selectedProductForAdj.stock - adjQuantity).toFixed(3));
      if (adjType === 'SET') newStock = adjQuantity;
      if (newStock < 0) { showToast("Stock cannot be negative.", 'ERROR'); return; }
      onAdjustStock({ id: `adj-${Date.now()}`, productId: selectedProductForAdj.id, productName: selectedProductForAdj.name, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now(), type: adjType, quantity: adjQuantity, previousStock: selectedProductForAdj.stock, newStock, reason: adjReason, notes: adjNotes });
      setIsAdjModalOpen(false);
  };

  const handleRestockCheck = async () => { setIsLoadingAi(true); const suggestions = await suggestRestock(products); setAiSuggestions(suggestions); setIsLoadingAi(false); showToast("AI analysis complete.", 'SUCCESS'); };

  const handleSort = (field: SortField) => { if (sortField === field) setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc'); else { setSortField(field); setSortDirection('asc'); } };

  const HeaderCell = ({ field, label, align = 'left' }: { field: SortField, label: string, align?: 'left' | 'center' | 'right' }) => (
      <th className={`p-4 text-xs font-semibold text-slate-600 dark:text-slate-300 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700 transition select-none text-${align}`} onClick={() => handleSort(field)}>
          <div className={`flex items-center ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
              {label}{sortField === field ? (sortDirection === 'asc' ? <ArrowUp size={14} className="ml-1 text-blue-500" /> : <ArrowDown size={14} className="ml-1 text-blue-500" />) : <ChevronsUpDown size={14} className="ml-1 text-slate-400" />}
          </div>
      </th>
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 dark:text-white">Inventory</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm mt-1">Manage items, track health, and audit individual product lifecycles.</p>
        </div>
        <div className="flex space-x-2">
            <button onClick={() => handleOpenModal()} className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-xl flex items-center transition shadow-lg shadow-blue-500/20 font-black tracking-tight">
                <Plus size={18} className="mr-2" /> Add Product
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center group hover:border-blue-500 transition-colors">
              <div className="p-3 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-xl mr-4 group-hover:bg-blue-600 group-hover:text-white transition-all"><Package size={24}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase tracking-wider">Total Units</p><p className="text-2xl font-black text-slate-800 dark:text-white">{formatNumber(products.reduce((acc, p) => acc + p.stock, 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center group hover:border-emerald-500 transition-colors">
              <div className="p-3 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 rounded-xl mr-4 group-hover:bg-emerald-600 group-hover:text-white transition-all"><DollarSign size={24}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase tracking-wider">Asset Value</p><p className="text-2xl font-black text-slate-800 dark:text-white">{symbol}{formatCurrency(products.reduce((acc, p) => acc + (p.cost * p.stock), 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center group hover:border-orange-500 transition-colors">
              <div className="p-3 bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 rounded-xl mr-4 group-hover:bg-orange-600 group-hover:text-white transition-all"><AlertTriangle size={24}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase tracking-wider">Low Stock</p><p className="text-2xl font-black text-slate-800 dark:text-white">{products.filter(p => p.stock <= p.minStockLevel && p.stock > 0).length}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center group hover:border-red-500 transition-colors">
              <div className="p-3 bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 rounded-xl mr-4 group-hover:bg-red-600 group-hover:text-white transition-all"><Clock size={24}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase tracking-wider">Expired / Out</p><p className="text-2xl font-black text-slate-800 dark:text-white">{products.filter(p => p.stock === 0 || (getDaysUntilExpiry(p.stockExpiryDate) || 0) < 0).length}</p></div>
          </div>
      </div>

      {/* Control Bar */}
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
          <div className="flex flex-col md:flex-row gap-4 w-full xl:w-auto items-center">
              <button onClick={toggleSelectAll} className="p-2 rounded-lg bg-slate-50 dark:bg-slate-700 hover:bg-slate-100 dark:hover:bg-slate-600 transition border border-slate-200 dark:border-slate-600">
                  {selectedIds.length === processedProducts.length && processedProducts.length > 0 ? <CheckSquare size={20} className="text-blue-500"/> : <Square size={20} className="text-slate-400"/>}
              </button>
              <div className="relative w-full md:w-64">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={18} />
                <input type="text" placeholder="Search products or SKU..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"/>
              </div>
              <div className="flex gap-2 w-full md:w-auto">
                  <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="flex-1 md:w-32 pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-xs font-bold text-slate-700 dark:text-slate-200 outline-none">
                      {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  <select value={filterStockStatus} onChange={(e) => setFilterStockStatus(e.target.value as any)} className="flex-1 md:w-40 pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-xs font-bold text-slate-700 dark:text-slate-200 outline-none">
                      <option value="ALL">All Stock Health</option>
                      <option value="IN">In Stock (Healthy)</option>
                      <option value="LOW">Low Stock Warning</option>
                      <option value="OUT">Out of Stock</option>
                      <option value="EXPIRED">Expired Items</option>
                  </select>
              </div>
          </div>
          <div className="flex flex-wrap gap-2 w-full xl:w-auto justify-end">
              {selectedIds.length > 0 && (
                <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-lg mr-2">
                    <button onClick={handleBulkDelete} className="px-3 py-1.5 bg-red-600 text-white rounded-md text-xs font-bold hover:bg-red-700 flex items-center shadow-md">
                        <Trash size={14} className="mr-1.5"/> Delete {selectedIds.length}
                    </button>
                    <button onClick={() => setSelectedIds([])} className="p-1.5 ml-1 text-slate-400 hover:text-slate-600"><X size={16}/></button>
                </div>
              )}
              <button onClick={exportToExcel} className="px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-medium hover:bg-emerald-700 transition flex items-center shadow-sm">
                  <FileSpreadsheet size={16} className="mr-2"/> Excel Report
              </button>
              <button onClick={handleRestockCheck} disabled={isLoadingAi} className="px-4 py-2 bg-purple-600 text-white rounded-lg text-sm font-medium hover:bg-purple-700 transition flex items-center shadow-sm">
                  <Wand2 size={16} className={`mr-2 ${isLoadingAi ? 'animate-spin' : ''}`}/> AI Audit
              </button>
          </div>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
          <div className="overflow-x-auto">
              <table className="w-full text-left">
                  <thead className="bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-700">
                      <tr>
                          <th className="p-4 w-4"></th>
                          <HeaderCell field="name" label="Product" />
                          <HeaderCell field="sku" label="SKU" />
                          <HeaderCell field="category" label="Category" />
                          <HeaderCell field="price" label="Price" align="right" />
                          <HeaderCell field="margin" label="Margin" align="right" />
                          <HeaderCell field="stock" label="Stock Level" align="center" />
                          <th className="p-4 text-xs font-semibold text-right">Actions</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                      {processedProducts.length === 0 ? (
                        <tr><td colSpan={8} className="p-12 text-center text-slate-400 italic">No products found.</td></tr>
                      ) : (
                        processedProducts.map(product => {
                          const margin = product.price > 0 ? ((product.price - product.cost) / product.price * 100) : 0;
                          const isLow = product.stock <= product.minStockLevel && product.stock > 0;
                          const isOut = product.stock === 0;
                          const daysLeft = getDaysUntilExpiry(product.stockExpiryDate);
                          const isExpired = daysLeft !== null && daysLeft < 0;

                          return (
                              <tr key={product.id} className={`hover:bg-slate-50 dark:hover:bg-slate-700/50 transition group ${selectedIds.includes(product.id) ? 'bg-blue-50/50 dark:bg-blue-900/10' : ''}`}>
                                  <td className="p-4">
                                      <button onClick={() => toggleSelect(product.id)} className="text-slate-400 hover:text-blue-500 transition">
                                          {selectedIds.includes(product.id) ? <CheckSquare size={18} className="text-blue-500" /> : <Square size={18} />}
                                      </button>
                                  </td>
                                  <td className="p-4">
                                      <div className="flex items-center">
                                          <div className="w-10 h-10 rounded bg-slate-100 dark:bg-slate-700 mr-3 overflow-hidden flex items-center justify-center shrink-0 border dark:border-slate-600">
                                              <img src={product.imageUrl || "https://placehold.co/40"} alt="" className="w-full h-full object-cover"/>
                                          </div>
                                          <div>
                                            <div className="text-sm font-bold text-slate-800 dark:text-white leading-tight">{product.name}</div>
                                            {isExpired && <span className="text-[10px] font-black text-red-500 uppercase flex items-center mt-1"><Clock size={10} className="mr-1"/> Expired</span>}
                                          </div>
                                      </div>
                                  </td>
                                  <td className="p-4 text-xs font-mono text-slate-500">{product.sku}</td>
                                  <td className="p-4"><span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300">{product.category}</span></td>
                                  <td className="p-4 text-right font-medium">{symbol}{product.price.toFixed(2)}</td>
                                  <td className="p-4 text-right"><span className={`text-xs font-bold ${margin < 15 ? 'text-red-500' : 'text-green-600'}`}>{margin.toFixed(1)}%</span></td>
                                  <td className="p-4 text-center font-black">
                                      <button onClick={() => handleOpenAdjModal(product)} className={`px-2 py-1 rounded-lg border transition ${isOut ? 'border-red-200 text-red-500 bg-red-50' : isLow ? 'border-orange-200 text-orange-600 bg-orange-50' : 'border-blue-100 text-blue-700 hover:bg-blue-50'}`}>
                                          {product.stock} <span className="text-[10px] font-normal opacity-50 uppercase">{product.unit}</span>
                                      </button>
                                  </td>
                                  <td className="p-4 text-right">
                                      <div className="flex items-center justify-end space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                          <button onClick={() => handleOpenInsights(product)} className="p-2 text-indigo-600 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg" title="Product Intelligence"><Activity size={16}/></button>
                                          <button onClick={() => handleOpenModal(product)} className="p-2 text-slate-600 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg" title="Edit"><Edit2 size={16}/></button>
                                          <button onClick={() => handleDelete(product.id)} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 rounded-lg" title="Delete"><Trash2 size={16}/></button>
                                      </div>
                                  </td>
                              </tr>
                          );
                        })
                      )}
                  </tbody>
              </table>
          </div>
      </div>

      {/* Product Insights Modal (Intelligence Hub) */}
      {selectedProductForInsights && (
        <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col animate-in zoom-in-95 duration-200">
                <div className="p-6 border-b border-slate-100 dark:border-slate-700 flex justify-between items-start bg-slate-50 dark:bg-slate-700/50 rounded-t-2xl">
                    <div className="flex items-center gap-4">
                        <div className="w-16 h-16 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black text-2xl shadow-lg shadow-indigo-500/30 overflow-hidden">
                            {selectedProductForInsights.imageUrl ? (
                                <img src={selectedProductForInsights.imageUrl} className="w-full h-full object-cover" alt="" />
                            ) : selectedProductForInsights.name.charAt(0)}
                        </div>
                        <div>
                            <h3 className="text-2xl font-black text-slate-800 dark:text-white leading-tight">{selectedProductForInsights.name}</h3>
                            <p className="text-sm font-bold text-slate-500 uppercase tracking-widest">{selectedProductForInsights.sku} • {selectedProductForInsights.category}</p>
                        </div>
                    </div>
                    <button onClick={() => setSelectedProductForInsights(null)} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full transition-colors"><X size={24}/></button>
                </div>

                <div className="flex border-b border-slate-100 dark:border-slate-700 px-6 bg-white dark:bg-slate-800">
                    {[
                        { id: 'FINANCIAL', label: 'Financial Audit', icon: DollarSign },
                        { id: 'SALES', label: 'Sold Logs', icon: ShoppingCart },
                        { id: 'RETURNS', label: 'Returned Logs', icon: RotateCcw },
                        { id: 'ADJUSTMENTS', label: 'Stock Movements', icon: ClipboardList }
                    ].map(tab => (
                        <button 
                            key={tab.id} 
                            onClick={() => setActiveLogTab(tab.id as LogTab)}
                            className={`py-4 px-6 font-black text-[10px] uppercase tracking-widest border-b-2 transition-all flex items-center gap-2 ${activeLogTab === tab.id ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
                        >
                            <tab.icon size={16}/> {tab.label}
                        </button>
                    ))}
                </div>

                <div className="flex-1 overflow-y-auto p-6 bg-slate-50/30 dark:bg-slate-900/50">
                    {activeLogTab === 'FINANCIAL' && (
                        <div className="space-y-4">
                            <div className="grid grid-cols-3 gap-4 mb-4">
                                <div className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-100 dark:border-slate-700 shadow-sm">
                                    <span className="text-[10px] font-black uppercase text-slate-400 block mb-1">Current Selling Price</span>
                                    <span className="text-xl font-black text-slate-800 dark:text-white">{symbol}{selectedProductForInsights.price.toFixed(2)}</span>
                                </div>
                                <div className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-100 dark:border-slate-700 shadow-sm">
                                    <span className="text-[10px] font-black uppercase text-slate-400 block mb-1">Current Unit Cost</span>
                                    <span className="text-xl font-black text-slate-800 dark:text-white">{symbol}{selectedProductForInsights.cost.toFixed(2)}</span>
                                </div>
                                <div className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-100 dark:border-slate-700 shadow-sm">
                                    <span className="text-[10px] font-black uppercase text-slate-400 block mb-1">Net Margin</span>
                                    <span className="text-xl font-black text-green-600">{((selectedProductForInsights.price - selectedProductForInsights.cost) / selectedProductForInsights.price * 100).toFixed(1)}%</span>
                                </div>
                            </div>
                            <table className="w-full text-left">
                                <thead className="bg-white dark:bg-slate-800 text-[10px] font-black uppercase text-slate-400 border-b dark:border-slate-700">
                                    <tr><th className="p-3">Timestamp</th><th className="p-3">Type</th><th className="p-3 text-right">Old Val</th><th className="p-3 text-right">New Val</th><th className="p-3 text-center">Change</th><th className="p-3">By User</th></tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                    {priceHistory.filter(h => h.productId === selectedProductForInsights.id).sort((a,b) => b.timestamp - a.timestamp).map(log => {
                                        const diff = log.newValue - log.oldValue;
                                        const isUp = diff > 0;
                                        return (
                                            <tr key={log.id} className="text-sm">
                                                <td className="p-3 font-medium text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
                                                <td className="p-3"><span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase ${log.type === 'PRICE' ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'}`}>{log.type}</span></td>
                                                <td className="p-3 text-right text-slate-400">{symbol}{log.oldValue.toFixed(2)}</td>
                                                <td className="p-3 text-right font-bold">{symbol}{log.newValue.toFixed(2)}</td>
                                                <td className="p-3 text-center">
                                                    <div className={`flex items-center justify-center gap-1 font-black text-xs ${isUp ? 'text-green-600' : 'text-red-600'}`}>
                                                        {isUp ? <TrendingUp size={12}/> : <TrendingDown size={12}/>}
                                                        {symbol}{Math.abs(diff).toFixed(2)}
                                                    </div>
                                                </td>
                                                <td className="p-3 text-slate-600 dark:text-slate-300 font-bold flex items-center gap-2"><div className="w-6 h-6 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center"><UserIcon size={12}/></div>{log.userName}</td>
                                            </tr>
                                        );
                                    })}
                                    {priceHistory.filter(h => h.productId === selectedProductForInsights.id).length === 0 && (
                                        <tr><td colSpan={6} className="p-8 text-center text-slate-400 italic">No financial changes recorded yet.</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    )}

                    {activeLogTab === 'SALES' && (
                        <div className="space-y-4">
                            <table className="w-full text-left">
                                <thead className="bg-white dark:bg-slate-800 text-[10px] font-black uppercase text-slate-400 border-b dark:border-slate-700">
                                    <tr><th className="p-3">Order ID</th><th className="p-3">Date</th><th className="p-3">Customer</th><th className="p-3 text-center">Qty</th><th className="p-3 text-right">Price @ Sale</th><th className="p-3 text-right">Total</th></tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                    {sales.filter(s => s.items.some(i => i.productId === selectedProductForInsights.id)).sort((a,b) => b.timestamp - a.timestamp).map(s => {
                                        const item = s.items.find(i => i.productId === selectedProductForInsights.id);
                                        return (
                                            <tr key={s.id} className="text-sm">
                                                <td className="p-3 font-mono text-xs text-blue-600 font-bold">#{s.id.split('-')[1]}</td>
                                                <td className="p-3 text-slate-500">{new Date(s.timestamp).toLocaleDateString()}</td>
                                                <td className="p-3 font-bold text-slate-700 dark:text-slate-200">{s.customerName || 'Guest'}</td>
                                                <td className="p-3 text-center font-black">{item?.quantity} <span className="text-[10px] opacity-40">{item?.unit}</span></td>
                                                <td className="p-3 text-right text-slate-500">{symbol}{item?.priceAtSale.toFixed(2)}</td>
                                                <td className="p-3 text-right font-black">{symbol}{(item!.quantity * item!.priceAtSale).toFixed(2)}</td>
                                            </tr>
                                        );
                                    })}
                                    {sales.filter(s => s.items.some(i => i.productId === selectedProductForInsights.id)).length === 0 && (
                                        <tr><td colSpan={6} className="p-8 text-center text-slate-400 italic">This product hasn't been sold yet.</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    )}

                    {activeLogTab === 'RETURNS' && (
                        <div className="space-y-4">
                             <table className="w-full text-left">
                                <thead className="bg-white dark:bg-slate-800 text-[10px] font-black uppercase text-slate-400 border-b dark:border-slate-700">
                                    <tr><th className="p-3">Return ID</th><th className="p-3">Date</th><th className="p-3 text-center">Qty Returned</th><th className="p-3">Reason</th><th className="p-3 text-center">Restocked?</th><th className="p-3 text-right">Refund Amt</th></tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                    {returns.filter(r => r.items.some(i => i.productId === selectedProductForInsights.id)).sort((a,b) => b.timestamp - a.timestamp).map(r => {
                                        const rItem = r.items.find(i => i.productId === selectedProductForInsights.id);
                                        return (
                                            <tr key={r.id} className="text-sm">
                                                <td className="p-3 font-mono text-xs text-red-600 font-bold">#{r.id.split('-')[1]}</td>
                                                <td className="p-3 text-slate-500">{new Date(r.timestamp).toLocaleDateString()}</td>
                                                <td className="p-3 text-center font-black text-red-600">{rItem?.quantity}</td>
                                                <td className="p-3 text-slate-600 dark:text-slate-300 italic">"{rItem?.reason}"</td>
                                                <td className="p-3 text-center">{rItem?.restock ? <span className="text-green-600 font-black text-xs uppercase">Yes</span> : <span className="text-slate-400 font-black text-xs uppercase">No</span>}</td>
                                                <td className="p-3 text-right font-black text-red-600">{symbol}{rItem?.refundAmount.toFixed(2)}</td>
                                            </tr>
                                        );
                                    })}
                                    {returns.filter(r => r.items.some(i => i.productId === selectedProductForInsights.id)).length === 0 && (
                                        <tr><td colSpan={6} className="p-8 text-center text-slate-400 italic">No returns recorded for this product.</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    )}

                    {activeLogTab === 'ADJUSTMENTS' && (
                        <div className="space-y-4">
                            <table className="w-full text-left">
                                <thead className="bg-white dark:bg-slate-800 text-[10px] font-black uppercase text-slate-400 border-b dark:border-slate-700">
                                    <tr><th className="p-3">Timestamp</th><th className="p-3">Action</th><th className="p-3 text-center">Amount</th><th className="p-3 text-right">Prev</th><th className="p-3 text-right">New</th><th className="p-3">Reason / User</th></tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                    {stockAdjustments.filter(a => a.productId === selectedProductForInsights.id).sort((a,b) => b.timestamp - a.timestamp).map(a => (
                                        <tr key={a.id} className="text-sm">
                                            <td className="p-3 text-slate-500">{new Date(a.timestamp).toLocaleString()}</td>
                                            <td className="p-3"><span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase ${a.type === 'ADD' ? 'bg-green-100 text-green-700' : a.type === 'REMOVE' ? 'bg-red-100 text-red-700' : 'bg-slate-100 text-slate-700'}`}>{a.type}</span></td>
                                            <td className={`p-3 text-center font-black ${a.type === 'ADD' ? 'text-green-600' : a.type === 'REMOVE' ? 'text-red-600' : 'text-slate-800'}`}>{a.type === 'ADD' ? '+' : a.type === 'REMOVE' ? '-' : ''}{a.quantity}</td>
                                            <td className="p-3 text-right text-slate-400">{a.previousStock}</td>
                                            <td className="p-3 text-right font-black">{a.newStock}</td>
                                            <td className="p-3">
                                                <div className="font-bold text-slate-700 dark:text-slate-200">{a.reason}</div>
                                                <div className="text-[10px] text-slate-400 uppercase tracking-tighter">By {a.userName}</div>
                                            </td>
                                        </tr>
                                    ))}
                                     {stockAdjustments.filter(a => a.productId === selectedProductForInsights.id).length === 0 && (
                                        <tr><td colSpan={6} className="p-8 text-center text-slate-400 italic">No manual adjustments recorded.</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    )}
                </div>

                <div className="p-6 border-t border-slate-100 dark:border-slate-700 bg-white dark:bg-slate-800 rounded-b-2xl flex justify-end">
                    <button onClick={() => setSelectedProductForInsights(null)} className="px-8 py-3 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-xl font-black transition-transform active:scale-95 shadow-xl">Close Intelligence View</button>
                </div>
            </div>
        </div>
      )}

      {isModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col animate-in zoom-in-95 duration-200">
                  <div className="p-5 border-b border-slate-100 dark:border-slate-700 flex justify-between items-center bg-slate-50 dark:bg-slate-700/50 rounded-t-2xl">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-blue-600 text-white rounded-lg"><Package size={20}/></div>
                        <h3 className="font-bold text-lg">{editingProduct ? 'Edit Product Details' : 'Create New Product'}</h3>
                    </div>
                    <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full transition-colors"><X size={20}/></button>
                  </div>
                  <div className="flex-1 overflow-y-auto p-8">
                      <div className="flex flex-col lg:flex-row gap-10">
                          {/* Image Selector Area */}
                          <div className="w-full lg:w-72 shrink-0">
                              <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 tracking-widest">Product Image</label>
                              <div className="relative group">
                                  <div className="aspect-square w-full rounded-2xl bg-slate-100 dark:bg-slate-700 border-2 border-dashed border-slate-300 dark:border-slate-600 flex flex-col items-center justify-center overflow-hidden transition-all group-hover:border-blue-500 group-hover:bg-blue-50 dark:group-hover:bg-blue-900/10">
                                      {formData.imageUrl ? (
                                          <img src={formData.imageUrl} className="w-full h-full object-cover" alt="Preview" />
                                      ) : (
                                          <>
                                              <ImageIcon className="text-slate-400 mb-2" size={48} />
                                              <span className="text-xs font-bold text-slate-500">No Image</span>
                                          </>
                                      )}
                                      <label className="absolute inset-0 cursor-pointer flex items-center justify-center opacity-0 group-hover:opacity-100 bg-black/40 transition-opacity">
                                          <div className="flex flex-col items-center text-white">
                                              <Upload size={24} className="mb-1" />
                                              <span className="text-xs font-black uppercase tracking-tighter">Change Image</span>
                                          </div>
                                          <input type="file" accept="image/*" className="hidden" onChange={handleImageUpload} />
                                      </label>
                                  </div>
                                  {formData.imageUrl && (
                                      <button 
                                        onClick={() => setFormData({...formData, imageUrl: ''})}
                                        className="absolute -top-2 -right-2 p-1.5 bg-red-500 text-white rounded-full shadow-lg hover:bg-red-600 transition-transform hover:scale-110"
                                      >
                                          <X size={14}/>
                                      </button>
                                  )}
                              </div>
                              <p className="text-[10px] text-slate-400 mt-3 italic text-center">Images are stored locally as base64 strings.</p>
                          </div>

                          {/* Details Form Area */}
                          <div className="flex-1 space-y-6">
                              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                  <div className="col-span-2">
                                      <label className="block text-[10px] font-black uppercase text-slate-400 mb-1 tracking-widest flex items-center">
                                          <Tags size={12} className="mr-1.5" /> Product Name <span className="text-red-500 ml-1">*</span>
                                      </label>
                                      <input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full p-3 border-2 rounded-xl bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white focus:border-blue-500 outline-none transition-colors" placeholder="e.g. Wireless Mouse X1" />
                                  </div>
                                  <div>
                                      <label className="block text-[10px] font-black uppercase text-slate-400 mb-1 tracking-widest">SKU / Barcode</label>
                                      <input type="text" value={formData.sku} onChange={e => setFormData({...formData, sku: e.target.value})} className="w-full p-3 border-2 rounded-xl bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white focus:border-blue-500 outline-none transition-colors" placeholder="W-12345" />
                                  </div>
                                  <div>
                                      <label className="block text-[10px] font-black uppercase text-slate-400 mb-1 tracking-widest flex items-center">
                                          <Layers size={12} className="mr-1.5" /> Category <span className="text-red-500 ml-1">*</span>
                                      </label>
                                      <input type="text" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full p-3 border-2 rounded-xl bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white focus:border-blue-500 outline-none transition-colors" placeholder="Electronics" />
                                  </div>
                                  <div>
                                      <label className="block text-[10px] font-black uppercase text-slate-400 mb-1 tracking-widest">Unit of Measure</label>
                                      <input type="text" value={formData.unit} onChange={e => setFormData({...formData, unit: e.target.value})} className="w-full p-3 border-2 rounded-xl bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white focus:border-blue-500 outline-none transition-colors" placeholder="pcs, kg, box..." />
                                  </div>
                                  <div>
                                      <label className="block text-[10px] font-black uppercase text-slate-400 mb-1 tracking-widest">Initial Stock</label>
                                      <input type="number" disabled={!!editingProduct} value={formData.stock} onChange={e => setFormData({...formData, stock: parseFloat(e.target.value)})} className="w-full p-3 border-2 rounded-xl bg-slate-50 dark:bg-slate-900 border-slate-100 dark:border-slate-700 dark:text-white focus:border-blue-500 outline-none transition-colors" />
                                  </div>
                              </div>

                              <div className="bg-slate-50 dark:bg-slate-900/50 p-5 rounded-2xl border border-slate-100 dark:border-slate-700 space-y-5">
                                  <h4 className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em]">Financial Details</h4>
                                  <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                      <div>
                                          <label className="block text-xs font-bold text-slate-600 dark:text-slate-300 mb-1.5">Purchase Cost ({symbol})</label>
                                          <div className="relative">
                                              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-bold">{symbol}</span>
                                              <input type="number" value={formData.cost} onChange={e => setFormData({...formData, cost: parseFloat(e.target.value)})} className="w-full p-3 pl-8 border-2 rounded-xl bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white focus:border-emerald-500 outline-none transition-colors" />
                                          </div>
                                      </div>
                                      <div>
                                          <label className="block text-xs font-bold text-slate-600 dark:text-slate-300 mb-1.5">Selling Price ({symbol})</label>
                                          <div className="relative">
                                              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-bold">{symbol}</span>
                                              <input type="number" value={formData.price} onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})} className="w-full p-3 pl-8 border-2 rounded-xl bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white focus:border-blue-500 outline-none transition-colors" />
                                          </div>
                                      </div>
                                  </div>
                              </div>

                              <div className="col-span-2">
                                  <div className="flex justify-between items-center mb-1.5">
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest">Marketing Description</label>
                                    <button 
                                        onClick={handleGenerateDescription} 
                                        disabled={isGeneratingDescription || !formData.name}
                                        className="flex items-center gap-1.5 px-2 py-1 bg-purple-100 dark:bg-purple-900/30 rounded text-[10px] font-black uppercase text-purple-600 hover:text-purple-700 disabled:opacity-50 transition"
                                    >
                                        <Sparkles size={12} className={isGeneratingDescription ? 'animate-spin' : ''}/>
                                        {isGeneratingDescription ? 'Writing...' : 'Write with AI'}
                                    </button>
                                  </div>
                                  <textarea value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full p-3 border-2 rounded-xl bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white focus:border-blue-500 outline-none transition-colors h-24 resize-none" placeholder="Provide product details for receipts or sales catalogs..."></textarea>
                              </div>

                              <div className="flex flex-col md:flex-row items-center justify-between p-4 bg-blue-50/50 dark:bg-blue-900/10 rounded-xl border border-blue-100 dark:border-blue-800 gap-4">
                                  <div className="flex items-center gap-3">
                                    <div className="relative inline-flex items-center cursor-pointer">
                                        <input type="checkbox" id="decimal" checked={formData.allowDecimal} onChange={e => setFormData({...formData, allowDecimal: e.target.checked})} className="sr-only peer"/>
                                        <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer dark:bg-slate-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all dark:border-gray-600 peer-checked:bg-blue-600"></div>
                                        <label htmlFor="decimal" className="ml-3 text-sm font-bold text-slate-700 dark:text-slate-300">Allow Decimal Quantities</label>
                                    </div>
                                  </div>
                                  <div className="text-[10px] text-slate-500 flex items-center font-medium"><Info size={14} className="mr-1.5 text-blue-500"/> Enable this for items sold by weight (Kg) or length (M).</div>
                              </div>
                          </div>
                      </div>
                  </div>
                  <div className="p-4 border-t border-slate-100 dark:border-slate-700 flex justify-end gap-3 bg-slate-50 dark:bg-slate-800/50 rounded-b-2xl">
                      <button onClick={() => setIsModalOpen(false)} className="px-6 py-2.5 text-sm font-bold text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 transition">Discard Changes</button>
                      <button onClick={handleSave} className="px-12 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-black shadow-lg shadow-blue-500/20 transition-all transform hover:-translate-y-0.5 active:translate-y-0">
                          {editingProduct ? 'Update Product' : 'Create Product'}
                      </button>
                  </div>
              </div>
          </div>
      )}

      {isAdjModalOpen && selectedProductForAdj && (
          <div className="fixed inset-0 bg-black/50 z-[120] flex items-center justify-center p-4 backdrop-blur-sm">
              <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl w-full max-sm:w-full max-w-sm p-6 animate-in zoom-in-95 duration-200 overflow-hidden relative">
                  <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/5 rounded-full -translate-y-12 translate-x-12 blur-2xl pointer-events-none"></div>
                  <h3 className="text-xl font-black text-slate-800 dark:text-white mb-1 flex items-center"><Scale size={24} className="mr-2 text-blue-600"/> Adjust Stock</h3>
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-6">{selectedProductForAdj.name}</p>

                  <div className="space-y-6">
                      <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-xl">
                          {['ADD', 'REMOVE', 'SET'].map(type => (
                              <button key={type} onClick={() => setAdjType(type as AdjustmentType)} className={`flex-1 py-2 text-[10px] font-black rounded-lg transition-all ${adjType === type ? 'bg-white dark:bg-slate-600 shadow-md text-blue-600 transform scale-105' : 'text-slate-500 hover:text-slate-700'}`}>{type}</button>
                          ))}
                      </div>

                      <div className="relative">
                        <input type="number" step={selectedProductForAdj.allowDecimal ? "0.001" : "1"} value={adjQuantity} onChange={e => setAdjQuantity(parseFloat(e.target.value) || 0)} className="w-full p-4 text-center text-5xl font-black bg-slate-50 dark:bg-slate-900 border-2 border-slate-100 dark:border-slate-700 rounded-2xl outline-none focus:border-blue-500 transition-all dark:text-white" autoFocus onFocus={(e) => e.target.select()}/>
                        <span className="absolute bottom-2 right-4 text-[10px] font-black text-slate-400 uppercase tracking-tighter">{selectedProductForAdj.unit}</span>
                      </div>

                      <div className="space-y-1">
                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest">Adjustment Reason</label>
                        <select value={adjReason} onChange={e => setAdjReason(e.target.value)} className="w-full p-3 border-2 rounded-xl text-sm font-bold bg-white dark:bg-slate-700 border-slate-100 dark:border-slate-600 dark:text-white outline-none focus:border-blue-500">
                            <option>Stock Count Correction</option>
                            <option>Damage / Wastage</option>
                            <option>Received Shipment</option>
                            <option>Product Return</option>
                        </select>
                      </div>
                  </div>

                  <div className="mt-8 flex gap-3">
                      <button onClick={() => setIsAdjModalOpen(false)} className="flex-1 py-3 text-slate-500 font-bold hover:bg-slate-50 rounded-xl transition">Discard</button>
                      <button onClick={handleSubmitAdjustment} className="flex-[2] py-3 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-xl shadow-lg shadow-blue-500/20 transition-all transform hover:-translate-y-0.5">Confirm Changes</button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Inventory;

export enum UserRole {
  SUPER_ADMIN = 'SUPER_ADMIN',
  ADMIN = 'ADMIN',
  CASHIER = 'CASHIER',
}

export type Permission = 
  | 'VIEW_DASHBOARD'
  | 'MANAGE_INVENTORY'
  | 'POS'
  | 'VIEW_SALES_HISTORY'
  | 'MANAGE_CUSTOMERS'
  | 'MANAGE_USERS'
  | 'MANAGE_SETTINGS'
  | 'MANAGE_PURCHASE_ORDERS';

export interface User {
  id: string;
  name: string;
  role: UserRole;
  email: string;
  avatar?: string;
  password?: string;
  permissions: Permission[];
}

export interface ToastMessage {
  id: string;
  message: string;
  type: 'SUCCESS' | 'ERROR' | 'INFO';
}

export interface CreditTerm {
  id: string;
  name: string;
  days: number;
  rate: number;
}

export interface StoreSettings {
  storeName: string;
  storeAddress: string;
  storePhone: string;
  storeEmail: string;
  storeLogo?: string;
  taxRate: number;
  taxName: string;
  taxType: 'INCLUSIVE' | 'EXCLUSIVE'; 
  currency: string;
  receiptHeader?: string;
  receiptFooter?: string;
  creditMarkupRate?: number;
  creditTerms: CreditTerm[];
}

