  name: string;
  sku: string;
  barcode?: string;
  brand?: string;
  supplier?: string;
  price: number;
  cost: number;
  stock: number;
  unit?: string; 
  category: string;
  description?: string;
  imageUrl?: string;
  minStockLevel: number;
  stockExpiryDate?: string;
  allowDecimal?: boolean;
  isActive?: boolean;
}

export interface Customer {
  id: string;
  name: string;
  email?: string;
  phone?: string;
  totalSpent: number;
  visitCount: number;
  lastVisit?: number;
  storeCredit: number;
  type: 'MEMBER' | 'WALK_IN';
  creditLimit?: number;
}

export interface CustomerSegment {
  id: string;
  name: string;
  description?: string;
  criteria: {
    minSpent?: number;
    maxSpent?: number;
    minVisits?: number;
    maxVisits?: number;
    daysSinceLastVisit?: number; 
  };
}

