  supplier: string;
  status: PurchaseOrderStatus;
  orderDate: number;
  expectedDate?: string;
  items: PurchaseOrderItem[];
  totalCost: number;
}

export type AdjustmentType = 'ADD' | 'REMOVE' | 'SET';

export interface StockAdjustment {
  id: string;
  productId: string;
  productName: string;
  userId: string;
  userName: string;
  timestamp: number;
  type: AdjustmentType;
  quantity: number; 
  previousStock: number;
  newStock: number;
  reason: string;
  notes?: string;
}

