  id: string;
  customerId: string;
  customerName: string;
  amount: number;
  type: 'ADD' | 'DEDUCT';
  newBalance: number;
  timestamp: number;
  userId: string;
  userName: string;
  reason?: string;
  paymentMethod?: 'CASH' | 'CARD' | 'DIGITAL';
}

export interface ReturnItem {
  productId: string;
  productName: string;
  quantity: number;
  refundAmount: number;
  reason: string;
  restock: boolean;
}

export interface ReturnTransaction {
  id: string;
  originalSaleId: string;
  timestamp: number;
  items: ReturnItem[];
  totalRefund: number;
  refundMethod: 'CASH' | 'CARD' | 'DIGITAL' | 'STORE_CREDIT';
  cashierId: string;
  customerId?: string;
}

export interface HoldTransaction {
  id: string;
  items: CartItem[];
  customer: Customer; 
  timestamp: number;
  durationMinutes: number;
  expiryTime: number;
  note?: string;
  cashierId: string;
}

export interface PriceHistory {
  id: string;
  productId: string;
  type: 'PRICE' | 'COST'; 
  oldValue: number;
  newValue: number;
  userId: string;
  userName: string;
  timestamp: number;
}

import React, { useState, useMemo } from 'react';
import { Product, StockAdjustment, AdjustmentType, User, ReturnTransaction, Customer, Sale, PriceHistory } from '../types';
import { suggestRestock, generateProductDescription } from '../services/geminiService';
import { 
  Plus, Edit2, Trash2, Search, Wand2, X, 
  FileSpreadsheet, Package, DollarSign, AlertTriangle, Scale, 
  ArrowUp, ArrowDown, ChevronsUpDown, TrendingUp, 
  TrendingDown, Clock, User as UserIcon, Sparkles, CheckSquare, 
  Square, Trash, Info, Activity, ShoppingCart, RotateCcw, ClipboardList,
  ArrowRight, History, Upload, Image as ImageIcon, Tags, Layers, 
  Barcode, Factory, Truck, Power, ChevronRight, ListOrdered
} from 'lucide-react';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  stockAdjustments: StockAdjustment[];
  onAdjustStock: (adjustment: StockAdjustment) => void;
  onBulkAdjustStock: (adjustments: StockAdjustment[]) => void;
  currentUser: User;
  currency: string;
  showToast: (message: string, type: 'SUCCESS' | 'ERROR' | 'INFO') => void;
  returns: ReturnTransaction[];
  customers: Customer[];
  sales: Sale[];
  priceHistory: PriceHistory[];
  onLogPriceChange: (log: PriceHistory) => void;
}

type SortField = 'name' | 'sku' | 'category' | 'price' | 'stock' | 'stockExpiryDate' | 'cost' | 'margin';
type SortDirection = 'asc' | 'desc';
type LogTab = 'FINANCIAL' | 'SALES' | 'RETURNS' | 'ADJUSTMENTS';

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, stockAdjustments, onAdjustStock, onBulkAdjustStock, currentUser, currency, showToast, returns, customers, sales, priceHistory, onLogPriceChange }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [selectedProductForInsights, setSelectedProductForInsights] = useState<Product | null>(null);
  const [activeLogTab, setActiveLogTab] = useState<LogTab>('FINANCIAL');

  const [filterCategory, setFilterCategory] = useState('ALL');
  const [filterStockStatus, setFilterStockStatus] = useState<'ALL' | 'LOW' | 'OUT' | 'IN' | 'EXPIRED'>('ALL');
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');

  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [isLoadingAi, setIsLoadingAi] = useState(false);
  const [isGeneratingDescription, setIsGeneratingDescription] = useState(false);
  const [isAdjModalOpen, setIsAdjModalOpen] = useState(false);
  const [selectedProductForAdj, setSelectedProductForAdj] = useState<Product | null>(null);
  const [adjType, setAdjType] = useState<AdjustmentType>('ADD');
  const [adjQuantity, setAdjQuantity] = useState(0);
  const [adjReason, setAdjReason] = useState('Stock Count Correction');
  const [adjNotes, setAdjNotes] = useState('');

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', barcode: '', brand: '', supplier: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false, isActive: true
  });

  const symbol = useMemo(() => {
    switch(currency) {
      case 'PHP': return '₱';
      case 'EUR': return '€';
      case 'GBP': return '£';
      default: return '$';
    }
  }, [currency]);

  const formatCurrency = (val: number) => val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const formatNumber = (val: number) => val.toLocaleString('en-US', { maximumFractionDigits: 3 });

  const categories = useMemo(() => {
      const cats = new Set(products.map(p => p.category).filter(Boolean));
      return ['ALL', ...Array.from(cats).sort()];
  }, [products]);

  const getDaysUntilExpiry = (dateString?: string) => {
    if (!dateString) return null;
    const [year, month, day] = dateString.split('-').map(Number);
    const expiry = new Date(year, month - 1, day);
    const diffTime = expiry.getTime() - new Date().setHours(0,0,0,0);
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const processedProducts = useMemo(() => {
      let filtered = products.filter(p => 
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        p.sku.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.barcode?.toLowerCase().includes(searchTerm.toLowerCase())
      );
      if (filterCategory !== 'ALL') filtered = filtered.filter(p => p.category === filterCategory);
      if (filterStockStatus !== 'ALL') {
          if (filterStockStatus === 'OUT') filtered = filtered.filter(p => p.stock === 0);
          if (filterStockStatus === 'LOW') filtered = filtered.filter(p => p.stock > 0 && p.stock <= p.minStockLevel);
          if (filterStockStatus === 'IN') filtered = filtered.filter(p => p.stock > p.minStockLevel);
          if (filterStockStatus === 'EXPIRED') filtered = filtered.filter(p => (getDaysUntilExpiry(p.stockExpiryDate) || 0) < 0);
      }
      return filtered.sort((a, b) => {
          let valA: any = a[sortField];
          let valB: any = b[sortField];
          if (sortField === 'margin') {
              valA = a.price > 0 ? ((a.price - a.cost) / a.price) : -999;
              valB = b.price > 0 ? ((b.price - b.cost) / b.price) : -999;
          }
          if (typeof valA === 'string') return sortDirection === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
          return sortDirection === 'asc' ? (valA < valB ? -1 : 1) : (valB < valA ? -1 : 1);
      });
  }, [products, searchTerm, filterCategory, filterStockStatus, sortField, sortDirection]);

  const toggleSelectAll = () => {
    if (selectedIds.length === processedProducts.length) setSelectedIds([]);
    else setSelectedIds(processedProducts.map(p => p.id));
  };

  const toggleSelect = (id: string) => {
    setSelectedIds(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleBulkDelete = () => {
    if (!window.confirm(`Are you sure you want to delete ${selectedIds.length} products?`)) return;
    setProducts(prev => prev.filter(p => !selectedIds.includes(p.id)));
    setSelectedIds([]);
    showToast(`${selectedIds.length} products removed.`, 'INFO');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerateDescription = async () => {
    if (!formData.name || !formData.category) {
        showToast("Enter name and category first.", "INFO");
        return;
    }
    setIsGeneratingDescription(true);
    try {
        const desc = await generateProductDescription(formData.name, formData.category);
        setFormData(prev => ({ ...prev, description: desc }));
        showToast("Description generated with AI.", "SUCCESS");
    } catch (e) {
        showToast("AI Generation failed.", "ERROR");
    } finally {
        setIsGeneratingDescription(false);
    }
  };

  const exportToExcel = () => {
    const headers = [
      "Product Name", "SKU", "Barcode", "Brand", "Supplier", "Category", "Cost Price", "Selling Price", "Stock", "Status"
    ];
    let html = `<html><head><style>table { border-collapse: collapse; } th, td { border: 1px solid #ccc; padding: 5px; }</style></head><body><table><thead><tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr></thead><tbody>`;
    processedProducts.forEach(p => {
        html += `<tr><td>${p.name}</td><td>${p.sku}</td><td>${p.barcode || ''}</td><td>${p.brand || ''}</td><td>${p.supplier || ''}</td><td>${p.category}</td><td>${p.cost}</td><td>${p.price}</td><td>${p.stock}</td><td>${p.isActive ? 'Active' : 'Inactive'}</td></tr>`;
    });
    html += `</tbody></table></body></html>`;
    const blob = new Blob([html], { type: 'application/vnd.ms-excel' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `Inventory_Report_${new Date().getTime()}.xls`;
    link.click();
    showToast("Exported Excel.", "SUCCESS");
  };

  const handleOpenModal = (product?: Product) => {
    if (product) { setEditingProduct(product); setFormData(product); }
    else { setEditingProduct(null); setFormData({ name: '', sku: '', barcode: '', brand: '', supplier: '', price: 0, cost: 0, stock: 0, unit: 'pcs', category: '', description: '', minStockLevel: 5, stockExpiryDate: '', imageUrl: '', allowDecimal: false, isActive: true }); }
    setIsModalOpen(true);
  };

  const handleOpenAdjModal = (product: Product) => { setSelectedProductForAdj(product); setAdjType('ADD'); setAdjQuantity(0); setAdjReason('Stock Count Correction'); setAdjNotes(''); setIsAdjModalOpen(true); };

  const handleOpenInsights = (product: Product) => {
    setSelectedProductForInsights(product);
    setActiveLogTab('FINANCIAL');
  };

  const handleSave = () => {
    if (!formData.name || !formData.price || !formData.category) { showToast("Name, Category, and Price are required.", 'ERROR'); return; }
    if (editingProduct) {
      if (formData.price !== editingProduct.price) onLogPriceChange({ id: `ph-${Date.now()}-p`, productId: editingProduct.id, type: 'PRICE', oldValue: editingProduct.price, newValue: formData.price || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      if (formData.cost !== editingProduct.cost) onLogPriceChange({ id: `ph-${Date.now()}-c`, productId: editingProduct.id, type: 'COST', oldValue: editingProduct.cost, newValue: formData.cost || 0, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now() });
      setProducts(prev => prev.map(p => p.id === editingProduct.id ? { ...p, ...formData } as Product : p));
      showToast("Product updated.", 'SUCCESS');
    } else {
      setProducts(prev => [...prev, { id: `p-${Date.now()}`, ...formData as Product }]);
      showToast("Product added.", 'SUCCESS');
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => { if (window.confirm('Delete this product?')) { setProducts(prev => prev.filter(p => p.id !== id)); showToast("Product deleted.", 'INFO'); } };

  const handleSubmitAdjustment = () => {
      if (!selectedProductForAdj) return;
      let newStock = selectedProductForAdj.stock;
      if (adjType === 'ADD') newStock = parseFloat((selectedProductForAdj.stock + adjQuantity).toFixed(3));
      if (adjType === 'REMOVE') newStock = parseFloat((selectedProductForAdj.stock - adjQuantity).toFixed(3));
      if (adjType === 'SET') newStock = adjQuantity;
      if (newStock < 0) { showToast("Stock cannot be negative.", 'ERROR'); return; }
      onAdjustStock({ id: `adj-${Date.now()}`, productId: selectedProductForAdj.id, productName: selectedProductForAdj.name, userId: currentUser.id, userName: currentUser.name, timestamp: Date.now(), type: adjType, quantity: adjQuantity, previousStock: selectedProductForAdj.stock, newStock, reason: adjReason, notes: adjNotes });
      setIsAdjModalOpen(false);
  };

  const handleRestockCheck = async () => { setIsLoadingAi(true); const suggestions = await suggestRestock(products); setAiSuggestions(suggestions); setIsLoadingAi(false); showToast("AI analysis complete.", 'SUCCESS'); };

  const handleSort = (field: SortField) => { if (sortField === field) setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc'); else { setSortField(field); setSortDirection('asc'); } };

  const HeaderCell = ({ field, label, align = 'left' }: { field: SortField, label: string, align?: 'left' | 'center' | 'right' }) => (
      <th className={`p-4 text-xs font-semibold text-slate-600 dark:text-slate-300 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700 transition select-none text-${align}`} onClick={() => handleSort(field)}>
          <div className={`flex items-center ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
              {label}{sortField === field ? (sortDirection === 'asc' ? <ArrowUp size={14} className="ml-1 text-blue-500" /> : <ArrowDown size={14} className="ml-1 text-blue-500" />) : <ChevronsUpDown size={14} className="ml-1 text-slate-400" />}
          </div>
      </th>
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-800 dark:text-white">Inventory</h2>
          <p className="text-slate-500 dark:text-slate-400 text-sm mt-1">Manage items, track health, and audit individual product lifecycles.</p>
        </div>
        <div className="flex space-x-2">
            <button onClick={() => handleOpenModal()} className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-xl flex items-center transition shadow-lg shadow-blue-500/20 font-black tracking-tight">
                <Plus size={18} className="mr-2" /> Add Product
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center group hover:border-blue-500 transition-colors">
              <div className="p-3 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-xl mr-4 group-hover:bg-blue-600 group-hover:text-white transition-all"><Package size={24}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase tracking-wider">Total Units</p><p className="text-2xl font-black text-slate-800 dark:text-white">{formatNumber(products.reduce((acc, p) => acc + p.stock, 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center group hover:border-emerald-500 transition-colors">
              <div className="p-3 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 rounded-xl mr-4 group-hover:bg-emerald-600 group-hover:text-white transition-all"><DollarSign size={24}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase tracking-wider">Asset Value</p><p className="text-2xl font-black text-slate-800 dark:text-white">{symbol}{formatCurrency(products.reduce((acc, p) => acc + (p.cost * p.stock), 0))}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center group hover:border-orange-500 transition-colors">
              <div className="p-3 bg-orange-100 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 rounded-xl mr-4 group-hover:bg-orange-600 group-hover:text-white transition-all"><AlertTriangle size={24}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase tracking-wider">Low Stock</p><p className="text-2xl font-black text-slate-800 dark:text-white">{products.filter(p => p.stock <= p.minStockLevel && p.stock > 0).length}</p></div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-center group hover:border-red-500 transition-colors">
              <div className="p-3 bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 rounded-xl mr-4 group-hover:bg-red-600 group-hover:text-white transition-all"><Clock size={24}/></div>
              <div><p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase tracking-wider">Expired / Out</p><p className="text-2xl font-black text-slate-800 dark:text-white">{products.filter(p => p.stock === 0 || (getDaysUntilExpiry(p.stockExpiryDate) || 0) < 0).length}</p></div>
          </div>
      </div>

      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
          <div className="flex flex-col md:flex-row gap-4 w-full xl:w-auto items-center">
              <button onClick={toggleSelectAll} className="p-2 rounded-lg bg-slate-50 dark:bg-slate-700 hover:bg-slate-100 dark:hover:bg-slate-600 transition border border-slate-200 dark:border-slate-600">
                  {selectedIds.length === processedProducts.length && processedProducts.length > 0 ? <CheckSquare size={20} className="text-blue-500"/> : <Square size={20} className="text-slate-400"/>}
              </button>
              <div className="relative w-full md:w-64">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400" size={18} />
                <input type="text" placeholder="Search products, SKU, barcode..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"/>
              </div>
              <div className="flex gap-2 w-full md:w-auto">
                  <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className="flex-1 md:w-32 pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-xs font-bold text-slate-700 dark:text-slate-200 outline-none">
                      {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  <select value={filterStockStatus} onChange={(e) => setFilterStockStatus(e.target.value as any)} className="flex-1 md:w-40 pl-3 pr-8 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-700 text-xs font-bold text-slate-700 dark:text-slate-200 outline-none">
                      <option value="ALL">All Stock Health</option>
                      <option value="IN">In Stock (Healthy)</option>
                      <option value="LOW">Low Stock Warning</option>
                      <option value="OUT">Out of Stock</option>
                      <option value="EXPIRED">Expired Items</option>
                  </select>
              </div>
          </div>
          <div className="flex flex-wrap gap-2 w-full xl:w-auto justify-end">
              {selectedIds.length > 0 && (
                <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-lg mr-2">
                    <button onClick={handleBulkDelete} className="px-3 py-1.5 bg-red-600 text-white rounded-md text-xs font-bold hover:bg-red-700 flex items-center shadow-md">
                        <Trash size={14} className="mr-1.5"/> Delete {selectedIds.length}
                    </button>
                    <button onClick={() => setSelectedIds([])} className="p-1.5 ml-1 text-slate-400 hover:text-slate-600"><X size={16}/></button>
                </div>
              )}
              <button onClick={exportToExcel} className="px-4 py-2 bg-emerald-600 text-white rounded-lg text-sm font-medium hover:bg-emerald-700 transition flex items-center shadow-sm">
                  <FileSpreadsheet size={16} className="mr-2"/> Excel Report
              </button>
              <button onClick={handleRestockCheck} disabled={isLoadingAi} className="px-4 py-2 bg-purple-600 text-white rounded-lg text-sm font-medium hover:bg-purple-700 transition flex items-center shadow-sm">
                  <Wand2 size={16} className={`mr-2 ${isLoadingAi ? 'animate-spin' : ''}`}/> AI Audit
